(window.GIM_TS=window.GIM_TS||{})["Yevamot.7"]={"from":168,"a":[["\u0003תרומה לכהן, ומעשר ראשון ללוי\u0004 בלבד, אלו \u0003דברי ר' מאיר. ר' אלעזר בן עזריה מתירו לכהן,\u0004 שאף לכהן (שכן גם הוא משבט לוי) מותר לאכול מעשר ראשון. ותוהים: \u0003מתירו?! מכלל\u0004 הדברים אתה שומע \u0003דאיכא מאן\u0004 \u0005[שיש מי]\u0006 ש\u0003אסר\u0004 על כהן לאכול מעשר? והלא כהן לוי הוא ואינו נקרא זר! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 כך: \u0003נותנו אף לכהן,\u0004 שאין חייבים לתת דווקא רק ללוי, אלא אף כהנים בכלל זה.","ומבררים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' מאיר? אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבה משמיה דגמרא\u0004 \u0005[בשם המסורת\u0006 המקובלת\u0005],\u0006 נאמר: \u0003\"כי את מעשר בני ישראל אשר ירימו לה' תרומה\u0004 נתתי ללוים לנחלה\u0003\"\u0004 (במדבר יח, כד), ומאחר שבפסוק זה המעשר קרוי תרומה, למדים: \u0003מה תרומה אסורה לזרים, אף מעשר ראשון אסור לזרים,\u0004 שאינם לויים. ויש לשאול: \u0003אי\u0004 \u0005[או]\u0006 \u0003מה תרומה חייבין עליו מיתה וחומש\u0004 אם אכלוה זרים — \u0003אף מעשר\u0004 כן יהיה דינו ויהיו \u0003חייבין עליו מיתה וחומש?\u0004","\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ומתו בו כי יחללהו\"\u0004 (ויקרא כב ט), ונאמר: \u0003\"ויסף חמשיתו עליו\"\u0004 (שם יד), ומדיוק הלשון אנחנו למדים שבא הכתוב להדגיש: \u0003\"בו\" — ולא במעשר,\u0004 וכן: \u0003\"עליו\" — ולא על מעשר.\u0004 ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 החולקים כיצד מפרשים הם השוואה זו שבפסוק — לא לענין היתר אכילה, אלא ללמד: \u0003מה תרומה טובלת,\u0004 שתבואה שלא הפרישו ממנה תרומה היא טבל, ואסורה באכילה, \u0003אף מעשר ראשון נמי\u0004 \u0005[גם כן]\u0006 \u0003טובל.\u0004","\u0003וכדתניא\u0004 \u0005[וכפי ש\u0006אכן \u0005שנינו\u0006 בברייתא\u0005]\u0006 \u0003ר' יוסי אומר: יכול לא יהא חייב אלא על טבל שלא הורם ממנו\u0004 תרומות ומעשרות \u0003כל עיקר,\u0004 אבל אם \u0003הורם ממנו תרומה גדולה ולא הורם ממנו מעשר ראשון\u0004 או שהורם ממנו \u0003מעשר ראשון ולא מעשר שני, ואפילו מעשר עני\u0004 שאין בו כשלעצמו קדושה אלא הוא צדקה לעניים בלבד, \u0003מנין\u0004 שאף עליו חייב?","\u0003תלמוד לומר: \"לא תוכל לאכל בשעריך\u0004 מעשר דגנך...\u0003\"\u0004 (דברים יב, יז), \u0003ולהלן הוא אומר\u0004 במעשר עני: \u0003\"ואכלו בשעריך ושבעו\"\u0004 (שם כו, יב), \u0003מה \"שעריך\" האמור להלן\u0004 הכוונה היא ל\u0003מעשר עני, אף \"שעריך\" האמור כאן\u0004 הוא \u0003מעשר עני, ואמר רחמנא\u0004 \u0005[ואמרה התורה]\u0006 \u0003\"לא תוכל\",\u0004 משמע שאסור לאוכלו אלא אחר הפרשה.","\u0003ואי מהתם\u0004 \u0005[ואם משם]\u0006 ממעשר עני בלבד \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שהוא \u0003ל\u0004איסור \u0003לאו\u0004 בלבד \u0003אבל\u0004 ל\u0003מיתה — לא,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 את ההשוואה לתרומה, לומר שיש גם חיוב מיתה באכילת טבל.","\u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]\u0006 של דיון זה מנוסחת בצורת שאלה: \u0003מעשר ראשון דטביל\u0004 \u0005[ש\u0006הוא \u0005טבל],\u0006 כלומר, שאי הפרשתו משאירה את הדבר בתורת טבל, הלא \u0003מ\u0004דברי \u0003ר' יוסי נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005]!\u0006 ומשיבים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003מ\u0004ההוכחה \u0003ההיא\u0004 בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 רק \u0003ללאו, אבל\u0004 ל\u0003מיתה — לא,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שיש בו כל חומרת איסור טבל.","ושואלים: \u0003במאי אוקימתא\u0004 \u0005[במה העמדת]\u0006 את המשנה — \u0003כ\u0004שיטת \u0003ר' מאיר,\u0004 אם כן \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]:\u0006 \u0003\"בת לוי מאורסת לכהן, ובת כהן ללוי — לא תאכל לא בתרומה ולא במעשר\", הכא מאי\u0004 \u0005[\u0006ו\u0005כאן מה]\u0006 \u0003זרות איכא\u0004 \u0005[יש]\u0006 שתהא פסולה, שאפילו לדעה האוסרת מעשר ראשון למי שאינו לוי, הלא מכל צד לויה היא! \u0003אמר רב ששת: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אינה אוכלת\" דקתני\u0004 \u0005[ששנה] —\u0006 \u0003אינה נותנת רשות לתרום.\u0004 והכוונה היא שבעודה ארוסה אינה יכולה לומר לשליח לתרום עבור הארוס תרומת מעשר מן המעשר כדי להכשירו, שכיון שעדיין אינה אשתו, אינה זכאית לעשות זאת עבורו.","ושואלים: \u0003מכלל\u0004 הדברים אתה למד כי ה\u0003נשואה נותנת רשות?\u0004 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003והתניא\u0004 \u0005[ו\u0006אכן כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר: \u0003\"ואכלתם אתו בכל מקום אתם וביתכם\"\u0004 (במדבר יח, לא) — \u0003לימד על\u0004 ה\u0003נשואה\u0004 ללוי (\"ביתכם\") שהיתה \u0003בת ישראל שנותנת רשות לתרום\u0004 תרומת מעשר מן המעשר הניתן ללוי.","וממשיכה הברייתא במשא ומתן: \u0003אתה אומר\u0004 שיכולה לתת \u0003רשות לתרום, או אינו אלא\u0004 שמותרת \u0003לאכול? אמרת: תרומה חמורה — אוכלת\u0004 ישראלית שנישאה לכהן, \u0003מעשר הקל לא כל שכן?!\u0004 ואם כן דבר זה אינו צריך להיאמר, \u0003אלא לימד על נשואה בת ישראל שנותנת רשות לתרום.\u0004","\u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבנא אמר:\u0004 אין כוונת המשנה לומר שבת לוי המאורסת לכהן לא תאכל במעשר, אלא \u0003לומר שאין חולקין לה מעשר בבית הגרנות.\u0004 ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 שטעם התקנה שלא יחלקו לאשה בגורן הוא \u0003משום ייחוד\u0004 שלא תבוא להתייחד עם גבר זר בגורן, שהוא מקום מבודד, \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שאסרו זאת \u0003משום גרושה,\u0004 שמא תתגרש האשה, ולא יידעו ששוב אין לה זכות בתרומה, והלא \u0003בת לוי מי לא אכלה\u0004 \u0005[האם אינה אוכלת]\u0006 \u0003במעשר\u0004 בזכות עצמה, אפילו נתגרשה מבעלה?! ומדוע לא יחלקו לה בגורן כשנתארסה לכהן?","ודוחים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שאין אתה מקבל את טעמו של מר בריה דרבנא בבת לוי, וכי \u0003גרושה בת כהן מי לא אכלה\u0004 \u0005[האם אינה אוכלת]\u0006 \u0003בתרומה?\u0004 ומדוע אין חולקים לבת כהן הנשואה לכהן תרומה בגורן! \u0003אלא\u0004 עיקר \u0003גזירה\u0004 זו היא \u0003משום גרושה\u0004 של כהן שהיתה \u0003בת ישראל,\u0004 שלאחר גירושיה שוב אינה אוכלת בתרומה. ומאותו טעם גזרו גם באשת לוי שלא תחלוק בגורן אף שהיא עצמה בת לוי.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כן]\u0006 שטעם המשנה הוא משום הגזירה שלא תקבל אשה מתנות כהונה בגורן, \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 למה דווקא\u0005]\u0006 \u0003מאורסת? אפילו נשואה נמי\u0004 \u0005[גם כן]\u0006 אינה מקבלת מטעם זה! ומשיבים: באמת לענין זה אין הבדל, אלא \u0003איידי דתנא רישא\u0004 \u0005[מתוך ששנה\u0006 ב\u0005ראש\u0006 המשנה\u0005]\u0006 \u0003מאורסת, תנא נמי סיפא\u0004 \u0005[שנה גם כן\u0006 ב\u0005סופה]\u0006 \u0003מאורסת\u0004 ואין זה דווקא משום אירוסין.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003תרומה\u0004 ניתנת \u0003לכהן, ומעשר ראשון\u0004 ניתן \u0003ללוי\u0004 דווקא, אלו \u0003דברי ר' עקיבא. ר' אלעזר בן עזריה אומר:\u0004"],["\u0003לכהן.\u0004 ותוהים: \u0003לכהן ולא ללוי?\u0004 הלא כתוב בתורה שמעשר ראשון ניתן ללוים! ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003אף לכהן.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' עקיבא — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואל הלוים תדבר ואמרת אלהם\"\u0004 (במדבר יח, כו) — \u0003בלוים קא משתעי קרא\u0004 \u0005[מדבר הכתוב]\u0006 ולא בכהנים. \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' אלעזר\u0005]\u0006 סבור \u0003כ\u0004שיטת \u0003ר' יהושע בן לוי.\u0004 ש\u0003אמר ר' יהושע בן לוי: בעשרים וארבעה מקומות\u0004 בכתוב \u0003נקראו כהנים \"לוים\", וזה אחד מהם,\u0004 שמפורש בו: \u0003\"והכהנים הלוים בני צדוק\"\u0004 (יחזקאל מד, טו), ואף הכתוב המדבר במעשר הוא מן המקומות הללו.","\u0003ור' עקיבא\u0004 אומר: \u0003הכא לא מצית אמרת\u0004 \u0005[כאן אין אתה יכול לומר]\u0006 שמדובר בכהנים, \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]:\u0006 \u0003\"ואכלתם אתו בכל מקום\"\u0004 (במדבר יח, לא), לומר: המעשר ניתן ל\u0003מי שיכול לאוכלו בכל מקום, יצא כהן, שאין יכול לאוכלו בבית הקברות\u0004 שאסור לו להיכנס שם. ואם כן לא בו מדבר הכתוב. \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' אלעזר\u0005]\u0006 מה הוא אומר על כך? הוא מסביר את הפסוק כך: \u0003כל היכא דבעי\u0004 \u0005[מקום שרוצה]\u0006 יכול לאכול — כוונתו בכל עיר, \u0003דלא בעי\u0004 \u0005[שאין צריך]\u0006 \u0003חומה\u0004 של ירושלים לאכלו (כמו מעשר שני), אלא בכל מקום בארץ. ועוד: \u0003ואי אכיל ליה\u0004 \u0005[ואם אוכל אותו]\u0006 את המעשר \u0003בטומאת הגוף — לא לקי\u0004 \u0005[איננו לוקה],\u0006 ולכן אפשר לומר כי המעשר נאכל אף על ידי כהנים בכל מקום.","מסופר: \u0003ההיא גינתא דהוה שקיל\u0004 \u0005[גינה אחת שהיה לוקח]\u0006 \u0003ר' אלעזר בן עזריה\u0004 שהיה כהן \u0003מעשר ראשון מינה\u0004 \u0005[ממנה],\u0006 שהרי לדעתו ניתן המעשר הראשון אף לכהן. \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003ר' עקיבא אהדריה לפתחא לבי קברי\u0004 \u0005[\u0006סגר את הגינה ו\u0005החזיר,\u0006 הזיז, \u0005את הפתח\u0006 שלה \u0005ל\u0006עבר \u0005בית הקברות]\u0006 שר' אלעזר בן עזריה, שהיה כהן, לא יוכל להיכנס. \u0003אמר\u0004 ר' אלעזר בהפרזה ובבדיחות־דעת: \u0003עקיבא,\u0004 רועה לשעבר, בא \u0003בתרמילו\u0004 ובו מזון כדי צרכו, \u0003ואנא חיי\u0004 \u0005[ואני אחיה]!\u0006 כלומר, ממה אחיה מעתה אם אין לי מעשר? ואף שר' אלעזר עשיר גדול היה, רצה לומר שר' עקיבא עושה מעשה כדי למנוע ממנו דבר המגיע לו, לדעתו.","\u0003איתמר\u0004 \u0005[אמר],\u0006 שנחלקו חכמים בשאלה \u0003מפני מה קנסו לוים במעשר,\u0004 שנותנים אותו בזמן הזה גם לכהנים? \u0003פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003ר' יונתן וסביא\u0004 \u0005[והזקנים,\u0006 החכמים\u0005]\u0006 שהיו עימו. \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 משום \u0003שלא עלו\u0004 לארץ ישראל \u0003בימי עזרא. וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 לא משום קנס ללוים, אלא \u0003כדי שיסמכו כהנים עליו בימי טומאתן.\u0004 שכיון שאסור לאכול תרומה בטומאה, אין לכהנים אז מה לאכול.","ושואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 שסיבת הקנס משום \u0003שלא עלו — משום הכי\u0004 \u0005[כך]\u0006 \u0003קנסינהו\u0004 \u0005[קנסו אותם]\u0006 שלא יקבלו את כל המעשר, ויתחלקו עם הכהנים. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שטעם הדבר \u0003כדי שיסמכו עליו כהנים בימי טומאתן — וכי משום\u0004 טובתם של \u0003כהנים קנסינהו\u0004 \u0005[קונסים אותם]\u0006 את ה\u0003לוים? אלא\u0004 יש לומר אחרת: \u0003כולי עלמא\u0004 \u0005[\u0006לדעת \u0005הכל]\u0006 \u0003קנסא\u0004 \u0005[הקנס]\u0006 הוא על \u0003שלא עלו בימי עזרא. והכא בהא קמיפלגי\u0004 \u0005[וכאן בכך נחלקו]:\u0006 \u0003מר סבר\u0004 \u0005[חכם\u0006 זה \u0005סבור]\u0006 כי \u0003קנסא\u0004 \u0005[הקנס]\u0006 צריכים לתת \u0003לעניים\u0004 שינתן המעשר ראשון לעניים, \u0003ומר סבר\u0004 \u0005[וחכם\u0006 זה \u0005סבר]\u0006 ש\u0003כהנים בימי טומאתן\u0004 בגדר \u0003עניים נינהו\u0004 \u0005[הם].\u0006","ושואלים: \u0003בשלמא למאן דאמר קנסא\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר\u0006 ש\u0005הקנס]\u0006 ניתן \u0003לעניים — משום הכי\u0004 \u0005[כך]\u0006 \u0003אהדריה\u0004 \u0005[החזירו]\u0006 \u0003ר' עקיבא לפתחא לבי קברי\u0004 \u0005[את פתח\u0006 הגינה \u0005ל\u0006עבר \u0005בית הקברות],\u0006 שכן רבי אלעזר בן עזריה עשיר היה. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שהקנס ניתן \u0003לכהנים\u0004 לכתחילה, אם כן \u0003אמאי אהדריה לפתחא לבי קברי\u0004 \u0005[מדוע החזיר את הפתח ל\u0006עבר \u0005בית הקברות]?\u0006 ומשיבים: \u0003הכי קאמר ליה\u0004 \u0005[כך אמר לו],\u0006 כך היתה כוונתו: \u0003אי דקא אתית\u0004 \u0005[אם אתה בא\u0006 ומקבל\u0005]\u0006 \u0003בתורת קנסא\u0004 \u0005[קנס] —\u0006 \u0003אית לך\u0004 \u0005[יש לך]\u0006 מעשר, \u0003ואי קא אתית\u0004 \u0005[אם אתה בא\u0006 ומקבל\u0005]\u0006 \u0003בתורת חלוקה,\u0004 לחלוק עם שאר הלויים — \u0003לית לך\u0004 \u0005[אין לך],\u0006 ולכן אם ירצה בעל השדה לתת לך — יכול הוא עדיין לתת, אבל אתה לא תוכל לקחת כרצונך.","ושואלים על הדבר שהוזכר קודם בענין הקנס שקנסו את הלויים: \u0003ומנא לן דלא סליקו\u0004 \u0005[ומניין לנו שלא עלו]\u0006 הלוים \u0003בימי עזרא? דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואקבצם אל הנהר הבא אל אהוא ונחנה שם ימים שלשה ואבינה בעם ובכהנים ומבני לוי לא מצאתי שם\"\u0004 (עזרא ח, טו). ואגב דבר זה \u0003אמר רב חסדא: בתחלה לא היו מעמידים שוטרים\u0004 על העם \u0003אלא מן הלוים, שנאמר: \"ושטרים הלוים לפניכם\"\u0004 (דברי הימים ב' יט, יא), ואולם \u0003עכשיו אין מעמידין שוטרים אלא מישראל, שנאמר: \"ושוטרים הרבים בראשיכם\",\u0004 שממנים שוטרים מאלה שהם רובו (\"הרבים\") של העם — מישראל.","\u0003בת ישראל שניסת\u0004 (שנישאה) \u0003לכהן — תאכל בתרומה. מת\u0004 הכהן, \u0003ולה,\u0004 לאשתו הישראלית, \u0003הימנו\u0004 (ממנו) \u0003בן — תאכל בתרומה\u0004 בשביל בנה. \u0003ניסת\u0004 אחר כך \u0003ללוי\u0004 — אינה אוכלת עוד בתרומה אבל \u0003תאכל\u0004 בשבילו \u0003במעשר. מת ולה הימנו בן\u0004 — תמשיך ו\u0003תאכל במעשר\u0004 בשביל בנה. \u0003ניסת\u0004 אחר כך \u0003לישראל — לא תאכל לא בתרומה, ולא במעשר. מת\u0004 בעלה הישראלי \u0003ולה הימנו בן\u0004 — עדיין \u0003לא תאכל לא בתרומה ולא במעשר.\u0004","\u0003מת\u0004 גם \u0003בנה מישראל\u0004 ונשאר לה בנה מן הלוי — \u0003תאכל במעשר\u0004 משום בנה הלוי. \u0003מת בנה מלוי\u0004 ונשאר לה בנה מן הכהן — תשוב ו\u0003תאכל בתרומה. מת בנה מכהן — לא תאכל\u0004 עוד \u0003לא בתרומה ולא במעשר.\u0004"],["\u0003בת כהן שניסת לישראל — לא תאכל בתרומה. מת ולה הימנו בן — לא תאכל בתרומה\u0004 כל עוד יש לה זרע ממנו. \u0003ניסת\u0004 אחר כך \u0003ללוי — תאכל במעשר. מת ולה הימנו בן — תאכל במעשר.\u0004 חזרה ו\u0003ניסת לכהן — תאכל בתרומה. מת ולה הימנו בן — תאכל בתרומה.\u0004","\u0003מת בנה מכהן — לא תאכל בתרומה,\u0004 שהרי יש לה בן מלוי. \u0003מת בנה מלוי — לא תאכל\u0004 עוד גם \u0003במעשר. מת בנה מישראל — חוזרת לבית אביה\u0004 ואוכלת בתרומה, \u0003ועל זו נאמר: \"ושבה אל בית אביה כנעוריה מלחם אביה תאכל\"\u0004 (ויקרא כב, יג).","שנינו במשנה: \u0003מת בנה מלוי תאכל בתרומה.\u0004 ושואלים: הלכה זו שאשה שהיתה נשואה לכהן, ונישאה לאחר, ונפרדה ממנו \u0003דהדרא אכלה\u0004 \u0005[שחוזרת\u0006 ו\u0005אוכלת]\u0006 \u0003משום בנה\u0004 מכהן \u0003מנלן\u0004 \u0005[מניין לנו]?\u0006 \u0003אמר ר' אבא אמר רב:\u0004 נאמר \"ובת כהן כי תהיה אלמנה וגרושה וזרע אין לה ושבה אל בית אביה\" (שם), שהיה יכול להיאמר \u0003\"בת\u0004 כהן \u0003\"\u0004ונאמר \u0003\"ובת\u0004 כהן","\u0003\",\u0004 והרי זו לשון ריבוי, לרבות גם את זו שחוזרת ואוכלת בתרומה. ושואלים: \u0003כמאן\u0004 \u0005[כמי]\u0006 שיטת דרשה זו — \u0003כר' עקיבא, דדריש ווי\u0004 \u0005[שדורש וו\"ים]\u0006 כריבויים? ודוחים: \u0003אפילו תימא רבנן\u0004 \u0005[תאמר\u0006 כשיטת \u0005חכמים]\u0006 שאינם רואים כל ו' כלשון ריבוי, מכל מקום, כאן \u0003כולא\u0004 \u0005[כל\u0006 המלה\u0005]\u0006 \u0003\"ובת\" קרא יתירא\u0004 \u0005[כתוב מיותר]\u0006 \u0003הוא,\u0004 שכן גם בפסוק הקודם נזכרת \"בת כהן\", ולא היה צריך לחזור ולהזכיר אותה, לכן לדעת הכל יש לראות בכך לשון ריבוי.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 בת כהן \u0003כשהיא חוזרת\u0004 לבית אביה — \u0003חוזרת ל\u0004אכילת \u0003תרומה ואינה חוזרת ל\u0004אכילת \u0003חזה ושוק\u0004 מן השלמים. \u0003אמר רב חסדא אמר רבינא בר שילא: מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 המלמד על כך — \u0003\"היא בתרומת הקדשים לא תאכל\"\u0004 (שם יב), ופירושו: \u0003במורם,\u0004 מאותו דבר שנותנים תרומה לכהן, \u0003מן הקדשים — לא תאכל. רב נחמן אמר\u0004 בשם \u0003רבה בר אבוה\u0004 מקור אחר: נאמר \u0003\"מלחם\u0004 אביה\u0003\"\u0004 (שם יג), ומדייקים: \"מלחם\" — \u0003ולא כל לחם, פרט לחזה ושוק.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רמי בר חמא: אימא\u0004 \u0005[אמור]\u0006 שמא בא הכתוב לומר: \u0003פרט להפרת נדרים,\u0004 שאף לאחר \"ושבה אל בית אביה כנעוריה\" (שם), אין הכוונה שתיעשה לכל ענין כנערה, ואין אביה רשאי להתיר את נדרה, וזה שבא הכתוב ללמדנו! \u0003אמר רבא:\u0004 את הקשר ביניהם לגבי נדרים \u0003כבר פסקה\u0004 \u0005[חתך אותה],\u0006 שלא תהיה עוד קשורה לבית אביה, ה\u0003תנא דבי\u0004 \u0005[\u0006ה\u0005חכם\u0006 ב\u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל, דתנא דבי\u0004 \u0005[ששנה\u0006 החכם ב\u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל,\u0004 נאמר: \u0003\"ונדר אלמנה וגרושה\u0004 כל אשר אסרה על נפשה \u0003יקום עליה\"\u0004 (במדבר ל, י) ולכאורה \u0003מה תלמוד לומר,\u0004 מה בא הדבר ללמד? \u0003והלא מוצאה מכלל\u0004 רשות \u0003אב,\u0004 שהרי כבר נישאה, \u0003ומוצאה מכלל בעל\u0004 שהרי היא אלמנה או גרושה, ולא הוצרך הכתוב לומר שאין התרה לנדריה!","\u0003אלא, הרי\u0004 כגון \u0003שמסר האב\u0004 את בתו \u0003לשלוחי הבעל\u0004 לשם נישואין, שיצאה כבר מבית אביה, \u0003או שמסרו שלוחי האב לשלוחי הבעל, ונתארמלה\u0004 (נתאלמנה) \u0003או נתגרשה בדרך\u0004 עד שהגיעה לבית בעלה, \u0003היאך אני קורא בה: בית אביה של זו, או בית בעלה של זו,\u0004 שהרי אין לה לא בית אב ולא בית בעל, \u0003אלא לומר לך: כיון שיצתה\u0004 (שיצאה) \u0003שעה אחת מרשות האב\u0004 לחלוטין, כגון שמסרה לשליחי הבעל — \u0003שוב אינו יכול להפר.\u0004 ואם כן, ממקור זה למדנו שאין האב יכול להפר נדרי בתו לאחר שהיתה נשואה. ואין צורך בכתוב נוסף.","\u0003רב ספרא אמר:\u0004 ההוכחה לכך שהחוזרת לבית אביה אינה אוכלת בחזה ושוק היא מדיוק הכתוב \u0003\"מלחם אביה תאכל\",\u0004 — \u0003\"לחם\"\u0004 של תרומה \u0003ולא בשר,\u0004 להוציא חזה ושוק. \u0003רב פפא אמר\u0004 לימוד אחר: \u0003\"מלחם אביה תאכל\",\u0004 פירושו: \u0003לחם הקנוי לאביה\u0004 כגון תרומה שהיא רכוש הכהן, \u0003פרט לחזה ושוק\u0004 שאינם קניין של הכהן, כי באלה ש\u0003משלחן גבוה\u0004 (הקדוש ברוך הוא) \u0003קא זכו\u0004 \u0005[הם זוכים],\u0006 שאינם זוכים בחזה ושוק כמתנה ישירה לעצמם, אלא לאחר שניתן הקרבן לשמים, מקבלים הכהנים חלק ממנו כמתנת ה' להם מן הזבח.","\u0003ורבא אמר,\u0004 נאמר: \u0003\"ואת חזה התנופה ואת שוק התרומה תאכלו\u0004 במקום טהור \u0003אתה ובניך ובנתיך אתך\"\u0004 (ויקרא י, יד), והדגשת הכתוב \"אתך\" באה ללמד: \u0003בזמן ש\u0004הם \u0003אתך,\u0004 אבל כאשר יצאו מאתך, כגון שנישאו לישראל — שוב אינם אוכלים.","\u0003אמר רב אדא בר אהבה, תנא\u0004 \u0005[שנה]\u0006 החכם: בת כהן \u0003כשהיא חוזרת לבית אביה,\u0004 לאחר שנישאה ונפרדה מבעלה ואין לה צאצאים ממנו — \u0003חוזרת לתרומה, ואינה חוזרת לחזה ושוק.\u0004 אבל בת ישראל שהיתה אוכלת \u0003בשביל בנה\u0004 מכהן, ומת בעלה ונישאה לישראל ומת אף הוא — \u0003חוזרת אף לחזה ושוק.\u0004","\u0003אזל\u0004 \u0005[הלך]\u0006 \u0003רב מרדכי אמרה לשמעתא\u0004 \u0005[להלכה\u0006 זו\u0005]\u0006 \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רב אשי. אמר\u0004 לו רב אשי: \u0003מהיכא קא מתרביא\u0004 \u0005[מהיכן\u0006 \u0005הוא\u0006 \u0005מתרבה]\u0006 מה מקור הריבוי המלמד שאוכלת בשביל בנה — \u0003מ\u0004מה שנאמר \u0003\"ובת\", מי עדיפא לה מינה\u0004 \u0005[האם\u0006 היא \u0005עדיפה ממנה]\u0006 מבת כהן עצמה שאינה חוזרת לאכול חזה ושוק? ומשיבים: \u0003התם כתיבי מיעוטי\u0004 \u0005[שם נאמרו מיעוטים]\u0006 כפי שלמדנו, למעט שאיננה חוזרת לכל דבר, ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 בבת ישראל זו החוזרת לאכול בשביל בנה מן הכהן לאחר מיתת בעלה הישראל, \u0003לא כתיבי מיעוטי\u0004 \u0005[נאמרו מיעוטים],\u0006 ולכן, אף שעצם הדין נלמד מבת כהן החוזרת לבית אביה — מרובה כוחה יותר מזו שחוזרת.","ולפירוש פרטי המשנה, שנינו: \u0003בת כהן שניסת לישראל\u0004 — לא תאכל בתרומה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 מדרש הלכה זה, נאמר: \u0003\"ושבה אל בית אביה\"\u0004 (שם כב, יג) — כוונתו: \u0003פרט לשומרת יבם,\u0004 כי מאחר שהיא שומרת וממתינה ליבם עדיין אינה יכולה לשוב. \u0003\"כנעוריה\"\u0004 בא ללמד — \u0003פרט למעוברת,\u0004 שההריון משנה אותה ממה שהיתה בנעוריה.","ודנים: לכאורה, \u0003והלא דין\u0004 (קל וחומר) \u0003הוא,\u0004 שאפשר ללמדו מן הסברה ואין צורך בכתוב מיוחד: \u0003ומה במקום שלא עשה\u0004 את ה\u0003ולד מן הראשון כולד מן השני לפוטרה מן הייבום,\u0004 שאם נישאה לאיש והיה לה בן ממנו, ואחר כך מת בעלה ונישאה לאחר, ומת השני בלא בנים — שצריכה ייבום, למרות שיש לה ילד. שהוולד מן הראשון איננו נחשב כדי לפוטרה מן הייבום, ולמרות הגבלה זו \u0003עשה\u0004 לענין ייבום את ה\u0003עובר כילוד,\u0004 שהמעוברת איננה חייבת בייבום —","\u0003מקום שעשה\u0004 את ה\u0003ולד מן הראשון כולד מן השני לפוסלה מן התרומה,\u0004 שאם בת כהן נישאה לישראל וילדה לו ומת, ואחר כך נישאה שוב לישראל ומת בלי בנים, אסור לה לאכול תרומה בגלל הוולד מן הראשון — וכי \u0003אינו דין שנעשה\u0004 לענין תרומה את ה\u0003עובר כילוד,\u0004 שכשהיא מעוברת לא תחזור לאכול?!","אולם את הראיה הזו אפשר לדחות: \u0003לא, מה לי\u0004 לענין ש\u0003עשה\u0004 את ה\u0003עובר כילוד לענין ייבום — שהרי\u0004 בדין ייבום \u0003עשה מתים כחיים,\u0004 שאם היה לה בן בזמן שמת בעלה — נפטרה על ידו לגמרי מן הייבום אף שמת אחר כך, ונמצא שלדין ייבום נחשב הבן המת כאילו היה חי, אולם האם \u0003נעשה\u0004 את ה\u0003עובר כילוד לענין תרומה, שלא עשה\u0004 לענין תרומה \u0003מתים כחיים?!\u0004 שהרי בתרומה כל עוד יש לבת כהן ילד חי מבעלה הישראלי — פוסל הוא אותה מן התרומה, מת הילד — הרי היא כשרה, ואין אומרים שהוא נחשב כחי. על כן אין ללמוד דין תרומה מייבום גם לענין עובר כילוד. ולכן \u0003תלמוד לומר \"כנעוריה\" — פרט למעוברת.\u0004","ומעירים: \u0003ואיצטריך למכתב\u0004 \u0005[והוצרך לומר]\u0006 כתוב זה ללמד על ה\u0003מעוברת, ואיצטריך למכתב\u0004 \u0005[והוצרך לומר]\u0006 \u0003\"וזרע אין לה\"\u0004 (שם). \u0003דאי כתב רחמנא\u0004 \u0005[שאילו אמרה התורה]\u0006 רק \u0003\"וזרע אין לה\"\u0004 הייתי אומר: כיון ש\u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 כשאכלה בתרומה היתה רק \u0003חד גופא\u0004 \u0005[גוף אחד]\u0006 \u0003והשתא תרי גופי\u0004 \u0005[ועכשיו\u0006 כשחוזרת \u0005שני גופים]\u0006 שוב אין זו \"בנעוריה\", \u0003אבל מעוברת, דמעיקרא חד גופא והשתא חד גופא\u0004 \u0005[שמתחילה\u0006 היתה \u0005גוף אחד ועכשיו\u0006 עדיין \u0005גוף אחד] —\u0006 \u0003אימא תיכול\u0004 \u0005[אמור\u0006 ש\u0005תאכל]\u0006 בתרומה עד שתלד, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 הדבר להיאמר. ולהיפך: \u0003ואי כתב רחמנא\u0004 \u0005[ואילו אמרה התורה]\u0006 רק לענין \u0003מעוברת,\u0004 הייתי אומר כך: דווקא מעוברת \u0003דמעיקרא גופא\u0004"],["\u0003סריקא והשתא גופא מליא\u0004 \u0005[מתחילה\u0006 היה \u0005גוף ריק,\u0006 שלא היה בו דבר, \u0005ועכשיו גוף מלא\u0006 בעובר\u0005]\u0006 \u0003אבל \"זרע אין לה\", דמעיקרא גופא סריקא והשתא גופא סריקא\u0004 \u0005[שמתחילה\u0006 היה \u0005גוף ריק ועכשיו\u0006 הוא \u0005גוף ריק]\u0006 לאחר שילדה, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 תיפסל על ידי כך, לכן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שני הכתובים.","\u0003סימן\u0004 של ראשי הפרקים שיידונו להלן: \u0003אמ\"ר לי\"ה ל\"א נעש\"ה מעשי\"ה במית\"ה נעש\"ה ול\"א נעש\"ה בול\"ד יב\"ם ותרומ\"ה יבו\"ם ותרומ\"ה — סימן.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יהודה מדאסקרתא לרבא,\u0004 כהמשך לדיון שבברייתא: \u0003לא נעשה מתים כחיים לענין יבום מקל וחומר,\u0004 וכך נאמר: \u0003ומה במקום שעשה ולד מן הראשון כולד מן השני לפוסלה מן התרומה,\u0004 שהרי כל עוד יש לה ולד שאינו כהן פסולה לאכילת התרומה, ובכל זאת \u0003לא עשה\u0004 ילדים \u0003מתים כחיים — מקום שלא עשה ולד מן הראשון כולד מן השני לפוטרה מן הייבום — אינו דין שלא נעשה מתים כחיים?\u0004 ומדוע באמת נפטרת היבמה מחובת הייבום אם מת הבן שנולד לה מבעלה לאחר מות הבעל? \u0003תלמוד לומר: \"דרכיה דרכי נעם וכל נתיבתיה שלום\"\u0004 (משלי ג, יז), כלומר, דרכי התורה דרכי נועם הן, ואין לחייב אשה מספק שמא נישאה כבר לאחר, לחזור ולחלוץ, כדי שלא תתגנה על בעלה.","","","ויש לשאול גם מצד אחר: אם כן, \u0003ונעשה\u0004 ילדים \u0003מתים כחיים לענין תרומה, מקל וחומר: ומה\u0004 בייבום, \u0003במקום שלא עשה ולד מן הראשון כולד מן השני\u0004 לענין \u0003לפוטרה מן הייבום, עשה\u0004 בכל זאת \u0003מתים כחיים — מקום שעשה ולד מן הראשון כולד מן השני, לפוסלה מן התרומה, אינו דין שנעשה מתים כחיים? תלמוד לומר: \"וזרע אין לה\"\u0004 (ויקרא כב, יג), \u0003והא\u0004 \u0005[והרי]\u0006 כעת \u0003אין לה.\u0004","ודנים עוד: \u0003ונעשה ולד מן הראשון כולד מן השני לענין יבום מקל וחומר,\u0004 וכך נאמר: \u0003ומה במקום שלא עשה מתים כחיים לענין תרומה,\u0004 בכל זאת \u0003עשה ולד מן הראשון כולד מן השני — מקום שעשה מתים כחיים, לענין יבום, אינו דין שנעשה\u0004 ונדון \u0003ולד מן הראשון כ\u0004אילו היה \u0003ולד מן השני\u0004 ותיפטר מן הייבום?! \u0003תלמוד לומר: \"ובן אין לו\"\u0004 (דברים כה, ה), \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אין לו\u0004 בנים לאחר שמת.","ודנים מצד אחר: \u0003ולא נעשה ולד מן הראשון כולד מן השני לתרומה מקל וחומר,\u0004 ונאמר: \u0003מה במקום שעשה מתים כחיים\u0004 לענין \u0003לפוטרה מן הייבום,\u0004 בכל זאת \u0003לא עשה ולד מן הראשון כולד מן השני — מקום שלא עשה מתים כחיים לענין תרומה, אינו דין שלא נעשה ולד מן הראשון כולד מן השני?! תלמוד לומר: \"\u0004וזרע \u0003אין לה\", והא\u0004 \u0005[והרי]\u0006 \u0003יש לה.\u0004 ואם כן על ידי מדרש הכתובים הובהרו ההבדלים בין שתי הלכות אלה.","","\u0003האשה שהלך בעלה למדינת הים, ובאו\u0004 עדים \u0003ואמרו לה \"מת בעליך\", וניסת\u0004 (נישאה) על סמך עדות זו לאדם אחר, \u0003ואחר כך בא בעלה\u0004 ממדינת הים — \u0003תצא מזה ומזה,\u0004 משני הבעלים, ששניהם אסורים בה, \u0003וצריכה גט מזה ומזה,\u0004","\u0003ואין לה כתובה, ולא פירות\u0004 מהנכסים שהשתמשו אלה בהם, \u0003ולא מזונות, ולא בלאות\u0004 (נכסי צאן ברזל שהביאה ונתבלו) — \u0003לא על זה ולא על זה,\u0004 לא מן הראשון ולא מן השני. \u0003ואם נטלה\u0004 אחד מכל אלה \u0003מזה\u0004 או \u0003מזה — תחזיר\u0004 להם.","\u0003והולד ממזר מזה ומזה,\u0004 כלומר, הוולד מבעלה השני ממזר גמור, ואם חזרה לבעלה הראשון גזרו חכמים שגם הוולד הנולד ממנו ממזר. \u0003ולא זה וזה מטמא לה\u0004 במיתתה אם היו כהנים, \u0003ולא זה וזה זכאים\u0004 בזכויות הנובעות מקשר הנישואין: \u0003לא במציאתה, ולא במעשה ידיה, ולא בהפרת נדריה.\u0004","אם \u0003היתה בת ישראל — נפסלה מן הכהונה\u0004 שכן ביאה זו על ידי הבעל השני היא ביאת זנות. ואף גזרו בה שאם היא \u0003בת לוי\u0004 נפסלת \u0003מן המעשר, ו\u0004אם היא \u0003בת כהן\u0004 נפסלת \u0003מן התרומה. ואין יורשין של זה ויורשין של זה יורשין את כתובתה,\u0004 שאינה נחשבת כאילו היתה נשואה, אף לא לאחד מהם. \u0003ואם מתו\u0004 שני אלו בלי בנים — \u0003אחיו של זה ואחיו של זה חולצין ולא מייבמין.\u0004","\u0003ר' יוסי\u0004 חולק על תנא קמא ו\u0003אומר:\u0004 יש לה כתובה ו\u0003כתובתה על נכסי בעלה הראשון. ר' אלעזר אומר: הראשון זכאי במציאתה ובמעשה ידיה ובהפרת נדריה,\u0004 שכיון שנישואיה לשני היו בטעות, אין היא מוצאת על ידי כך מבעלה הראשון. \u0003ר' שמעון\u0004 מוסיף ו\u0003אומר: ביאתה או חליצתה מאחיו של\u0004 ה\u0003ראשון פוטרת\u0004 אפילו את \u0003צרתה,\u0004 שהיא חליצה גמורה, ובודאי שאינה צריכה חליצה מאחיו של שני. \u0003ו\u0004אם חזרה לראשון ונולד לה ממנו בן — \u0003אין הולד ממנו ממזר.\u0004","כל זה כשנישאה ברשות בית דין לאחר ששמעה שמת בעלה, \u0003ואם ניסת שלא ברשות\u0004 בית דין אלא על פי העדים בלבד, ובא בעלה — \u0003מותרת לחזור לו\u0004 לבעלה הראשון. ועוד הבדל בין המקרים: \u0003ניסת על פי בית דין — תצא\u0004 משניהם, \u0003ופטורה מן הקרבן\u0004 קרבן חטאת על שגגה באיסור ניאוף, שהרי עשתה בהוראת בית דין, והיא נחשבת כאנוסה ואם","\u0003לא ניסת על פי בית דין\u0004 אלא על פי עדים — \u0003תצא\u0004 מבעלה השני, \u0003וחייבת בקרבן\u0004 על השגגה ששגגה באיסור ערוה. ובזה \u0003יפה כח בית דין, שפוטרה מן הקרבן.\u0004 אם \u0003הורוה בית דין לינשא\u0004 על סמך עדות בלתי נכונה, \u0003והלכה וקלקלה,\u0004 כלומר, נבעלה לאדם בזנות — \u0003חייבת בקרבן, שלא התירוה אלא לינשא,\u0004 ומה שעשתה לא היה בגדר ההיתר של בית דין.","\u0003מדקתני סיפא\u0004 \u0005[מ\u0006מה \u0005ששנינו\u0006 ב\u0005סופה]\u0006 של המשנה: \u0003נשאת שלא ברשות\u0004 בית דין — \u0003מותרת לחזור לו,\u0004 משמע \u0003שלא ברשות בית דין\u0004 כוונתו: \u0003אלא בעדים,\u0004 שמאחר שהיו שני עדים — אינה זקוקה להיתר מיוחד של בית דין ו\u0003מכלל\u0004 הדברים אתה למד \u0003דרישא\u0004 \u0005[ש\u0006ב\u0005ראשה]\u0006 של המשנה שמדובר בה \u0003ברשות בית דין,\u0004 הכוונה שעשתה זאת \u0003בעד אחד, אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003עד אחד נאמן\u0004 להעיד שמת הבעל, ובית הדין יתיר לאשה להינשא על פי עדות זו.","\u0003ותנן נמי\u0004 \u0005[ושנינו גם כן\u0006 במשנה\u0005]:\u0006 \u0003הוחזקו להיות משיאין\u0004 אשה, שהעידו שמת בעלה, גם \u0003עד מפי עד, ו\u0004כן \u0003אשה מפי אשה, ו\u0004אף בעדות \u0003אשה מפי עבד ומפי שפחה, אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003עד אחד מהימן\u0004 (נאמן) לענין זה, שכל מקום שעד אחד נאמן, גם עד מפי עד וכל הפסולים לעדות נאמנים וכשרים, \u0003ותנן נמי\u0004 \u0005[ושנינו\u0006 במשנה \u0005גם כן]:\u0006 אם \u0003עד אחד אומר\u0004 לאדם \u0003\"אכלת חלב\" והוא אומר \"לא אכלתי\" — פטור\u0004 האיש מלהביא קרבן. ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003אמר\u0004 אותו אדם \u0003\"לא אכלתי\"\u0004 והכחיש את הדבר, \u0003הא אישתיק\u0004 \u0005[הרי\u0006 אם \u0005שתק]\u0006 ולא הכחיש — \u0003מהימן\u0004 \u0005[נאמן]\u0006 העד האחד. \u0003אלמא\u0004 \u0005[מכאן],\u0006 ש\u0003עד אחד מהימן מדאורייתא\u0004 \u0005[נאמן מן התורה]\u0006 לדברים מסויימים.","","ושואלים: \u0003מנא לן\u0004 \u0005[מניין לנו]\u0006 הדבר? ומביאים, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר בחטאת הבאה על השגגה: \u0003\"או הודע אליו חטאתו\"\u0004 (ויקרא ד, כג. ושם כח), משמע — שהחטא צריך להיות ידוע לו בידיעת עצמו \u0003ולא שיודיעוהו אחרים,\u0004 שעל ידי עדות אחרים איננו מביא קרבן, גם אם הם מעידים עליו שחטא. \u0003יכול אף על פי שאינו מכחישו יהא פטור\u0004 מלהביא קרבן? — \u0003תלמוד לומר: \"או הודע אליו\" — מכל מקום.\u0004","ומעתה מבררים: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005היה הדבר],\u0006 \u0003אילימא דאתו תרי ולא קא מכחיש להו\u0004 \u0005[אם תאמר שבאים שני\u0006 עדים ומודיעים לו \u0005והוא\u0006 \u0005אינו מכחיש אותם],\u0006 \u0003קרא\u0004 \u0005[הכתוב]\u0006 \u0003למה לי\u0004 לשם כך? הרי יש שני עדים הנאמנים לכל דבר. \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר ב\u0003חד\u0004 \u0005[\u0006בעד \u0005אחד],\u0006 \u0003וכי לא קא מכחיש ליה\u0004 \u0005[וכאשר אינו מכחיש אותו] —\u0006 \u0003מהימן\u0004 \u0005[נאמן\u0006 הוא\u0005],\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003עד אחד נאמן\u0004 באיסורים. את ההוכחה הזאת דוחים: \u0003וממאי\u0004 \u0005[וממה]\u0006 מסיק אתה שהטעם הוא \u0003דמשום דמהימן\u0004 \u0005[שנאמן]?\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 עיקר הטעם \u0003משום דקא שתיק\u0004 \u0005[שהוא שותק],\u0006 \u0003ו\u0004אנו אומרים כי \u0003שתיקה כהודאה דמיא\u0004 \u0005[נחשבת]?\u0006","ו\u0003תדע\u0004 שזהו אכן הטעם, \u0003דקתני סיפא\u0004 \u0005[ששנה\u0006 ב\u0005סופה\u0006 של אותה ברייתא\u0005]:\u0006 \u0003אמרו\u0004 לו \u0003שנים \"אכלת חלב\" והוא אומר \"לא אכלתי\" — פטור. ר' מאיר מחייב. אמר ר' מאיר\u0004 בטעם דבריו: \u0003קל וחומר\u0004 בדבר; \u0003אם הביאוהו שנים לידי מיתה חמורה,\u0004 שאם יבואו שני עדים ויעידו עליו שעבר במזיד עבירה שחייבים עליה מיתה — הלא יוציאוהו להורג בשל כך, והאם שני עדים \u0003לא יביאוהו לידי\u0004 הבאת \u0003קרבן הקל?\u0004","\u0003אמרו לו\u0004 חכמים: יש מקום לחלק, שכן לענין קרבן \u0003מה אם ירצה לומר \"מזיד הייתי\"!\u0004 והמזיד אינו חייב קרבן, שהרי אין העדים יכולים להכחישו בדבר זה, וכיון שבענין קרבן יש בכוחו לבטל את העדות, יש בכוחו גם להכחיש את המעשה עצמו, מה שאין כן כשמעידים עליו שעשה מעשה שחייבים עליו מיתה, שאז אין הכחשתו מעלה ומורידה דבר. ומבררים: \u0003רישא\u0004"],["\u0003מאי טעמא קא מחייבי רבנן\u0004 \u0005[בראש\u0006 הברייתא, כששותק, \u0005מה טעם מחייבים חכמים]\u0006 קרבן על פי עד אחד? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דמהימן\u0004 \u0005[ש\u0006הוא, העד, \u0005נאמן] —\u0006 \u0003והא תרי בעלמא, דאף על גב דקא מכחיש להו אינהו מהימני\u0004 \u0005[והרי שניים,\u0006 עדים \u0005סתם, שאף על פי ש\u0006הוא \u0005מכחיש אותם הם נאמנים]\u0006 \u0003ו\u0004בכל זאת לענין קרבן \u0003קא פטרי רבנן\u0004 \u0005[פוטרים חכמים],\u0006 וכל שכן שהיו חכמים צריכים לפטור בעד אחד. \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003משום דאישתיק\u0004 \u0005[ששתק]\u0006 \u0003ושתיקה כהודאה דמיא\u0004 \u0005[נחשבת]\u0006 ורק משום כך מביא קרבן, ואם כן, אין להביא מכאן ראיה שסומכים על עד אחד.","\u0003אלא\u0004 צריך לומר כי \u0003סברא היא\u0004 בענין זה, \u0003מידי דהוה\u0004 \u0005[כמו שהוא]\u0006 ביחס ל\u0003חתיכה\u0004 שהיא \u0003ספק של חלב ספק של שומן\u0004 ואי אפשר לברר זאת, \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003עד אחד ואמר: ברי\u0004 (ברור) \u0003לי,\u0004 ש\u0003שומן הוא — דמהימן\u0004 \u0005[שנאמן],\u0006 ואף כאן העד האחד בא לברר ולהתיר לנו את הספק.","ומקשים: \u0003מי דמי\u0004 \u0005[האם\u0006 זה \u0005דומה]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003לא איתחזק איסורא\u0004 \u0005[הוחזק האיסור],\u0006 שהרי לא היתה חזקה שחתיכה זו ודאי אסורה ולכן סומכים על העד שהתיר אותה, אבל \u0003הכא\u0004 \u0005[כאן]\u0006 הלא \u0003איתחזק איסורא\u0004 \u0005[הוחזק האיסור]\u0006 של \u0003אשת איש, ו\u0004כלל הוא: \u0003אין דבר שבערוה\u0004 נקבע על פי \u0003פחות משנים\u0004 המעידים!","אלא, \u0003הא לא דמיא\u0004 \u0005[זה אינו דומה]\u0006 \u0003אלא ל\u0004מקרה של \u0003חתיכה\u0004 שידוע לנו ש\u0003ודאי חלב\u0004 היא, \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003עד אחד, ואמר: ברי לי\u0004 ש\u0003שומן הוה\u0004 \u0005[היה],\u0006 \u0003דלא מהימן\u0004 \u0005[שאינו נאמן]!\u0006 ודוחים: \u0003מי דמי\u0004 \u0005[האם\u0006 זה \u0005דומה],\u0006 הרי \u0003התם\u0004 \u0005[שם],\u0006 כאשר מוחזק וברור לנו בודאי שחלב היא \u0003אפילו\u0004 אם \u0003אתו בי מאה לא מהימני\u0004 \u0005[יבואו מאה\u0006 עדים \u0005אינם נאמנים],\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003כיון דכי אתו בי תרי מהימני\u0004 \u0005[שכאשר יבואו שניים\u0006 יהיו \u0005נאמנים\u0006 שמת\u0005]\u0006 — \u0003חד נמי להימניה\u0004 \u0005[אחד גם כן נאמין לו],\u0006 \u0003מידי דהוה\u0004 \u0005[כמו שהוא]\u0006 הדין לגבי \u0003טבל, הקדש, וקונמות\u0004 (נדר שאדם אוסר על עצמו דבר כאילו הוא קרבן), שאף על פי שהוחזק האיסור — נאמן.","ושואלים: \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003טבל\u0004 שהבאנו כדוגמא, \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]?\u0006 \u0003אי דידיה\u0004 \u0005[אם שלו\u0006 הוא\u0005]\u0006 ומעיד עליו שהוא מתוקן, יש טעם אחר שמאמינים לו — \u0003משום\u0004 ש\u0003בידו לתקנו\u0004 בכל עת שירצה, ומה לו אם כן לשקר. \u0003אלא\u0004 אם תאמר שמעיד על טבל של \u0003אחר,\u0004 יש לדון, \u0003מאי קסבר\u0004 \u0005[מה הוא סבור]:\u0006","\u0003אי קא סבר\u0004 \u0005[אם הוא סבור]\u0006 שה\u0003תורם משלו על של חברו — אינו צריך דעת בעלים,\u0004 שיכול לתקן טבל של חבירו מתי שירצה, אם כן זה שמאמינים לו שהטבל מתוקן, הרי זה גם כן \u0003משום\u0004 ש\u0003בידו לתקנו. ואי קסבר\u0004 \u0005[ואם הוא]\u0006 ש\u0003צריך דעת בעלים\u0004 כדי לתרום, אלא שכאן הוא בא \u0003ואמר: אנא ידענא ביה דמתקן\u0004 \u0005[אני יודע בו ש\u0006הוא \u0005מתוקן],\u0006 ומקבלים את דבריו, אך \u0003היא גופה\u0004 \u0005[עצמה]\u0006 \u0003מנלן\u0004 \u0005[מניין לנו]?\u0006 ומדוע יהיה ברור הדין בטבל יותר מבעדות אשה.","כיוצא בו \u0003הקדש נמי\u0004 \u0005[גם כן],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 קדוש הוא רק ב\u0003קדושת דמים,\u0004 שאין זה קרבן אלא חפץ שהוקדש לצרכי המקדש, הרי הטעם שסומכים בזה על עד אחד המעיד שאין הוא קדוש עכשיו, הוא \u0003משום\u0004 ש\u0003בידו לפדותו\u0004 ובכך להפקיע קדושתו. \u0003ואי\u0004 \u0005[אם]\u0006 תאמר שהוא קדוש ב\u0003קדושת הגוף,\u0004 יש לברר: \u0003אי דידיה\u0004 \u0005[אם\u0006 הוא קרבן \u0005שלו]\u0006 — אף בכך נאמן \u0003משום\u0004 ש\u0003בידו לאיתשולי עליה\u0004 \u0005[להישאל עליו],\u0006 שילך לחכם והחכם יתיר לו את נדר ההקדש, כמו שהוא מתיר שאר נדרים. \u0003אלא\u0004 תאמר שהוא קרבן של \u0003אחר ואמר\u0004 אותו עד: \u0003ידענא ביה דאיתשיל מריה עליה\u0004 \u0005[יודע אני בו שנשאל בעליו עליו],\u0006 יש לשאול: \u0003היא גופה\u0004 \u0005[עצמה]\u0006 \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 שהוא נאמן?","\u0003קונמות נמי\u0004 \u0005[גם כן]\u0006 \u0003אי קסבר\u0004 \u0005[אם סבור הוא]\u0006 ש\u0003יש מעילה בקונמות,\u0004 ושדין קונם הוא כדין הקדש, \u0003וקדושת דמים נחתא להו\u0004 \u0005[ירדה עליהם],\u0006 יש לומר שנאמין לו שאין הוא קדוש עכשיו — \u0003משום\u0004 ש\u0003בידו לפדותו, ואי קסבר\u0004 \u0005[ואם סבור\u0006 הוא\u0005]\u0006 ש\u0003אין מעילה בקונמות, ואיסור בעלמא\u0004 \u0005[סתם]\u0006 \u0003הוא דרכיב להו אכתפיה\u0004 \u0005[שרוכב על כתיפו],\u0006 כלומר, יש בהם איסור של מעין־הקדש, ואין דינו כהקדש ממש, אולם גם אז אפשר לחלק: \u0003אי דידיה\u0004 \u0005[אם שלו\u0006 הוא\u0005]\u0006 הדבר שמעיד עליו — אפשר לומר \u0003משום\u0004 ש\u0003בידו לאיתשולי עליה\u0004 \u0005[להישאל עליו]\u0006 ולהתיר את הנדר,","\u0003אלא\u0004 תאמר שהוא קונם של \u0003אחר, ואמר\u0004 אותו עד: \u0003אנא ידענא דאיתשיל מריה עליה\u0004 \u0005[אני יודע שנשאל בעליו עליו],\u0006 והותר איסורו — \u0003היא גופה\u0004 \u0005[עצמה]\u0006 \u0003מנלן\u0004 \u0005[מניין לנו]?\u0006 ולאחר שנדחה טעם זה להסביר את הדין, נשארת השאלה במקומה: מדוע סומכים בעדות אשה על עד אחד בלבד?","\u0003אמר ר' זירא: מתוך חומר שהחמרת עליה\u0004 על אשה הנישאת על פי עד אחד \u0003בסופה,\u0004 שאם יתברר שהעדות לא היתה נכונה והבעל עודנו חי — מחמירים עליה ביותר והיא יוצאת נפגעת מכל צד — \u0003הקלת עליה בתחלה\u0004 שלא יזדקקו לשני עדים כדי להתירה ודי בעד אחד. ושואלים: \u0003לא ליחמיר\u0004 \u0005[נחמיר\u0006 בסופה\u0005]\u0006 \u0003ולא ליקיל\u0004 \u0005[נקל\u0006 בתחילתה\u0005]!\u0006","ומשיבים: \u0003משום עיגונא\u0004 \u0005[עיגון]\u0006 \u0003אקילו\u0004 \u0005[הקילו]\u0006 \u0003בה רבנן\u0004 \u0005[חכמים],\u0006 שהרי לא תמיד יש שני עדים על המוות, ואם לא יקלו לסמוך על עדותו של עד אחד עלולה האשה להישאר עגונה. אבל כדי שלא לגרום בכך לתקלה והפקרות, החמירו בה מאד בסופה כדי שתיזהר האשה ולא תקבל עדות בלתי מהימנה.","שנינו במשנה שאם אמרו לה שמת בעלה ונישאה על פי עדות זו, ואחר כך בא בעלה — \u0003תצא מזה ומזה וכו'. אמר רב: לא שנו אלא שניסת\u0004 (שנישאת) על פי \u0003עד אחד, אבל\u0004 אם \u0003ניסת על פי\u0004 עדות \u0003שני עדים — לא תצא. מחכו עליה במערבא\u0004 \u0005[צחקו עליו בארץ ישראל]\u0006 ואמרו: \u0003אתא גברא וקאי, ואת אמרת\u0004 \u0005[בא האיש\u0006 בעלה הראשון \u0005ועומד\u0006 לפנינו, \u0005ואתה אומר]\u0006 ש\u0003לא תצא\u0004 מבעלה השני? גם אם היו בשעתו שני עדים כשרים, הלא הוא עצמו עומד לפנינו! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקום, \u0003דלא ידעינן ליה\u0004 \u0005[שאין אנחנו יודעים,\u0006 מכירים \u0005אותו]\u0006 והוא טוען שהוא הבעל.","ושואלים: \u0003אי דלא ידעינן ליה\u0004 \u0005[אם\u0006 במקרה \u0005שאיננו יודעים,\u0006 מכירים \u0005אותו],\u0006 גם אם נישאה \u0003בעד אחד אמאי\u0004 \u0005[מדוע]\u0006 \u0003תצא?\u0004 נסמוך לגמרי על העד שאמר שמת! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה כזה: \u0003דאתו בי תרי ואמרי\u0004 \u0005[שבאו שניים\u0006 אחרים \u0005ואמרו]:\u0006 \u0003אנן הוינן בהדיה מכי נפק\u0004 \u0005[אנחנו היינו איתו מאז שיצא]\u0006 \u0003ועד השתא\u0004 \u0005[עכשיו],\u0006 \u0003ואתון הוא דלא ידעיתו ליה\u0004 \u0005[ואתם הם שאינכם מכירים אותו],\u0006 משום שהשתנה במשך הזמן, וכעין \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויכר יוסף את אחיו והם לא הכירהו\"\u0004 (בראשית מב, ח), \u0003ואמר רב חסדא:\u0004 פסוק זה \u0003מלמד שיצא\u0004 יוסף מאחיו \u0003בלא חתימת זקן, ובא,\u0004 כלומר, כשפגש אותם היה \u0003בחתימת זקן,\u0004 ולכן לא הכירוהו. ומכאן שעשויים אנשים להשתנות במשך השנים עד שלא יכירום אפילו קרוביהם.","ושואלים: אפילו במקרה זה, \u0003סוף סוף תרי ותרי נינהו\u0004 \u0005[שניים\u0006 מול \u0005שניים הם]\u0006 כי היו שני עדים שהעידו שאותו אדם מת, ועכשיו יש שני עדים שמעידים שהוא חי, ומדוע סומכים דווקא על העדים שאומרים שמת ולא תצא, הרי יש עדים אחרים שאומרים שהוא חי, והספק נשאר במקומו,"],["\u0003והבא עליה באשם תלוי קאי\u0004 \u0005[עומד,\u0006 מחוייב\u0005],\u0006 שכיון שיש עדים האומרים שהיא אשת איש, ועדים אחרים האומרים שהיא עכשיו אלמנה — נמצא שיש בכך ספק איסור כרת, וכל העושה בשגגה דבר שיש בו ספק שמא הוא איסור כרת — חייב להביא קרבן אשם תלוי. ובודאי שצריך לגרשה! \u0003אמר רב ששת:\u0004 מדובר \u0003כגון שניסת\u0004 (שנישאת) אותה אשה \u0003לאחד מעדיה\u0004 שהעידו שמת בעלה, והרי העד בטוח בדבר, ולגביו אין כאן אשם תלוי.","ושואלים: מכל מקום \u0003היא גופה\u0004 \u0005[עצמה]\u0006 כן \u0003באשם תלוי קיימא\u0004 \u0005[עומדת],\u0006 שהרי אינה יודעת את הדבר בוודאות, וסומכת רק על העדים! ומשיבים: \u0003באומרת \"ברי\u0004 (ברור) \u0003לי\",\u0004 שמשום מה היא בטוחה בדבר הזה, ובשבילה אין כאן ספק. ושואלים: \u0003אי הכי, מאי למימרא\u0004 \u0005[אם כך, מה\u0006 יש \u0005לומר]\u0006 דבר זה? שאם דברי רב מתייחסים רק למקרה זה, אין בהם איפוא כל חידוש, שהרי \u0003אפילו ר' מנחם בר' יוסי לא קאמר\u0004 \u0005[אמר]\u0006 מה שאמר \u0003אלא כשבאו עדים ואחר כך ניסת, אבל\u0004 אם \u0003ניסת ואחר כך באו עדים — לא אמר.\u0004","ומהו הענין — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שנים אומרים \"מת\"\u0004 בעלה של אשה זו \u0003ושנים אומרים \"לא מת\",\u0004 או ש\u0003שנים אומרים \"נתגרשה\"\u0004 אשה זו \u0003ושנים אומרים \"לא נתגרשה\" — הרי זו לא תנשא, ואם\u0004 בכל זאת \u0003ניסת\u0004 — \u0003לא תצא,\u0004 שהרי אין עדות ברורה כדי להוציאה. \u0003ר' מנחם בר' יוסי אמר: תצא. אמר ר' מנחם בר' יוסי: אימת\u0004 (מתי) \u0003אני אומר תצא — בזמן שבאו\u0004 ה\u0003עדים\u0004 השניים, אשר הכחישו את העדים הראשונים ואמרו שאין היא פנויה, \u0003ואחר כך ניסת\u0004 למרות העדות הסותרת. \u0003אבל\u0004 אם \u0003ניסת, ואחר כך באו עדים\u0004 המכחישים — \u0003הרי זו לא תצא!\u0004","ומשיבים: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003רב\u0004 את דבריו \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003בזמן שבאו\u0004 תחילה ה\u0003עדים\u0004 השניים והעידו בניגוד לעדות הראשונה שהוא חי \u0003ואחר כך ניסת,\u0004 ואפילו אז לדבריו לא תצא, ודבריו הם \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 \u0003מ\u0004דברי \u0003ר' מנחם בר' יוסי,\u0004 ולפסוק כתנא קמא. \u0003ואיכא דאמר\u0004 \u0005[ויש\u0006 מי \u0005שאומר]\u0006 שכך צריך להבין את דברי רב: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום שתחילה \u0003ניסת ואחר כך באו עדים, אבל\u0004 אם תחילה \u0003באו\u0004 ה\u0003עדים\u0004 השניים \u0003ואחר כך ניסת — תצא. כמאן\u0004 \u0005[כ\u0006דעת \u0005מי] —\u0006 \u0003כ\u0004דעת \u0003ר' מנחם בר' יוסי.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא\u0004 ממה ששנינו בברייתא: \u0003מנין שאם לא רצה\u0004 הכהן להיזהר מאשה פסולה — \u0003דפנו,\u0004 כלומר, כפה אותו במלקות, ובעל כורחו יהיה מקודש — \u0003תלמוד לומר\u0004 מן האמור בסוף פרשת איסורי כהונה: \u0003\"וקדשתו...\u0004 קדוש יהיה לך\u0003\"\u0004 (ויקרא כא, ח), כלומר, אפילו \u0003בעל כרחו.\u0004","ומעתה נברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 היה \u0005הדבר],\u0006 אם נאמר שמדובר בכהן שנשא ספק גרושה או ספק זונה, \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003לא ניסת לאחד מעדיה ולא קאמרה\u0004 \u0005[אמרה]\u0006 \u0003\"ברי לי\"\u0004 שהעדים המכחישים הם עדי אמת, וכי \u0003צריכא למימר\u0004 \u0005[האם צריך לומר]\u0006 \u0003דדפנו,\u0004 שיש לכפותו? שברור לנו שהוא עובר על איסור והיא עוברת על איסור וצריך להפרישו ממנה. \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 מדובר באופן ש\u0003ניסת לאחד מעדיה, וקאמרה\u0004 \u0005[ואמרה]\u0006 \u0003\"ברי לי\"\u0004 שעדות המכחישים אמת, \u0003ו\u0004בכל זאת \u0003קתני\u0004 \u0005[ושנה]\u0006 \u0003דפנו, אלמא, מפקינן לה מיניה\u0004 \u0005[מכאן\u0006 ש\u0005מוציאים אותה ממנו],\u0006 וקשה על רב שאמר שהנישאת על פי שניים לא תצא!","ומשיבים: \u0003איסור כהונה שאני\u0004 \u0005[שונה],\u0006 שבאיסור כהונה אנו מחמירים בספק כאילו היה זה ודאי. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"דפנו\"\u0004 שאמרו — \u0003דפנו בעדים,\u0004 שרק כשבאו עדים נוספים וביררו את הדבר, אומרים דפנו שלא תינשא לכתחילה, אבל נישאת כבר לא תצא. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 שזהו דווקא \u0003כשבאו עדים ואחר כך ניסת, ו\u0004ברייתא זו האומרת שבמקרה זה כופים אותו להוציאה, כשיטת \u0003ר' מנחם בר' יוסי היא.\u0004","\u0003רב אשי אומר: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לא תצא\" דקאמר\u0004 \u0005[שאמר]\u0006 \u0003רב\u0004 — כוונתו היתה: \u0003לא תצא מהיתירה הראשון\u0004 לבעלה הראשון. שכיון שנישאה בדין על פי עדים הרי מה שעשתה נחשב כאונס, וכשאר אנוסה היא ומותרת לחזור לבעלה הראשון.","ושואלים: אם זהו פירוש הדברים ו\u0003הא\u0004 \u0005[והרי]\u0006 כבר \u0003אמרה רב חדא זימנא\u0004 \u0005[פעם אחת],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003ניסת שלא ברשות\u0004 בית דין, אלא על פי עדים — \u0003מותרת לחזור לו. ואמר רב הונא אמר רב: הכי הלכתא\u0004 \u0005[כך ההלכה].\u0006 ואם כן הרי כבר אמר אותה הלכה שלא תצא מהיתרה הראשון! ומשיבים: \u0003חדא מכללא\u0004 \u0005[אחת מכלל]\u0006 \u0003חברתה איתמר\u0004 \u0005[נאמרה],\u0006 כלומר, רב לא אמר את שתי ההלכות במפורש, אלא אמר את אחת מהן, ואת השניה הסיקו מכלל דבריו.","\u0003אמר שמואל: לא שנו\u0004 שתצא האשה מבעלה השני, \u0003אלא\u0004 כ\u0003שלא מכחשתו\u0004 את העד שמעיד שבעלה חי, \u0003אבל\u0004 אם \u0003מכחשתו — לא תצא.\u0004 ומבררים: \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]\u0006 \u0003אילימא בבי תרי\u0004 \u0005[אם תאמר בשניים],\u0006 שבאו שני עדים והעידו שבעלה חי, \u0003כי מכחשתא ליה מאי הוי\u0004 \u0005[כאשר מכחישה אותו מה הוא\u0006 מה בכך\u0005]\u0006 הלא עדות זו כשרה ונאמנה לכל ענין! \u0003אלא בחד\u0004 \u0005[ב\u0006עד \u0005אחד],\u0006 ומעתה \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום ש\u0003מכחשתו, הא שתקה\u0004 \u0005[הרי\u0006 אם היא \u0005שותקת]\u0006 ואינה מכחישה — \u0003תצא.\u0004","ושואלים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003עולא: כל מקום,\u0004 בכל עדות \u0003שהאמינה\u0004 ה\u0003תורה\u0004 ל\u0003עד אחד, הרי כאן\u0004 עדות שיש לה תוקף כמו עדות של \u0003שנים, ו\u0004ממילא \u0003אין דבריו של אחד\u0004 המכחיש את העד הראשון נחשבים \u0003במקום שנים!\u0004 ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים] —\u0006 שאותם עדים שאמרו שלא מת היו \u0003פסולי עדות, וכ\u0004שיטת \u0003ר' נחמיה.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' נחמיה אומר: כל מקום שהאמינה\u0004 ה\u0003תורה\u0004 ל\u0003עד אחד — הלך\u0004 בעדות כזו \u0003אחר רוב דעות.\u0004 שבעדות כשרה, רואים שני עדים כעדות גמורה ומושלמת, ואין הבדל בין רבים ומעטים, ואילו כאן שאינה עדות גמורה, הולכים לפי מספר האנשים ואפילו הם פסולים, \u0003ועשו\u0004 במקרה זה ש\u0003שתי נשים\u0004 המעידות \u0003באיש אחד\u0004 (נגד עדות איש אחד שהעיד שמת) תיחשבנה \u0003כשני אנשים\u0004 המעידים \u0003באיש אחד\u0004 שאינו נחשב כשניים — ובטלה עדותו, אבל כשגם היא מכחישה אין הפסולים נאמנים.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כך: \u0003כל היכא דאתא\u0004 \u0005[מקום שבא]\u0006 \u0003עד אחד כשר מעיקרא\u0004 \u0005[מתחילה]\u0006 והעיד שמת הבעל — \u0003אפילו מאה נשים\u0004 מעידות שהוא חי — \u0003כעד אחד דמיין\u0004 \u0005[\u0006הן \u0005נחשבות]\u0006 ואינן נאמנות להכחישו, שהוא נחשב כשניים, ו\u0003הכא במאי עסקינן\u0004 \u0005[\u0006ו\u0005כאן במה אנו עוסקים]\u0006 \u0003כגון דאתיא\u0004 \u0005[שבאה]\u0006 \u0003אשה מעיקרא\u0004 \u0005[מתחילה]\u0006 והעידה.","\u0003ותרצה\u0004 \u0005[ותרץ,\u0006 הסבר, \u0005אותה],\u0006 את ההלכה של \u0003ר' נחמיה הכי\u0004 \u0005[כך],\u0006 \u0003ר' נחמיה אומר: כל מקום שהאמינה\u0004 ה\u0003תורה\u0004 ל\u0003עד אחד — הלך אחר רוב דעות, ועשו שתי נשים באשה אחת כשני אנשים באיש אחד. אבל שתי נשים באיש אחד — כפלגא ופלגא דמי\u0004 \u0005[כמחצה ומחצה\u0006 נחשבים\u0005].\u0006 ולענייננו, כיון שעדות האשה הראשונה שמת הבעל לא בטלה לגמרי, שבאו שתי נשים והכחישו אותה, אם האשה מצטרפת לעד הראשון — לא תצא.","שנינו במשנה שאם נישאה לאחר בטעות, וחזר בעלה — \u0003צריכה גט מזה ומזה.\u0004 ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 ש\u0003מ\u0004ה\u0003ראשון תבעי\u0004 \u0005[תצטרך]\u0006 \u0003גט,\u0004 שהרי אשתו גמורה היא, \u0003אלא מ\u0004ה\u0003שני, אמאי\u0004 \u0005[מדוע]\u0006 צריכה היא גט? הלא \u0003זנות בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא!\u0004 שכיון שהיה בעלה הראשון קיים לא תפסו כלל נישואיה לשני!","\u0003אמר רב הונא: גזירה\u0004 היא, \u0003שמא יאמרו\u0004 אנשים שלא ידעו את כל המעשה ש\u0003גירש זה\u0004 הבעל הראשון, \u0003ו\u0004אחר כך \u0003נשא זה\u0004 השני, \u0003ו\u0004אם תצא בלא גט, חושבים כי \u0003נמצאת אשת איש יוצאה בלא גט.\u0004 ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003סיפא דקתני\u0004 \u0005[סופה\u0006 של המשנה הבאה \u0005ששנינו]\u0006 בה: \u0003אמרו לה \"מת בעליך\" ונתקדשה\u0004 לאחר ועדיין לא נישאה לו, \u0003ואחר כך בא בעלה — מותרת לחזור לו\u0004 לבעלה הראשון. \u0003התם נמי נימא\u0004 \u0005[שם גם כן נאמר]\u0006 שמא יחשבו אנשים \u0003גירש זה וקדש זה, ונמצאת אשת איש יוצאה שלא בגט!\u0004","ומשיבים: \u0003לעולם\u0004 גם כשנתקדשה בלבד \u0003בעיא\u0004 \u0005[צריכה]\u0006 \u0003גט,\u0004 שאמנם מותרת היא לחזור לבעלה הראשון, אבל צריכה גט מן השני. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 יחשבו ש\u0003נמצא זה\u0004 כאילו \u0003מחזיר גרושתו משנתארסה\u0004 לאחר! ומשיבים: התנא שלנו סבור בענין זה \u0003כר' יוסי בן כיפר,\u0004 ש\u0003אמר\u0004 ככלל: גרושה שיצרה קשר עם אדם אחר, אם היה זה קשר \u0003מן הנשואין — אסורה\u0004 לחזור לבעלה הראשון, \u0003מן האירוסין — מותרת.\u0004 ואם כן, אין מקום לחשש.","ומקשים: \u0003הא מדקתני סיפא\u0004 \u0005[הרי מ\u0006מה \u0005ששנינו\u0006 ב\u0005סופה]:\u0006 \u0003אף על פי\u0004"],["\u0003שנתן לה אחרון גט — לא פסלה מן הכהונה,\u0004 ואינה נחשבת כלל כגרושה, \u0003מכלל\u0004 הדברים אתה למד \u0003דלא בעיא\u0004 \u0005[שאינה צריכה]\u0006 \u0003גט\u0004 ממנו, \u0003דאי בעיא\u0004 \u0005[שאם צריכה]\u0006 היא \u0003גט\u0004 אפילו מפני הספק, \u0003אמאי\u0004 \u0005[מדוע]\u0006 אם כן \u0003לא פסלה מן הכהונה?\u0004 שהרי כאשר יש לגט תוקף כלשהו, דיו כדי לפסול מכהונה! אלא ודאי יש לומר כי גט שנותן לאשה שאינה אשתו, אין בו כל ממש. \u0003אלא\u0004 כך צריך לומר: \u0003סיפא\u0004 \u0005[\u0006ב\u0005סוף\u0006 המשנה\u0005],\u0006 במקרה של קידושין, \u0003אמרי\u0004 \u0005[אומרים]\u0006 אנשים \u0003קידושי טעות הוו\u0004 \u0005[היו],\u0006 שאנשים סבורים שנתברר שהיתה טעות בקידושין, ולכן בטלו הקידושין מעיקרם ללא צורך בגט.","ושואלים: אם כן, \u0003רישא נמי\u0004 ב\u0005תחילה גם כן]\u0006 \u0003אמרי\u0004 \u0005[אומרים]\u0006 \u0003נישואי טעות הוו\u0004 \u0005[היו]?\u0006 ומשיבים: \u0003קנסוה רבנן\u0004 \u0005[חכמים]\u0006 בכל זאת שתצטרך גט, משום החשש שמא יאמרו גירש זה ונשא זה. ושואלים: אם כן \u0003סיפא נמי ליקנסוה\u0004 \u0005[\u0006במקרה שב\u0005סוף\u0006 המשנה \u0005גם כן שיקנסוה]!\u0006 ומשיבים: \u0003רישא, דעבדא איסורא\u0004 \u0005[\u0006במקרה שב\u0005תחילה, שעשתה איסור],\u0006 שנבעלה באיסור — \u0003קנסוה\u0004 חכמים, ואולם \u0003סיפא\u0004 \u0005[\u0006במקרה שב\u0005סוף],\u0006 ש\u0003לא עבדא איסורא\u0004 \u0005[עשתה איסור]\u0006 בקידושין בלבד — \u0003לא קנסוה רבנן\u0004 \u0005[חכמים].\u0006","שנינו במשנה שאשה זו \u0003אין לה כתובה.\u0004 ומסבירים: \u0003מאי טעמא תקינו\u0004 \u0005[מה טעם תיקנו]\u0006 \u0003לה רבנן\u0004 \u0005[חכמים]\u0006 \u0003כתובה\u0004 לאשה בכלל — \u0003כדי שלא תהא קלה בעיניו להוציאה,\u0004 שמתוך שצריך לטרוח להשיג כסף לפרעון כתובתה, הריהו מהרהר ומתחרט, אולם \u0003הא\u0004 \u0005[\u0006אשה \u0005זו]\u0006 אדרבא רצו חכמים ש\u0003תהא קלה בעיניו להוציאה,\u0004 שהרי נישואיה באיסור, ואסור לה להיות עמו, ולכן קנסוה שתצא בלי כתובה, כדי שימהר לגרש אותה.","עוד שנינו במשנה ש\u0003אין לה פירות ולא מזונות ולא בלאות.\u0004 ומדוע — \u0003תנאי כתובה,\u0004 כלומר, כל הזכויות שיש לאשה שהן כתנאי נוסף על הכתובה, \u0003ככתובה דמי\u0004 \u0005[\u0006הן \u0005נחשבות],\u0006 וכיון שאין לה כתובה — גם תנאי כתובה אין לה.","עוד שנינו שאם \u0003נטלה מזה ומזה,\u0004 מחזירה לזה ולזה. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 כיון שאמרנו שאין לה זכות לכך — ודאי שצריכה להחזיר! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003כיון\u0004 ש\u0003תפשה\u0004 כבר \u0003לא מפקינן מינה\u0004 \u0005[מוציאים ממנה],\u0006 שהרי רק קנס היה הדבר, ולא נטלה מה שלא היה שייך לה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף מוציאים ממנה.","שנינו במשנה ש\u0003הולד ממזר\u0004 מזה ומזה. לשם בירור הענין מביאים סוגיה אחרת, \u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]:\u0006 \u0003אין תורמין\u0004 תרומה \u0003מן הטמא על הטהור, ואם תרם\u0004 דבר טמא, \u0003בשוגג — תרומתו תרומה.\u0004 ואם עשה \u0003במזיד — לא עשה ולא כלום.\u0004 ונחלקו בשאלה: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003לא עשה ולא כלום? אמר רב חסדא: לא עשה ולא כלום כל עיקר,\u0004 ופירושו: ש\u0003אפילו ההיא גריוא הדר לטיבליה\u0004 \u0005[אותה סאה\u0006 שתרם, שהפרישה לתרומה \u0005חזרה ל\u0006היות \u0005טבל],\u0006 כמו שהיתה לפני כן, שאנחנו אומרים שכל מעשה התרומה בטל מעיקרו לגמרי.","\u0003רב נתן בר' אושעיא אמר: לא עשה ולא כלום,\u0004 הוא לענין, \u0003לתקן את השירים,\u0004 את התבואה שנשארה לאחר שהפריש ממנה תרומה, \u0003אבל תרומה הוי\u0004 \u0005[הריהי],\u0006 שחלה קדושת תרומה על מה שהפריש, אבל אין זה מועיל לתקן את תבואת החולין הטהורה. ומסבירים את שיטותיהם: \u0003רב חסדא לא אמר כרב נתן בר' אושעיא, דאי אמרת\u0004 \u0005[שאם אומר אתה]\u0006 \u0003הוי\u0004 \u0005[הריהי\u0006 נעשית\u0005]\u0006 \u0003תרומה,\u0004 יש לחשוש שמא \u0003זימנין דפשע\u0004 \u0005[פעמים ש\u0006הוא \u0005מתרשל]\u0006 \u0003ולא מפריש\u0004 עוד, מפני שהוא סבור שמאחר שתפסה קדושת תרומה במופרש, בודאי גם ניתקן כל מה שהיה צריך לתקן ונמצא שאוכל טבל.","ושואלים: \u0003מאי שנא מהא דתנן\u0004 \u0005[\u0006ב\u0005מה שונה\u0006 הדבר \u0005מזו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003התורם קישות\u0004 (מלפפון) \u0003ונמצאת מרה,\u0004 או \u0003אבטיח ונמצאת סרוח\u0004 — הרי זו \u0003תרומה, ו\u0004בכל זאת \u0003יחזור ויתרום\u0004 פעם נוספת קישות או אבטיח ראוי, ואין חוששים שמא לא יחזור ויתרום! ומשיבים: מ\u0003שוגג\u0004 על \u0003מזיד קרמית\u0004 \u0005[אתה מטיל,\u0006 מראה סתירה\u0005]?\u0006 הרי יש לחלק ביניהם כי \u0003שוגג לא עבד איסורא\u0004 \u0005[עשה איסור]\u0006 בכוונה ולא קנסוהו, מה שאין כן \u0003מזיד קעבד איסורא\u0004 \u0005[עשה איסור].\u0006","\u0003ורמי\u0004 \u0005[ומטילים,\u0006 מראים סתירה\u0005]\u0006 בין ענין \u0003שוגג אשוגג\u0004 \u0005[על שוגג]:\u0006 \u0003הכא קתני\u0004 \u0005[כאן שנה]\u0006 שאם תרם מן הטמא על הטהור \u0003בשוגג — תרומתו תרומה,\u0004 משמע לגמרי, שאינו צריך לחזור ולתרום, ואילו \u0003התם קתני\u0004 \u0005[שם\u0006 בפרי שהיה מקולקל \u0005שנה]\u0006 שהוא כן \u0003תרומה, ויחזור ויתרום!\u0004","ומסבירים: \u0003התם\u0004 \u0005[שם]\u0006 במקרה שהפרי היה מקולקל — הרי זה \u0003שוגג קרוב למזיד, דאיבעי ליה למיטעמיה\u0004 \u0005[שהיה צריך לטעום אותו]\u0006 תחילה וליבדוק מה הוא תורם, וכיון שלא בדק, יש בזה צד קרוב למזיד, ולכן קנסוהו שיחזור ויתרום, מה שאין כן בתרומה טמאה, שאינו יכול תמיד לברר את הדבר בשעת הפרשה.","\u0003ורמי\u0004 \u0005[ומטילים,\u0006 מראים סתירה\u0005]\u0006 מ\u0003מזיד\u0004 על \u0003מזיד: הכא קתני\u0004 \u0005[כאן שנה]\u0006 שאם תרם \u0003במזיד לא עשה כלום, התם תנן\u0004 \u0005[שם\u0006 במשנה \u0005שנינו]\u0006 במקרה אחר: \u0003התורם מ\u0004דבר הצומח בכלי \u0003שאין\u0004 (שאינו) \u0003נקוב\u0004 (שכיון שאין הכלי נקוב, אינו חייב בתרומה מן התורה כלל) \u0003על\u0004 מה שצמח בכלי \u0003נקוב\u0004 הנחשב כמחובר לקרקע, ונדון כמוה — הרי זו \u0003תרומה, ויחזור ויתרום,\u0004 ואין אומרים שכיון שצריך לחזור ולתרום לא תחול תרומה גם ממה שהפריש!","ומשיבים: \u0003בתרי מאני\u0004 \u0005[ב\u0006מקום שיש בו \u0005שני כלים] —\u0006 \u0003ציית\u0004 \u0005[מציית],\u0006 כיון שרואה שאחד נקוב ואחד איננו נקוב, אנחנו מניחים שאם נחייב אותו לחזור ולתרום יציית לדברי חכמים, מפני שהוא מבין את ההבדל, מה שאין כן \u0003בחד מנא לא ציית\u0004 \u0005[בכלי אחד\u0006 ש\u0005איננו מציית],\u0006 כיון שהטמא והטהור נראים בעיניו דומים זה לזה, ואם יאמרו לו שחלה קדושת תרומה על המופרש ובכל זאת צריך לחזור לתרום לא יציית לדברי חכמים ולא יתרום.","ושואלים מצד אחר: \u0003ול\u0004דעת \u0003רב נתן בר' אושעיא, ש\u0004\u0003אמר\u0004 כי \u0003לא עשה ולא כלום\u0004 כוונתו לענין \u0003לתקן שירים, אבל תרומה הוי\u0004 \u0005[הריהי]\u0006 נעשית, אם כן"],["\u0003מאי שנא מהא דתנן\u0004 \u0005[\u0006ב\u0005מה שונה\u0006 הדבר \u0005מזו ששנינו\u0006 במשנתנו\u0005]:\u0006 התורם \u0003מן הנקוב על שאין\u0004 (שאינו) \u0003נקוב — תרומתו תרומה, ולא תאכל עד שיוציא עליה תרומה ומעשר ממקום אחר.\u0004 כלומר, שמה שהפריש לתרומה לא חלה עליו קדושת תרומה לגמרי, ואף נחשב כטבל שחייבים לתקן אותו ולהפריש ממנו תרומה, ואילו המפריש תרומה טמאה, אינו צריך לתקן את המופרש!","ומשיבים: \u0003שאני הכא\u0004 \u0005[שונה כאן]\u0006 בענין התורם תרומה טמאה, \u0003דמדאורייתא\u0004 \u0005[שמן התורה]\u0006 בעצם \u0003תרומה מעלייתא\u0004 \u0005[מעולה]\u0006 \u0003היא,\u0004 ורק גזירת חכמים היא לקונסו. ו\u0003כ\u0004דברי \u0003ר' אלעאי,\u0004 ש\u0003אמר ר' אלעאי: מנין לתורם מן הרעה על היפה שתרומתו תרומה — דכתיב\u0004 \u0005[שנאמר]\u0006 בענין תרומה: \u0003\"ולא תשאו עליו חטא בהרימכם את חלבו ממנו\"\u0004 (במדבר יח, לב), \"חלבו\" — כוונתו המובחר שבו, כלומר, אם מפרישים לצורך תרומה מן המובחר — עושים בכך דבר ראוי שאין בו חטא, ומכאן משמע שאם מפרישים דבר גרוע — נושאים חטא על כך.","\u0003ואם אין\u0004 אותו דבר הגרוע שנתן \u0003קדוש\u0004 כלל בקדושת תרומה ולא עשה דבר — \u0003נשיאות חטא למה?\u0004 אלא \u0003מיכן\u0004 (מכאן) \u0003לתורם מן הרעה על היפה — שתרומתו תרומה\u0004 בדיעבד, ומכאן שגם המפריש מן הטמא על הטהור תרומתו תרומה מן התורה.","עד כאן לבירור השיטות עצמן, ומעתה לבירור נוסף, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה לרב חסדא: לדידך דאמרת\u0004 \u0005[לך,\u0006 לשיטתך \u0005שאומר אתה]\u0006 \u0003לא עשה ולא כלום כל עיקר,\u0004 והכוונה היא ש\u0003אפילו ההוא גריוא הדר לטיבליה\u0004 \u0005[אותה סאה\u0006 שתרם \u0005חוזרת ל\u0006היות \u0005טבל\u0006 כבתחילה\u0005],\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003גזירה דלמא פשע\u0004 \u0005[שמא יתרשל]\u0006 \u0003ולא מפריש\u0004 \u0005[יפריש]\u0006 פעם שניה, ואולם, \u0003מי איכא מידי דמדאורייתא הוי\u0004 \u0005[האם יש דבר שמן התורה הריהו]\u0006 \u0003תרומה\u0004 כפי שאמר ר' אלעאי, \u0003ומשום\u0004 החשש \u0003דלמא פשע אפקוה רבנן\u0004 \u0005[שמא יתרשל הוציאו אותה חכמים]\u0006 \u0003לחולין, וכי בית דין מתנין\u0004 כלומר, עושים תקנה, \u0003לעקור דבר מן התורה?\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ואת לא תסברא\u0004 \u0005[ואתה אינך סבור]\u0006 שיש כוח כזה ביד חכמים? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו פה\u0005]:\u0006 \u0003הולד ממזר מזה ומזה. בשלמא\u0004 \u0005[נניח]\u0006 מה שאמרו שהוולד \u0003משני ממזר\u0004 — מובן, שהרי הוא ילד שנולד לאשת איש שלא מבעלה, \u0003אלא מראשון אמאי\u0004 \u0005[מדוע]\u0006 יהיה הוולד ממזר? הלא \u0003אשתו היא, ו\u0004מן התורה \u0003ישראל מעליא\u0004 \u0005[מעולה]\u0006 \u0003הוא,\u0004 הבן, וכיון שגוזרים עליו חכמים שיהא ממזר, אין זה קנס בלבד אלא גם \u0003וקא שרינן ליה\u0004 \u0005[ומתירים אותו]\u0006 בכך \u0003בממזרת,\u0004 ונמצא שעוקרים איסור מן התורה משום גזירת חכמים!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר שמואל\u0004 בענין זה: הוולד מן הבעל הראשון אף על פי שנחשב כממזר, מכל מקום \u0003אסור בממזרת. וכן כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן: אסור בממזרת. ואמאי קרי ליה\u0004 \u0005[ומדוע קורא לו]\u0006 \u0003\"ממזר\"\u0004 — הרי זה רק להחמיר עליו \u0003לאוסרו בבת ישראל,\u0004 אבל לא להתירו בממזרת, ואין כאן איפוא עקירת איסור מן התורה.","\u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא לרבה ביד רב אחא בר רב הונא\u0004 ראיה אחרת: \u0003ו\u0004כי \u0003אין בית דין מתנין לעקור דבר מן התורה? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מאימתי אדם יורש את אשתו קטנה\u0004 שהשיאוה אמה או אחיה, כפי תקנת חכמים, ואינם נישואין גמורים מן התורה? \u0003בית שמאי אומרים: משתעמוד בקומתה,\u0004 כלומר, משתגדל ותגיע לפירקה בבגרות, \u0003ובית הלל אומרים: משתכנס לחופה, ר' אליעזר אומר: משתבעל.\u0004 וכאשר היא נחשבת לאשתו גמורה נוהג בה כאשתו לכל דבר, \u0003ויורשה, ומיטמא לה\u0004 אם היה כהן, \u0003ואוכלת בגינו\u0004 (בשלו) \u0003תרומה.\u0004","ותחילה מבררים כמה פרטים שבברייתא לגופם, \u0003בית שמאי אומרים: משתעמוד בקומתה.\u0004 ותוהים: \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 שעדיין \u0003לא נכנסה לחופה?\u0004 והרי אפילו אשתו גדולה אינו יורשה על ידי קידושין בלבד, אלא אם כן נכנסה גם לחופה! ומשיבים, \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003משתעמוד בקומתה ותכנס לחופה. והכי קאמרו ליה\u0004 \u0005[וכך אמרו להם]\u0006 \u0003בית שמאי לבית הלל: דקאמריתו\u0004 \u0005[שאומרים אתם]\u0006 \u0003משתכנס לחופה\u0004 — אין זה מספיק אלא, \u0003אי\u0004 \u0005[אם]\u0006 \u0003עמדה בקומתה — מהניא\u0004 \u0005[מועילה]\u0006 \u0003לה חופה, ואי\u0004 \u0005[ואם]\u0006 \u0003לא — לא מהניא\u0004 \u0005[מועילה]\u0006 \u0003לה חופה.\u0004","\u0003ר' אליעזר אומר: משתבעל.\u0004 ותוהים, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אליעזר: אין מעשה קטנה כלום,\u0004 וממילא אין לנישואיה ולבעילתה תוקף כמעשה קניין! אלא \u0003אימא\u0004 \u0005[אמור],\u0006 תקן והסבר: \u0003משתגדיל ותבעל.\u0004","\u0003קתני מיהת\u0004 \u0005[שנינו על כל פנים]\u0006 ש\u0003יורשה\u0004 — \u0003והא הכא, דמדאורייתא אבוה ירית לה\u0004 \u0005[והרי כאן, שמן התורה אביה יורש אותה]\u0006 ובמיתתו — קרובי אביה, שהרי מדין תורה אין נישואין לקטנה יתומה, \u0003ומדרבנן ירית לה\u0004 \u0005[ומדברי סופרים יורש אותה]\u0006 ה\u0003בעל?!\u0004 ומשיבים: אין מכאן ראיה, כי בענייני ממון \u0003הפקר בית דין הפקר,\u0004 ובוודאי יש כוח בידי חכמים להפקיר את ממונו,","ש\u0003אמר ר' יצחק: מנין שהפקר בית דין הפקר — שנאמר: \"\u0004ו\u0003כל אשר לא יבוא לשלשת הימים כעצת השרים והזקנים יחרם כל רכושו והוא יבדל מקהל הגולה\"\u0004 (עזרא י, ח), משמע שבית דין רשאי להחרים רכושו של אדם.","\u0003ר' אלעזר אמר\u0004 ראיה שהפקר בית דין הפקר, \u0003מהכא\u0004 \u0005[מכאן]:\u0006 \u0003\"אלה הנחלת אשר נחלו אלעזר הכהן ויהושע בן נון וראשי האבות למטות בני ישראל\"\u0004 (יהושע יט, נא), \u0003וכי מה ענין ראשים אצל אבות?\u0004 שהרי הביטוי \"ראשי האבות למטות\" אינו רגיל ואינו ברור, \u0003אלא לומר לך: מה אבות מנחילין בניהם כל מה שירצו — אף ראשים\u0004 (מנהיגי העם ושופטיו) \u0003מנחילין את העם כל מה שירצו.\u0004 משמע שראשי העם יכולים להפקיע רכוש של אדם אחד ולתתו לאחר.","שנינו שבעלה של הקטנה \u0003מיטמא לה,\u0004 ושואלים: \u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 \u0003דמדאורייתא\u0004 \u0005[שמן התורה]\u0006 \u0003אביה מיטמא לה\u0004 ולא זה שנשאה, שהרי אינה אשתו מדין תורה, \u0003ומדרבנן\u0004 \u0005[ומדברי סופרים]\u0006 \u0003מיטמא לה\u0004 ה\u0003בעל!\u0004 ומשיבים: הטעם כאן הוא \u0003משום דהויא לה\u0004 \u0005[שהריהי,\u0006 נעשית\u0005]\u0006 כ\u0003מת מצוה\u0004 שאפילו כהן מיטמא לו, שלאחר שנישאה אין הקרובים מבית אביה דואגים לה עוד, ונמצא שבעלה הוא היחיד שעליו מוטל הדבר.","ושואלים: \u0003ומי הוי\u0004 \u0005[והאם היא]\u0006 \u0003מת מצוה? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אי זהו מת מצוה — כל שאין לו קוברין,\u0004 ואם זה היה במקום שאם \u0003קורא ואחרים עונין אותו — אין זה\u0004 כבר \u0003מת מצוה,\u0004 ואשה זו הלא יש לה קרובים שיקברו אותה! ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003כיון דלא ירתי לה\u0004 \u0005[שאין\u0006 יורשיה מצד האב \u0005יורשים אותה]\u0006 — \u0003קריא ולא ענו\u0004 \u0005[\u0006היא \u0005קוראה ואין עונים]\u0006 \u0003לה,\u0004 שאינם רוצים לטפל בה. וכיון שהבעל יורשה, מוטלת עליו גם החובה לקוברה, ומיטמא לה כמת מצוה."],["\u0003ואוכלת בגינו תרומה\u0004 ומסבירים: המדובר דווקא \u0003בתרומה דרבנן\u0004 \u0005[\u0006ש\u0005מדברי סופרים]\u0006 ולא בתרומה שקדושתה מן התורה. ומנסים להביא ראיה לעיקר הדבר, \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 ראיה מברייתא: \u0003אכל תרומה טמאה\u0004 של כהן — \u0003משלם\u0004 לו \u0003חולין טהורים.\u0004 ואם \u0003שילם חולין טמאים\u0004 — \u0003סומכוס אומר משום\u0004 (בשם) \u0003ר' מאיר:\u0004 אם עשה זאת \u0003בשוגג — תשלומיו תשלומין, במזיד — אין תשלומיו תשלומין\u0004 כלל. \u0003וחכמים אומרים: אחד זה ואחד זה תשלומיו תשלומין,\u0004 וחלה עליהם קדושת תרומה, למרות שזו תרומה טמאה, \u0003וחוזר ומשלם חולין טהורין.\u0004","\u0003והוינן\u0004 \u0005[ועסקנו]\u0006 \u0003בה\u0004 בשאלה זו: מדוע לשיטת ר' מאיר כשמשלם לו חולין טמאים \u0003במזיד אין תשלומיו תשלומין?\u0004 אדרבה, צריך לומר — \u0003תבא עליו ברכה,\u0004 ש\u0003אכל מיניה מידי\u0004 \u0005[ממנו דבר]\u0006 \u0003דלא קחזי ליה\u0004 \u0005[שאינו ראוי לו]\u0006 אפילו \u0003בימי טומאתו,\u0004 שהרי תרומה טמאה טעונה שריפה, \u0003וקא משלם\u0004 \u0005[ומשלם]\u0006 לו חולין טמאים, שהם \u0003מידי דקחזי ליה\u0004 \u0005[דבר שראוי לו]\u0006 \u0003בימי טומאתו\u0004 (ואף שאחר כך כשחלה קדושה על התשלומים הם נעשים תרומה טמאה, מכל מקום בשעה ששילם נתן דבר הראוי).","\u0003ואמר רבא ואמרי לה כדי\u0004 \u0005[ו\u0006יש \u0005אומרים אותה,\u0006 את השמועה הזאת, \u0005סתם,\u0006 בלי שם אומרה\u0005]:\u0006 \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 הברייתא \u0005וכך\u0006 יש \u0005לשנותה]:\u0006 \u0003אכל תרומה טמאה — משלם כל דהו\u0004 \u0005[כלשהו,\u0006 כל דבר\u0005]\u0006 אפילו חולין טמאים. \u0003אכל תרומה טהורה — משלם חולין טהורין,\u0004 ואם \u0003שילם חולין טמאים\u0004 — בזה נחלקו, ש\u0003סומכוס אומר משום\u0004 (בשם) \u0003ר' מאיר: בשוגג — תשלומיו תשלומין, במזיד — אין תשלומיו תשלומין. וחכמים אומרים: בין בשוגג בין במזיד — תשלומיו תשלומין, וחוזר ומשלם חולין טהורין.\u0004","ומכאן לענייננו, \u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 \u0003דמדאורייתא תשלומי מעליא הוי\u0004 \u0005[שמן התורה תשלום מעולה,\u0006 גמור, \u0005הוא]\u0006 מה ששילם, ונעשה קניינו של הכהן לגמרי, \u0003דאי מקדש בהו\u0004 \u0005[שאם מקדש בהם]\u0006 \u0003כהן אשה — תפסו לה קידושי\u0004 \u0005[תופסים בה\u0006 ה\u0005קידושין],\u0006 \u0003ואמור רבנן\u0004 \u0005[ואמרו חכמים]\u0006 לשיטת סומכוס ש\u0003אין תשלומיו תשלומין, וקשרינן\u0004 \u0005[ומתירים אנו]\u0006 על ידי כך \u0003אשת איש לעלמא\u0004 \u0005[לעולם,\u0006 לכול\u0005].\u0006 נמצא שעל ידי קנס זה שמדברי סופרים אנו מבטלים את הקידושין, למרות שמן התורה הם חלים!","ומשיבים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003אין תשלומיו תשלומין דקאמר\u0004 \u0005[שאמר]\u0006 \u0003ר' מאיר\u0004 — כוונתו היא: \u0003דבעי למיהדר שלומי\u0004 \u0005[שצריך לחזור\u0006 ו\u0005לשלם]\u0006 \u0003חולין טהורין,\u0004 אבל קדושה חלה גם על מה שהפריש תחילה. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 היא שיטת \u0003סומכוס,\u0004 אם כן \u0003היינו\u0004 \u0005[זהו]\u0006 כדעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 שלפי פירוש זה שניהם אומרים אותו דבר!","ומשיבים: \u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא:\u0004 לענין \u0003קנסו שוגג אטו\u0004 \u0005[משום]\u0006 \u0003מזיד איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005].\u0006 ובזה הם חלוקים: שלדעת סומכוס אם הפריש בשוגג תשלומיו תשלומים ולא קנסו אותו שיחזור וישלם אחרים, ולדעת חכמים אפילו בשוגג צריך לחזור ולשלם אחרים, שגזרו שוגג משום מזיד.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 ראיה אחרת: \u0003דם\u0004 קרבנות \u0003שנטמא, וזרקו\u0004 על גבי המזבח, אם לא ידע שטמא היה וזרקו \u0003בשוגג — הורצה,\u0004 ונתקבל הקרבן, ויצא בו בעליו ידי חובתו. ואם זרקו \u0003במזיד — לא הורצה.\u0004","\u0003והא הכא דמדאורייתא ארצויי מרצה\u0004 \u0005[והרי כאן שמן התורה מרצה\u0006 הוא\u0005],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003על מה הציץ\u0004 של הכהן גדול \u0003מרצה — על הדם, ועל הבשר, ועל החלב שנטמא, בין בשוגג בין במזיד, בין באונס בין ברצון, בין ביחיד בין בצבור. ואמרי רבנן\u0004 \u0005[ואמרו חכמים]\u0006 כי במזיד \u0003לא הורצה\u0004 וצריך להביא קרבן אחר, אבל הקרבן האחר הרי לא היה חייב מן התורה, \u0003ו\u0004אם כן \u0003קא הדר מעייל\u0004 \u0005[וחוזר\u0006 ו\u0005מכניס]\u0006 \u0003חולין לעזרה!\u0004","\u0003אמר ר' יוסי בר חנינא:\u0004 אין מכאן ראיה, כי \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לא הורצה\" דקאמר\u0004 \u0005[שאמר] —\u0006 הכוונה היא לא הורצה עד כדי \u0003להתיר בשר\u0004 הקרבן \u0003באכילה, אבל בעלים נתכפרו בו,\u0004 ואינם חייבים בקרבן אחר.","ומקשים: \u0003סוף סוף קמתעקרא\u0004 \u0005[נעקרת]\u0006 \u0003אכילת בשר\u0004 מקרבן זה, שמדין תורה היה מצוה לאכול אותו, \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ואכלו אתם אשר כפר בהם\"\u0004 (שמות כט, לג), \u0003מלמד\u0004 בכתוב זה \u0003שהכהנים אוכלים ובעלים מתכפרים\u0004 על אכילה זו! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שב ואל תעשה שאני\u0004 \u0005[שונה].\u0006 שיש לומר כי בידי חכמים רשות לעקור מצוה מן התורה על ידי \"שב ואל תעשה\", כלומר, על ידי מניעה מלעשות דבר, אבל אין בכוחם לעקור מצוה בעשיית מעשה בפועל."],["\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא לרבה: \u0003בעאי לאותובך\u0004 \u0005[רציתי להקשות עליך]\u0006 מדין \u0003ערל,\u0004 שגזרו חכמים במי שהתגייר בערב פסח שאסור לו לאכול בקרבן פסח, משום שנחשב כטמא, אף שחובה עליו מן התורה להקריב, ומדין \u0003הזאה\u0004 של מי חטאת לטהר את מי שנטמא במת, שאוסרים חכמים להזות על הטמא בערב פסח שחל להיות בשבת, למרות שבכך מבטלים אותו ממצות קרבן פסח.","\u0003ו\u0004מדין \u0003אזמל\u0004 של מילה, שגזרו חכמים שלא להוליכו בשבת, אף על פי שמבטלים בכך מצות מילה בזמנה שהיא מהתורה, ומדין \u0003סדין\u0004 של פשתן, שאסרו חכמים להטיל \u0003ב\u0004סדין \u0003ציצית\u0004 של צמר, גזירה משום כסות לילה שפטורה מציצית, שאם היו בה ציציות צמר חייב על לבישתה משום שעטנז, ומבטלים בכך מצות ציצית.","\u0003ו\u0004כן מדין \u0003כבשי עצרת,\u0004 שגזרו חכמים שלא לזרוק דמם של כבשי עצרת שנשחטו שלא לשמם כשחלה עצרת בשבת, אף על פי שמן התורה אין זריקה זו אסורה ובכך מבטלים שלוש מצוות שמן התורה: זריקת הדם, הקטרת אימורים ואכילת הבשר. \u0003ו\u0004כן \u0003שופר\u0004 שמצוה לתקוע בו בראש השנה, וגזרו חכמים שלא לתקוע בו כשחל בשבת, שמא יטלטלנו ארבע אמות ברשות הרבים.","\u0003ו\u0004כן \u0003לולב\u0004 שבגזירת חכמים אין נוטלים אותו ביום הראשון של חג הסוכות שחל בשבת, מאותו הטעם. \u0003השתא דשנית לן\u0004 \u0005[עכשיו שתרצת לנו]\u0006 כי \u0003\"שב ואל תעשה\" לא מיעקר הוא\u0004 \u0005[איננו\u0006 נקרא \u0005עקירה],\u0006 \u0003כולהו נמי\u0004 \u0005[כל אלה גם כן]\u0006 \u0003\"שב ואל תעשה\" נינהו\u0004 \u0005[הם].\u0006","\u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 ראיה אחרת, נאמר לגבי נביא אמת: \u0003\"אליו תשמעון\"\u0004 (דברים יח, טו) — \u0003אפילו אומר לך\u0004 הנביא: \u0003עבור על אחת מכל מצות שבתורה, כגון אליהו בהר הכרמל\u0004 שהקריב קרבן לה' בזמן שיש איסור כרת להקריב קרבנות מחוץ לבית המקדש, \u0003הכל\u0004 אם מתיר \u0003לפי שעה — שמע לו.\u0004 משמע שעוקרים דבר מן התורה על ידי מעשה!","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אליו תשמעון\"\u0004 ומצות עשה היא לשמוע בקול הנביא, ועשה זה דוחה מצות לא תעשה. ושואלים: \u0003וליגמר מיניה\u0004 \u0005[ושנלמד ממנו]\u0006 גם לדברי חכמים, שכוחם לענין זה ככוח הנביא! ומשיבים: \u0003מיגדר מילתא שאני\u0004 \u0005[לגדור דבר\u0006 זה \u0005שונה].\u0006 שכיון שנעשה הדבר כדי לעשות תקנה ולהרחיק את ישראל מעבודה זרה, בכגון זה מותר לעקור דבר מן התורה במעשה, אבל אין חכמים רשאים לעשות כן משום גזירה או חשש בלבד.","\u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 ראיה ממקום אחר: אמרו חכמים שלא יבטל אדם גט ששלח לאשתו לאחר שמסרו לשליח, בלי ידיעת האשה שמא תחשוב שהיא גרושה ותינשא לאחר באיסור. ואם \u0003בטלו\u0004 בכל זאת — \u0003מבוטל,\u0004 אלו \u0003דברי רבי. רבן שמעון בן גמליאל אומר: אינו יכול לא לבטלו, ו\u0004גם \u0003לא להוסיף על תנאו\u0004 שהיה בו. ש\u0003אם כן,\u0004 שיכול לבטלו — \u0003מה כח בית דין יפה\u0004 שגזרו שלא יבטל.","\u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 בגט זה, \u0003דמדאורייתא\u0004 \u0005[שמן התורה]\u0006 \u0003בטל\u0004 ה\u0003גט ומשום\u0004 הטעם של \u0003\"מה כח בית דין\"\u0004 אין הביטול נחשב ו\u0003קא שרינן\u0004 \u0005[\u0006ו\u0005מתירים אנו]\u0006 על ידי כך \u0003אשת איש לעלמא\u0004 \u0005[לעולם,\u0006 להינשא לכל אדם\u0005]!\u0006 ומשיבים: מדיני נישואין אין ראיה, כי \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003מקדש\u0004 אשה — \u0003אדעתא דרבנן\u0004 \u0005[על דעת חכמים]\u0006 הוא \u0003מקדש, ו\u0004במקרה כזה \u0003אפקעינהו רבנן\u0004 \u0005[הפקיעו חכמים]\u0006 את ה\u0003קידושין\u0004 קידש אותה בתחילה,","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: התינח דקדיש בכספא\u0004 \u0005[זה נוח\u0006 במקרה \u0005שקידש בכסף]\u0006 שאז אפשר לומר שהפקירו חכמים את כסף הקידושין וממילא בטלו הקידושין, אולם אם \u0003קדיש\u0004 \u0005[קידש]\u0006 \u0003בביאה, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: \u0003שויוה רבנן\u0004 \u0005[עשו אותה חכמים]\u0006 \u0003לבעילתו\u0004 שבעל אותה, כ\u0003בעילת זנות.\u0004 שהרי אף כאן הקידושין, כלומר, כוח הקנין שבדבר, הוא על דעת חכמים, והם אמרו שבמקרה כזה לא ייחשב הדבר לקנין.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 \u0003אמר ר' אלעזר בן יעקב: שמעתי שבית דין מכין ועונשין שלא מן התורה,\u0004 כלומר, בדברים שלא נאמר בתורה שיש להעניש עליהם, \u0003ולא\u0004 משום \u0003לעבור\u0004 (שעברו) \u0003על דברי תורה, אלא לעשות סייג לתורה. ו\u0004כגון \u0003מעשה באדם אחד שרכב על סוס בשבת בימי יונים,\u0004 ורכיבה על סוס אינה אסורה אלא מדברי סופרים — \u0003והביאוהו לבית דין וסקלוהו\u0004 כמחלל שבת, \u0003לא מפני ש\u0004היה \u0003ראוי לכך,\u0004 שהרי, כאמור, אין ברכיבה איסור סקילה, \u0003אלא שהשעה\u0004 היתה \u0003צריכה לכך\u0004 שהיו מזלזלים באיסורי שבת.","\u0003ושוב מעשה באדם אחד שהטיח\u0004 (בעל) \u0003באשתו\u0004 שלו \u0003תחת התאנה\u0004 בחוץ, \u0003והביאוהו לבית דין והלקוהו, לא מפני שראוי לכך\u0004 שהרי אין איסור תורה אם הוא בועל את אשתו בכל מקום שירצה, \u0003אלא שהשעה\u0004 היתה \u0003צריכה לכך\u0004 מפני שרצו למעט את הפריצות. משמע שבית דין עוקרים דבר מן התורה אפילו על ידי מעשה בפועל כמו סקילה! ומשיבים: \u0003מיגדר מילתא שאני\u0004 \u0005[לגדור דבר שונה]\u0006 ובזה כבר אמרנו שבית דין (כנביא) מותר להם לעקור דבר מן התורה, כדי לחזק את קיום התורה בכללה.","שנינו במשנה: \u0003ולא זה וזה\u0004 בעלה הראשון והשני \u0003מטמאין לה\u0004 אם היו כהנים. ושואלים: \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 הדבר? ומסבירים: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי אם לשארו הקרב אליו\"\u0004 (ויקרא כא, ב), \u0003ואמר מר\u0004 \u0005[החכם]:\u0006 \u0003\"שארו\" — זו אשתו,\u0004","\u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"לא יטמא בעל בעמיו להחלו\"\u0004 (שם ד), וכדי שלא תהיה סתירה בפסוקים יש לומר ש\u0003יש בעל שמיטמא\u0004 לאשתו, \u0003ויש בעל שאין מיטמא. הא כיצד? מיטמא הוא לאשתו\u0004 ה\u0003כשרה, ואינו מיטמא לאשתו\u0004 ה\u0003פסולה\u0004 וכיון שזו פסולה לשניהם אינם מיטמאים לה.","עוד שנינו במשנה ש\u0003לא זה וזה זכאין במציאתה וכו'.\u0004 ומסבירים: \u0003טעמא מאי אמור רבנן\u0004 \u0005[מה טעם אמרו חכמים]\u0006 ש\u0003מציאת אשה\u0004 שייכת \u0003לבעלה — כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא תיהוי ליה\u0004 \u0005[תהיה לו]\u0006 \u0003איבה\u0004 כלפיה, אם היא מוצאת דבר ואיננה נותנת לו, ומשתמשת בדברים לעצמה. אבל \u0003הכא — תיהוי ליה\u0004 \u0005[כאן\u0006 ש\u0005תהיה לו]\u0006 \u0003איבה ואיבה,\u0004 שהרי אנו רוצים שיוציאנה.","\u0003ו\u0004כן שנינו במשנה ששניהם אינם זכאים \u0003במעשה ידיה. טעמא מאי אמרי רבנן\u0004 \u0005[מה טעם אמרו חכמים]\u0006 ש\u0003מעשה ידיה\u0004 של אשה שייכים \u0003לבעלה — משום דקאכלה מזוני\u0004 \u0005[שאוכלת מזונות]\u0006 משלו, \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003כיון דמזוני לית\u0004 \u0005[שמזונות אין]\u0006 \u0003לה\u0004 ממנו — \u0003מעשה ידיה לאו דידיה\u0004 \u0005[אינם שלו].\u0006","\u0003ו\u0004עוד שנינו: \u0003לא מיפר נדריה,\u0004 ומסבירים: \u0003טעמא מאי אמר רחמנא\u0004 \u0005[מה טעם אומרת התורה]\u0006 כי \u0003בעל מיפר\u0004 את נדרי אשתו — \u0003כדי שלא\u0004 תידור נדר כזה שתגרום בכך ש\u0003תתגנה\u0004 עליו על ידי נדר זה, כגון שלא תתרחץ או תתקשט, \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003תתגנה ותתגנה,\u0004 שהרי רוצים אנו שיוציאנה.","עוד שנינו במשנה: \u0003היתה בת ישראל — נפסלה מן הכהונה וכו'.\u0004"],["\u0003פשיטא\u0004 \u0005[פשוט]\u0006 הוא שנפסלה, הרי זונה היא! ומשיבים: \u0003בת לוי מן המעשר איצטריכא ליה\u0004 \u0005[נצרכה לו\u0006 לומר\u0005]\u0006 ואגב כך גם אמר בת ישראל מן הכהונה.","ושואלים: \u0003ובת לוי מן המעשר מי מיפסלא\u0004 \u0005[האם\u0006 היא \u0005נפסלת]\u0006 \u0003ב\u0004של \u0003זנות? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לויה שנשבית\u0004 ויש חשש שנבעלה על ידי אחד השובים, \u0003או ש\u0004ודאי \u0003נבעלה בעילת זנות — נותנין לה מעשר, ואוכלת.\u0004 משמע שזנות איננה פוסלת מאכילת מעשר! \u0003אמר רב ששת: קנסא\u0004 \u0005[קנס]\u0006 הוא, שקנסו אשה זו במיוחד על שלא דקדקה, ונישאה בלא עדים.","שנינו במשנה: \u0003בת כהן\u0004 נפסלת \u0003מן התרומה.\u0004 ומסבירים: אין הדבר חידוש לגבי תרומה מן התורה, שהרי ודאי פסולה היא מלאוכלה, אלא \u0003אפילו בתרומה דרבנן\u0004 \u0005[שמדברי סופרים]\u0006 גזרו עליה שלא תאכל.","עוד שנינו במשנה: \u0003ואין יורשיו של זה ויורשיו של זה יורשין כתובתה וכו'.\u0004 ושואלים: \u0003כתובה מאי עבידתה\u0004 \u0005[מה מעשיה,\u0006 מה עניינה כאן\u0005]\u0006 הרי אמרנו שאין לה כתובה! ומשיבים: \u0003אמר רב פפא: כתובת בנין דיכרין\u0004 \u0005[בנים זכרים],\u0006 שאחד מתנאי הכתובה הוא שבנים זכרים שייוולדו לאשה זו כשיירשו את אביהם יקבלו סכום כתובת אמם יתר על ירושתם עם שאר אחיהם.","ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, שכיון שאין לה כתובה — אין גם תנאי כתובה! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי דווקא \u0003לדידה דעבדא איסורא\u0004 \u0005[לה\u0006 עצמה \u0005שעשתה איסור]\u0006 \u0003קנסוה רבנן\u0004 \u0005[חכמים],\u0006 אולם \u0003לזרעה לא קנסו רבנן\u0004 \u0005[חכמים],\u0006 שהרי הם לא חטאו — על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שבטלה הכתובה וכל התנאים הכתובים בה.","שנינו במשנה: \u0003אחיו של זה ואחיו של זה חולצין ולא מייבמין.\u0004 ומסבירים: \u0003אחיו של ראשון חולץ — מדאורייתא\u0004 \u0005[מ\u0006דין \u0005תורה]\u0006 שהרי בעצם היא אשתו של הראשון, וצריך לחלוץ לה. \u0003ולא מייבם — מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 שהרי קנסו בה שלא תחזור לבעלה הראשון. \u0003אחיו של שני חולץ — מדרבנן\u0004 \u0005[מדברי סופרים],\u0006 כדי שלא יאמרו שאשה שלא היו לה בנים יצאה בלא חליצה, \u0003ולא מייבם — לא מדאורייתא\u0004 \u0005[מ\u0006דברי \u0005תורה]\u0006 \u0003ולא מדרבנן\u0004 \u0005[מ\u0006דברי \u0005סופרים],\u0006 שהרי נישואיה לשני היו בטעות.","שנינו במשנה ש\u0003ר' יוסי אומר: כתובתה על נכסי בעלה\u0004 הראשון. \u0003אמר רב הונא: בתראי\u0004 \u0005[\u0006החכמים \u0005האחרונים],\u0006 כלומר, ר' אלעזר ור' שמעון \u0003מודו לקמאי\u0004 \u0005[מודים לראשונים]\u0006 ומוסיפים על דבריהם. אבל \u0003קמאי לא מודו לבתראי\u0004 \u0005[הראשונים אינם מודים לאחרונים],\u0006 שדברי הראשונים הם רק במה שפירשו, והאחרונים באו והוסיפו עליהם.","ומפרטים: \u0003ר' שמעון מודי ליה\u0004 \u0005[מודה לו]\u0006 \u0003לר' אלעזר.\u0004 ומדוע: שכן \u0003מה ביאה\u0004 שהיא \u0003עיקר איסורא\u0004 \u0005[האיסור]\u0006 הוא \u0003לא קניס\u0004 \u0005[קונס],\u0006 שהרי הוא אומר שביאתה על ידי יבם, אחי בעלה הראשון, קונה אותה קנין גמור עד שפוטרת את צרתה, \u0003וכל שכן מציאתה ומעשה ידיה דממונא\u0004 \u0005[ש\u0006ענין \u0005ממון]\u0006 בלבד \u0003הוא,\u0004 ודאי שזוכה בהם בעלה הראשון. \u0003ור' אלעזר לא מודי ליה\u0004 \u0005[מודה לו]\u0006 \u0003לר' שמעון,\u0004 ומדוע — \u0003מציאתה ומעשה ידיה דממונא\u0004 \u0005[ש\u0006ענין \u0005ממון]\u0006 \u0003הוא —\u0004 הריהו \u0003לא קניס\u0004 \u0005[קונס],\u0006 \u0003אבל ביאה דאיסורא\u0004 \u0005[ש\u0006ענין \u0005איסור]\u0006 \u0003הוא — קניס\u0004 \u0005[קונס].\u0006","\u0003ותרוייהו מודו ליה\u0004 \u0005[ושניהם מודים לו]\u0006 \u0003לר' יוסי\u0004 לענין כתובה, שאם \u0003הני דיתבא תותיה\u0004 \u0005[אלה\u0006 הדברים שעושה כ\u0005שיושבת תחתיו]\u0006 ונוהג בה כבאשה נשואה \u0003לא קניס\u0004 \u0005[קונס]\u0006 ומציאתה ומעשה ידיה שלו, ונחשבת כאשתו, \u0003וכל שכן כתובה דלמשקל ומיפק קאי\u0004 \u0005[שלקחת ולצאת\u0006 היא \u0005עומדת],\u0006 ובוודאי לא קנסוה בכתובה. \u0003ו\u0004אילו \u0003ר' יוסי לא מודי להו\u0004 \u0005[מודה להם],\u0006 שהוא סבור כי \u0003כתובה דלמשקל ומיפק\u0004 \u0005[ש\u0006היא \u0005לקחת ולצאת] —\u0006 \u0003הוא\u0004 ש\u0003לא קניס\u0004 \u0005[קנס]\u0006 בה, \u0003אבל הני\u0004 \u0005[\u0006תנאים \u0005אלה]\u0006 המתקיימים \u0003דיתבא תותיה\u0004 \u0005[\u0006כ\u0005שיושבת\u0006 עדיין \u0005תחתיו] —\u0006 \u0003קניס\u0004 \u0005[קונס]\u0006 בכך.","ואילו \u0003ר' יוחנן אמר: קמאי מודו לבתראי, בתראי לא מודו לקמאי\u0004 \u0005[\u0006ה\u0005ראשונים מודים לאחרונים\u0006 אך ה\u0005אחרונים אינם מודים לראשונים],\u0006 שלדעתו דברי הראשונים כוללים יותר, ודברי האחרונים מגבילים ומצמצמים אותם. כיצד? \u0003ר' יוסי מודי ליה\u0004 \u0005[מודה לו]\u0006 \u0003לר' אלעזר,\u0004 וכך הוא מסביר את טעמיהם: אם \u0003כתובה, דמדידיה לדידה\u0004 \u0005[ש\u0006הוא נותן \u0005ממנו אליה]\u0006 — הריהו \u0003לא קניס\u0004 \u0005[קונס]\u0006 בה, וסבור שכיון שלא עשתה בזדון מגיעה לה כתובה, \u0003וכל שכן מציאתה ומעשה ידיה דמדידה לדידיה\u0004 \u0005[שממנה אליו],\u0006 שדבר שהיא חייבת לתת לו אין לקנוס אותו בהם, וודאי שהיא צריכה לתת לו.","\u0003ור' אלעזר לא מודי ליה\u0004 \u0005[מודה לו]\u0006 בכתובה, כי \u0003מציאתה ומעשה ידיה הוא דמדידה לדידיה\u0004 \u0005[\u0006כיון \u0005שממנה אליו]\u0006 — הריהו \u0003לא קניס\u0004 \u0005[קונס],\u0006 \u0003אבל כתובה דמדידיה לדידה\u0004 \u0005[שממנו אליה] — הריהו\u0006 \u0003קניס\u0004 \u0005[קונס]\u0006 אותה שלא תקבל ממנו.","\u0003ותרוייהו מודו ליה\u0004 \u0005[ושניהם מודים לו]\u0006 \u0003לר' שמעון,\u0004 וטעמם: \u0003ומה הני\u0004 \u0005[אלה]\u0006 שהם ניתנים \u0003מחיים — לא קנסי\u0004 \u0005[קונסים]\u0006 בהם, \u0003ביאה\u0004 של יבם ש\u0003לאחר מיתה\u0004 של הבעל היא — \u0003לא כל שכן\u0004 שלא יקנסו אותה, ומותרת. \u0003ו\u0004אילו \u0003ר' שמעון לא מודי להו\u0004 \u0005[מודה להם],\u0006 כי רק \u0003ביאה הוא\u0004 שהיא \u0003לאחר מיתה\u0004 ולכן הוא \u0003לא קניס\u0004 \u0005[קונס]\u0006 בה, \u0003אבל הני\u0004 \u0005[אלה]\u0006 הדברים שהם באים \u0003מחיים\u0004 של הבעל, בזה \u0003קניס\u0004 \u0005[קונס]\u0006 אותה ומפסידה.","שנינו במשנה שלדעת ר' שמעון אם \u0003נשאת שלא ברשות\u0004 — מותרת לחזור לו. \u0003אמר רב הונא אמר רב: הכי הלכתא\u0004 \u0005[כך הלכה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן: גנבא גנובי\u0004 \u0005[לגנוב\u0006 דברים\u0005]\u0006 \u0003למה לך?\u0004 כלומר, למה לך לומר דבריך בדרך עקיפין והסתר ולא לאומרם במפורש? \u0003אי סבירא לך\u0004 \u0005[אם סבור אתה]\u0006 \u0003כר' שמעון — אימא\u0004 \u0005[אמור]\u0006 במפורש: \u0003הלכה כ\u0004דעת \u0003ר' שמעון, דשמעתיך\u0004 \u0005[ש\u0006הרי \u0005שמועתך,\u0006 ההלכה שלך\u0005]\u0006 \u0003כ\u0004דעת \u0003ר' שמעון קאזלה\u0004 \u0005[\u0006היא \u0005הולכת,\u0006 תואמת\u0005]\u0006.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003אי אמינא\u0004 \u0005[אם אומר]\u0006 \u0003הלכה כ\u0004דעת \u0003ר' שמעון,\u0004 יהיה \u0003משמע אפילו בקמייתא\u0004 \u0005[בראשונה],\u0006 כלומר, באשת איש שנישאת בעד אחד, אם כן \u0003אימא\u0004 \u0005[אמור]\u0006 בלשון זו: \u0003הלכה כר' שמעון באחרונה!\u0004 ומעירים, אכן \u0003קשיא\u0004 \u0005[קשה]\u0006 שלא פירש רב הונא את הדברים בצורה זו.","\u0003אמר רב ששת: אמינא\u0004 \u0005[אומר אני]\u0006 \u0003כי ניים ושכיב\u0004 \u0005[כאשר נמנם ושכב]\u0006 \u0003רב אמרה להא שמעתתא\u0004 \u0005[את ההלכה הזו],\u0006 כלומר, לא דקדק יפה בדבר, כי ההלכה שקבע איננה נחוצה שהרי אם קבע \u0003הלכה — מכלל דפליגי\u0004 \u0005[מכאן שחולקים]\u0006 אחרים עליו, אולם בענין זה אין כל מחלוקת, כי \u0003מאי הוה\u0004 \u0005[מה היה]\u0006 \u0003לה למיעבד\u0004 \u0005[לעשות]\u0006 — הרי כאילו \u0003מיאנס\u0004 \u0005[לאנוס]\u0006 \u0003אנסה,\u0004 שהלא מה שעשתה, באונס עשתה, שכיון שהיה הדבר ברור לפי העדים שהיא מותרת — מדוע לא תינשא, והרי פשוט שהאנוסה מותרת לבעלה?","\u0003ועוד תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003כל עריות שבתורה אין צריכות הימנו גט\u0004 אפילו כאשר נשא אחת מהן בדרך נישואין כשרים \u0003חוץ מאשת איש שניסת על פי בית דין.\u0004 ונדייק מכאן: הנישאת \u0003על פי בית דין הוא דבעיא גיטא\u0004 \u0005[שצריכה גט],\u0006 ואילו הנישאת \u0003על פי עדים לא בעיא גיטא\u0004 \u0005[אינה צריכה גט],\u0006","ונברר: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]\u0006 ברייתא זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהיא כדעת \u0003ר' שמעון,\u0004 אולם לדעתו זו הנישאת \u0003על פי בית דין מי בעיא\u0004 \u0005[האם צריכה]\u0006 \u0003גט\u0004 משני? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון אומר: עשו בית דין בהוראתן,\u0004 כאשר הורו לאשה להינשא ובא בעלה, כאילו היה זה \u0003זדון איש באשה,\u0004 וקונסים אותה בכל הדברים כאילו היתה זו ביאה בזדון. ואם נישאה \u0003על פי עדים\u0004 — עושים זאת \u0003כשגגת איש באשה.\u0004 ועל כל פנים \u0003אידי ואידי לא בעיא\u0004 \u0005[זו וזו אינה צריכה]\u0006 \u0003גט.\u0004 שוודאי אין אשת איש שנאפה (בזדון או בשוגג) צריכה לקבל גט מן הנואף.","\u0003אלא לאו רבנן\u0004 \u0005[האם לא\u0006 כשיטת \u0005חכמים]\u0006 \u0003היא\u0004 ברייתא זו האומרת שעריות אינן צריכות גט וגם הנישאת על פי עדים בכלל זה, ואם כן, לא היה צורך לפסוק שהלכה כדעה זו — כי בזה מודים הכל.","ודוחים: \u0003לעולם\u0004 תפרש שברייתא זו כדעת \u0003ר' שמעון היא, ותריץ הכי\u0004 \u0005[ותרץ,\u0006 ישב אותה \u0005כך],\u0006 \u0003ר' שמעון אומר: עשו בית דין בהוראתן\u0004 — הרי זה \u0003ככוונת איש באשה,\u0004 כמו איש שבא על אשה מתוך כוונה לשאתה, \u0003ו\u0004אם כן \u0003בעיא\u0004 \u0005[צריכה]\u0006 \u0003גט\u0004 ממנו, וכשנישאת \u0003על פי עדים\u0004 — הרי זה \u0003כ\u0004אילו \u0003שלא בכוונת איש באשה,\u0004 שבא על אשה שלא לכוונת נישואין, \u0003ו\u0004במקרה כזה \u0003לא בעיא\u0004 \u0005[ואינה צריכה]\u0006 \u0003גט.\u0004","\u0003רב אשי אמר\u0004 שמעיקר הדברים אין כאן קושי, ויש להסביר את דברי ר' שמעון בדרך אחרת, כי ר' שמעון \u0003לענין איסורא קתני\u0004 \u0005[איסור שנה]\u0006 ולא לענין גט, \u0003והכי קאמר\u0004 \u0005[וכך אמר]:\u0006 \u0003עשו בית דין בהוראתן\u0004 — כאילו היה זה \u0003כזדון איש באשה,\u0004 וכוונתו: \u0003ומיתסרא\u0004 \u0005[ונאסרת]\u0006 \u0003על בעלה,\u0004 כאילו נבעלה האשה בזדון. ואם נישאת \u0003על פי עדים\u0004 — עשו זאת \u0003כשגגת איש באשה, ולא מיתסרא\u0004 \u0005[ואינה נאסרת]\u0006 \u0003על בעלה.\u0004"],["\u0003רבינא אמר: לענין קרבן קתני\u0004 \u0005[שנה]\u0006 ברייתא זו, וכך יש לפרשה: \u0003עשו בית דין בהוראתן\u0004 — הרי זה \u0003כזדון איש באשה ולא מתיא\u0004 \u0005[ואינה מביאה]\u0006 \u0003קרבן,\u0004 שהרי על עבירת זדון אין מביאים קרבן. אם נישאת \u0003על פי עדים\u0004 — עשו זאת \u0003כשגגת איש באשה, ומתיא\u0004 \u0005[ומביאה]\u0006 \u0003קרבן.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 לדחות את קושיית רב ששת באופן אחר: \u0003הא קמייתא\u0004 \u0005[זו\u0006 הברייתא ה\u0005ראשונה]\u0006 הפוטרת מגט עריות שנישאו — כדעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא,\u0004 האוסרים אותה על בעלה גם בנישאת על פי עדים, \u0003ותריץ הכי\u0004 \u0005[ותרץ,\u0006 ישב אותה, \u0005כך]:\u0006 \u0003חוץ מאשת איש\u0004 שנישאת על פי עדים, \u0003ו\u0004בכלל זה גם זו \u0003שניסת על פי בית דין\u0004 שצריכות גט.","לגבי עצם הסברה שהעלה רב ששת \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003עולא: מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 נימוק זה של \u0003מאי הוה\u0004 \u0005[מה היה]\u0006 \u0003לה למיעבד\u0004 \u0005[לעשות],\u0006 שאם לאשה לא היתה כלל דרך להימנע מעבירה דנים אותה כאנוסה? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003כתב\u0004 גט וכתב בו תאריך \u0003לשם מלכות שאינה הוגנת,\u0004 שאיננה המלכות שבה הם נמצאים, או \u0003לשם מלכות מדי, לשם מלכות יון\u0004 שכבר בטלו מן העולם, או כתב תאריך \u0003לבנין הבית\u0004 או \u0003לחורבן הבית,\u0004 וכן אם \u0003היה\u0004 הגט ניתן \u0003במזרח וכתב\u0004 בו מקום \u0003במערב,\u0004 או שניתן \u0003במערב וכתב\u0004 בו מקום \u0003במזרח\u0004 — הרי גט זה פסול, ולכן אם נישאה לאחר —","\u0003תצא מזה ומזה,\u0004 גם מזה שנתגרשה ממנו, וגם מבעלה החדש, \u0003וכל הדרכים האלו\u0004 המוזכרות במשנה של קנסות שקנסו אשה נשואה שחזרה ונישאה שלא כדין — קיימים גם \u0003בה. ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003לימא\u0004 \u0005[נאמר]:\u0006 \u0003מאי הוה\u0004 \u0005[מה היה]\u0006 \u0003לה למיעבד\u0004 \u0005[לעשות],\u0006 הרי כאנוסה היא שחשבה שהגט כשר ולכן הלכה ונישאה! ומשיבים: זו אינה אנוסה, כי \u0003איבעי לה לאקרויי לגיטא\u0004 \u0005[היתה צריכה להקריא את הגט]\u0006 לחכם, והוא היה אומר לה שגט זה פסול הוא.","\u0003אמר רב שימי בר אשי: תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 ראיה אחרת, ממה ששנינו: \u0003הכונס את יבמתו והלכה צרתה\u0004 של היבמה \u0003ונשאת\u0004 לאדם אחר, \u0003ונמצאת זו\u0004 היבמה לבסוף \u0003אילונית\u0004 ולא היתה זקוקה לייבום, ואם כן בעילתה לא פטרה את צרתה מן הייבום ואותה צרה שנישאה לאחר, בעבירה נישאה — \u0003תצא\u0004 הצרה \u0003מזה ומזה\u0004 מבעלה ומהיבם, שלא תתייבם, \u0003וכל הדרכים האלו בה. ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003נימא\u0004 \u0005[נאמר]:\u0006 \u0003מאי הוה\u0004 \u0005[מה היה]\u0006 \u0003לה למיעבד\u0004 \u0005[לעשות]?\u0006 ומשיבים: מכאן אין להוכיח, כי \u0003איבעי\u0004 \u0005[היה]\u0006 \u0003לה לאמתוני\u0004 \u0005[להמתין]\u0006 עד שיתברר אם האשה האחרת היא איילונית.","\u0003אמר אביי: תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 מה ששנינו: \u0003כל\u0004 ה\u0003עריות שאמרו\u0004 שהן \u0003פוטרות צרותיהן,\u0004 אם \u0003הלכו\u0004 ה\u0003צרות ונישאו ונמצאו אלו\u0004 (העריות) \u0003אילונית,\u0004 שנישאו בטעות ולא היו בכלל חובת הייבום, ונמצא שהיו הצרות צריכות להתייבם — \u0003תצא מזה ומזה, וכל הדרכים האלו בה. ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003נימא\u0004 \u0005[נאמר]:\u0006 \u0003מאי הוה\u0004 \u0005[מה היה]\u0006 \u0003לה למיעבד\u0004 \u0005[לעשות]?\u0006 ומשיבים, כפי שאמרנו כבר: \u0003איבעי\u0004 \u0005[היה]\u0006 \u0003לה לאמתוני\u0004 \u0005[להמתין].\u0006","\u0003אמר רבא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003כתב סופר גט לאיש ושובר לאשה\u0004 שהאיש יתן את הגט לאשה והאשה תתן לו שובר לכשתקבל את כתובתה, לאשר שקיבלה את כל הסכום, \u0003וטעה\u0004 הסופר \u0003ונתן\u0004 את ה\u0003גט לאשה ו\u0004את ה\u0003שובר\u0004 נתן \u0003לאיש.\u0004 והאיש חשב שגט בידו, והאשה חשבה ששובר בידה, \u0003ונתנו זה לזה וזה לזה\u0004","\u0003ולאחר זמן\u0004 התברר ש\u0003הרי הגט יוצא מתחת ידי האיש, ושובר\u0004 יוצא \u0003מתחת ידי האשה\u0004 ולא היה כאן מעשה גירושין כלל, אם בינתיים נישאה האשה לאחר — \u0003תצא מזה ומזה, וכל הדרכים האלו בה. ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003נימא\u0004 \u0005[נאמר]:\u0006 \u0003מאי הוה\u0004 \u0005[מה היה]\u0006 \u0003לה למיעבד\u0004 \u0005[לעשות]!\u0006 ומשיבים: גם שם, \u0003איבעי לה לאקרויי לגיטא\u0004 \u0005[היתה צריכה להקריא את הגט]\u0006 לבקי.","\u0003אמר רב אשי: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003שינה\u0004 אדם בגט את \u0003שמו\u0004 או את \u0003שמה\u0004 של אשתו, או \u0003שם עירו\u0004 או את \u0003שם עירה — תצא מזה ומזה, וכל הדרכים האלו בה. ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003נימא\u0004 \u0005[נאמר]:\u0006 \u0003מאי הוה\u0004 \u0005[מה היה]\u0006 \u0003לה למיעבד\u0004 \u0005[לעשות]!\u0006 ומשיבים: \u0003איבעי לה לאקרויי לגיטא\u0004 \u0005[היתה צריכה להקריא את הגט]\u0006 לחכם.","\u0003אמר רבינא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003כנסה בגט קרח,\u0004 שכן כאשר עושים סוג גט מיוחד (מקושר) צריך שיהיו בו עדים כמנין השורות שבו, וגט זה לא היו בו מספיק עדים (\"קרח\"), והוא פסול, ואם נישאה — \u0003תצא מזה ומזה\u0004 וכל הדרכים האלו בה. ומה היה לה לעשות? ומשיבים: \u0003איבעי לה לאקרויי לגיטא\u0004 \u0005[היתה צריכה להקריא את הגט]\u0006 לחכם, והוא היה אומר לה שגט זה פסול.","מסופר: \u0003רב פפא סבר למיעבד עובדא\u0004 \u0005[חשב לעשות מעשה]\u0006 ולהתיר לאשה לחזור לבעלה על סמך הנימוק של \u0003במאי הוה\u0004 \u0005[במה היה]\u0006 \u0003לה למיעבד\u0004 \u0005[לעשות],\u0006 שכיון שלא היתה לה דרך לברר את הדברים יש לראותה כאנוסה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע לרב פפא: והתניא כל הני מתנייתא\u0004 \u0005[והרי שנויות כל המשניות הללו]\u0006 שמהן הוכחנו פעם אחרי פעם שהנימוק של מה היה לה לעשות אינו תופס!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב פפא: \u0003ולאו שנינהו\u0004 \u0005[ו\u0006כי \u0005לא תירצנו אותן],\u0006 שבכל המקרים הללו היתה לה דרך לברר את הדינים! \u0003אמר ליה: ואשינויי ליקו וליסמוך\u0004 \u0005[ועל תירוצים נעמוד ונסמוך]!\u0006 שאמנם תירצנו ודחינו את הקושיות בדרך כלשהי, אבל סיכומם של הקשיים מצטבר כדי הוכחה שאין סומכים על הנימוק \"מה היה לה לעשות\". \u0003ופסק,\u0004 כלומר, לא עשה רב פפא מעשה.","\u0003אמר רב אשי: ולקלא לא חיישינן\u0004 \u0005[ולקול אין אנו חוששים]\u0006 שאם יצא קול בלי עדות מוכחת שבעלה חי אין אנחנו חוששים לכך. ושואלים: \u0003הי קלא\u0004 \u0005[איזה קול],\u0006 כלומר, איך היה בדיוק הדבר, \u0003אילימא קלא דבתר\u0004 \u0005[אם תאמר קול ש\u0006יצא \u0005לאחר]\u0006 \u0003נשואין\u0004 של אשה זו לאחר\u0005]\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 כבר \u0003אמרה רב אשי חדא זימנא\u0004 \u0005[פעם אחת],\u0006 ש\u0003אמר רב אשי:\u0004"],["\u0003כל קלא דבתר\u0004 \u0005[קול שלאחר]\u0006 \u0003נשואין לא חיישינן\u0004 \u0005[אין אנו חוששים],\u0006 שאם יצא קול על אשה לאחר נישואיה, שהיה צד פסול או איסור בה — אין חוששים לו! ומשיבים: יש בכך חידוש, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הואיל ואתאי לבי דינא ושרינן\u0004 \u0005[ובאה לבית דין והתרנו\u0006 אותה\u0005]\u0006 שהיה צורך לדון בה כדי להתירה, אם כן אין היתרה ברור כל כך, ונאמר כי \u0003כקלא דקמי\u0004 \u0005[כקול שלפני]\u0006 \u0003נשואין דמי ותיתסר\u0004 \u0005[ייחשב, ותיאסר],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שגם במקרה זה, כיון שנישאה — נישאה, ואין חוששים לקול.","שנינו במשנה, שאם \u0003ניסת על פי בית דין תצא,\u0004 אבל אינה חייבת להביא קרבן חטאת. על זה \u0003אמר זעירי: ליתא דמתניתין מדתני בי מדרשא\u0004 \u0005[אין למשנתנו,\u0006 דחויה היא משנתנו, \u0005מ\u0006מה \u0005ששנו\u0006 ב\u0005בית המדרש],\u0006 שההלכה היא כפי הברייתא ששנו בבית המדרש. \u0003דתני בי מדרשא\u0004 \u0005[ששנו\u0006 ב\u0005בית המדרש]:\u0006 \u0003הורו בית דין ששקעה חמה\u0004 ביציאת השבת, ומותר לעשות מלאכה, \u0003ולבסוף זרחה — אין זו\u0004 נחשבת כ\u0003הוראה\u0004 שהאשמה בה תלויה בבית דין, \u0003אלא\u0004 כ\u0003טעות\u0004 ואין בית הדין צריך להביא קרבן על שגגת הציבור, אלא כל יחיד ויחיד נחשב כשוגג. ואף כאן, למרות שנישאה האשה בהוראת בית דין אין זו הוראה בלתי נכונה אלא טעות בעובדות, ובכגון זה נחשב לשגגה שיחיד מביא עליה קרבן.","\u0003ורב נחמן אמר:\u0004 מה שהתירה בית הדין, \u0003הוראה היא.\u0004","\u0003אמר רב נחמן: תדע\u0004 ש\u0003הוראה היא\u0004 בענין הנישואין, שהרי \u0003בכל\u0004 דיני \u0003התורה כולה עד אחד לא מהימן\u0004 \u0005[נאמן]\u0006 \u0003והכא מהימן\u0004 \u0005[וכאן נאמן],\u0006 \u0003מאי טעמא\u0004 \u0005[מה\u0006 ה\u0005טעם]?\u0006 — \u0003לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003משום\u0004 ש\u0003הוראה היא,\u0004 ולא על העד סמכו, אלא בית הדין הם שהורו והתירו. ומצד שני \u0003אמר רבא: תדע\u0004 ש\u0003טעות הוא,\u0004 ש\u0003אילו הורו בית דין בחלב ובדם להיתירא\u0004 \u0005[להיתר],\u0006 \u0003והדר חזו טעמא לאיסורא\u0004 \u0005[וחזרו וראו טעם לאיסור]\u0006 ואסרו, \u0003כי הדרי ואמרי להיתירא לא משגחינן להו\u0004 \u0005[כאשר\u0006 הם \u0005חוזרים ואומרים להיתר אין אנחנו משגיחים בהם],\u0006 שאם לא מצאו הוכחה מכרעת אלא רק נימוק חדש — אין סומכים על נימוק כזה לבטל הוראה לאיסור,","\u0003ואילו\u0004 בענין נישואין, \u0003היכא דאתא\u0004 \u0005[היכן,\u0006 כאשר \u0005בא]\u0006 \u0003עד אחד — שרינא\u0004 \u0005[מתירים אנו],\u0006 \u0003אתו תרי\u0004 \u0005[באו שנים]\u0006 ומעידים שהוא חי — \u0003אסרנא\u0004 \u0005[אוסרים אנו]\u0006 אותה, \u0003כי הדר אתא\u0004 \u0005[כאשר חוזר\u0006 ו\u0005בא]\u0006 \u0003עד אחרינא\u0004 \u0005[אחר]\u0006 ומעיד שמת האיש — \u0003שרינן\u0004 \u0005[מתירים אנו]\u0006 אותה. \u0003מאי טעמא\u0004 \u0005[מה\u0006 ה\u0005טעם],\u0006 \u0003לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003משום שטעות הוא,\u0004 שאין בית דין מתירים ואוסרים כאן על פי סברתם, אלא על פי הידיעות שבידיהם שנמסרות על ידי העדים, ולכן יש לראות זאת כטעות בעובדות של בית הדין, ולא כהוראה בלתי נכונה.","\u0003ואף ר' אליעזר סבר\u0004 ש\u0003טעות הוא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר אומר:\u0004 אשה שנישאת על פי בית דין והתברר שבעלה חי עדיין — \u0003יקוב הדין את ההר,\u0004 כלומר, נמצה את הדבר עד סופו, וכיון שהיתה זו טעות, בטלה ההוראה \u0003ותביא חטאת שמינה. אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 ש\u0003טעות הוא — משום הכי\u0004 \u0005[כך]\u0006 \u0003מתיא\u0004 \u0005[מביאה]\u0006 \u0003קרבן, אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003הוראה היא, אמאי מתיא\u0004 \u0005[מדוע מביאה]\u0006 \u0003קרבן?\u0004 הלא בית דין הוא שצריך להביא קרבן על שגגתו!","ומקשים: \u0003ודלמא קסבר\u0004 \u0005[ושמא סבור]\u0006 \u0003ר' אליעזר\u0004 כי \u0003יחיד שעשה\u0004 מעשה שלא כדין \u0003בהוראת בית דין\u0004 גם הוא \u0003חייב\u0004 להביא קרבן, ולכן ר' אליעזר מחייב את האשה בקרבן, אף שעשתה בהוראת בית הדין?! ודוחים: \u0003אם כן,\u0004 שכך סבור ר' אליעזר בכלל, \u0003מה \"יקוב הדין את ההר\"\u0004 יש כאן במיוחד, די היה לו לומר שצריכה להביא קרבן. אלא ודאי בכלל סבור הוא שאין יחיד מביא קרבן כאשר עבר בשגגה על הוראת בית דין, אבל כאן, כיון שטעות היתה — יביא קרבן.","שנינו במשנה שאם \u0003הורוה בית דין להנשא\u0004 והלכה וקלקלה — חייבת בקרבן. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"קלקלה\"? ר' אליעזר אומר: זינתה,\u0004 כלומר, נבעלה לאדם שלא לשם נישואין. \u0003ר' יוחנן אמר:\u0004 שנישאה בנישואין אסורים, כגון: \u0003אלמנה\u0004 שנישאה \u0003לכהן גדול, גרושה וחלוצה לכהן הדיוט.\u0004","ומסבירים: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003זינתה — כל שכן\u0004 ש\u0003אלמנה לכהן גדול\u0004 חייבת להביא קרבן, שכן עשתה מעשה האסור מן התורה. אבל \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שמשנתנו עוסקת ב\u0003אלמנה לכהן גדול,\u0004 דווקא במקרה זה חייבת בקרבן, \u0003אבל\u0004 אם \u0003זינתה — לא. מאי טעמא\u0004 \u0005[מה\u0006 ה\u0005טעם] —\u0006 כי \u0003אמרה: אתון\u0004 \u0005[אתם]\u0006 \u0003הוא דשויתין\u0004 \u0005[שעשיתם אותי]\u0006 \u0003פנויה,\u0004 ואף שאין הדבר נאה, מותר לי כפנויה לחיות עם כל מי שארצה.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן: הורוה בית דין להנשא והלכה וקלקלה, כגון: אלמנה לכהן גדול, גרושה וחלוצה לכהן הדיוט — חייבת בקרבן על כל ביאה וביאה,\u0004 שכל ביאה היתה מעשה עבירה נפרד, אלו \u0003דברי ר' אלעזר,\u0004","\u0003וחכמים אומרים:\u0004 מביאה \u0003קרבן אחד על הכל,\u0004 שהרי השגגה והעלם הדבר שהיה כאן אחד הוא. \u0003ומודים חכמים לר' אלעזר שאם נשאת\u0004 אשת איש בטעות למשל \u0003לחמשה בני אדם — שחייבת בקרבן על כל אחד ואחד, הואיל וגופין מוחלקין\u0004 ועל כל איש ואיש (\"גוף\") חייבת בקרבן מיוחד.","\u0003האשה שהלך בעלה ובנה למדינת הים, ובאו ואמרו לה: מת בעליך ואחר כך מת בנך,\u0004 וכיון שבזמן מות בעלה היה לה בן, הרי שלא נזקקה לייבום, והלכה \u0003ונשאת\u0004 לאדם אחר, \u0003ואחר כך אמרו לה: חילוף היו הדברים,\u0004 כלומר, שמת הבן תחילה ואחר כך הבעל, והיתה זקוקה לייבום, ונמצאת עתה שהיא יבמה שנישאה לחוץ, ללא חליצה — \u0003תצא\u0004 מבעלה, \u0003והולד ראשון\u0004 שנולד לפני השמועה, \u0003ואחרון\u0004 שנולד לאחר השמועה — \u0003ממזר.\u0004","ולהיפך, אם \u0003אמרו לה: מת בנך ואחר כך מת בעליך ו\u0004משום כך \u0003נתייבמה, ואחר כך אמרו לה: חילוף היו הדברים,\u0004 ונמצא שנישאה לאחי בעלה שלא במקום ייבום — \u0003תצא\u0004 מבעלה, \u0003והולד ראשון ואחרון ממזר. אמרו לה: מת בעליך וניסת\u0004 (נישאה), \u0003ואחר כך אמרו לה: קיים\u0004 (חי) \u0003היה\u0004 באותה שעה שנישאה \u0003ומת\u0004 אחר כך — \u0003תצא\u0004 מבעלה השני, \u0003והולד ראשון\u0004 שנולד בשעה שהיה בעלה חי — \u0003ממזר, ואחרון\u0004 שנולד לאחר מיתת הבעל הראשון — \u0003אינו ממזר.\u0004","\u0003אמרו לה: מת בעליך, ונתקדשה. ואחר כך בא בעלה — מותרת לחזור לו\u0004 שאינה נאסרת על בעלה משום קידושין בלבד. \u0003אף על פי שנתן לה אחרון גט — לא פסלה\u0004 על ידי כך אפילו \u0003מן הכהונה,\u0004 שהרי התברר שלא היתה כלל אשתו ולא תפסו בה קידושיו, ואין גט פוסל באשתו של אדם זר. \u0003את זו דרש ר' אלעזר בן מתיא: \"ואשה גרושה מאישה\u0004 לא יקחו\u0003\"\u0004 (ויקרא כא, ז), \u0003ולא\u0004 זו שנתגרשה \u0003מאיש שאינו אישה,\u0004 והרי השני איננו אישה.","לגבי הקטע הראשון במשנה שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ראשון\", ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"אחרון\"\u0004 שנאמרו כאן? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כי \u0003ראשון\u0004 הוא זה שנולד \u0003לפני\u0004 ה\u0003שמועה\u0004 שלא כך היו הדברים, \u0003ואחרון לאחר שמועה — ליתני\u0004 \u0005[שישנה]\u0006 סתם: \u0003הולד ממזר,\u0004 שהרי אין הבדל בין הדינים!","ומסבירים: \u0003משום דקבעי למיתני סיפא\u0004 \u0005[שרצה לשנות\u0006 ב\u0005סוף]\u0006 \u0003אמרו לה מת בעלך ונשאת, ואחר כך אמרו לה קיים היה ומת, הראשון ממזר והאחרון אינו ממזר — תנא נמי רישא\u0004 \u0005[שנה גם כן\u0006 ב\u0005תחילה]\u0006 \u0003ראשון ואחרון ממזר,\u0004 אף שבמקרים אלה אין הבדל אם היה זה לפני השמועה או אחריה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 משנתנו \u0003זו דברי ר' עקיבא\u0004 היא, \u0003שהיה אומר: אין קדושין תופסין בחייבי לאוין,\u0004 ולפיכך הוולד מיבמה שנישאה לחוץ ועברה על לאו — ממזר. \u0003אבל חכמים אומרים: אין ממזר מיבמה.\u0004 ושואלים: \u0003ולימא\u0004 \u0005[ושיאמר]\u0006 בדברי חכמים בצורה כוללת: \u0003אין ממזר מחייבי לאוין!\u0004","ומשיבים: \u0003האי תנא הך תנא\u0004 \u0005[תנא זה\u0006 המובא בשם חכמים, \u0005הוא התנא\u0006 האחר\u0005]\u0006 שאמר בשם \u0003ר' עקיבא,\u0004 ש\u0003אמר\u0004 כך: וולד הנולד \u0003מחייבי לאוין\u0004 של \u0003שאר,\u0004 כלומר, מתוך קירבת משפחה — \u0003הוי\u0004 \u0005[הריהו\u0006 ממזר\u0005]\u0006 \u0003ממזר,\u0004 והנולד \u0003מחייבי לאוין גרידי\u0004 \u0005[סתם],\u0006 כלומר, מחיוב לאו שאיננו תלוי בקירבת משפחה, כגון האיסור ביבמה של \"לא תהיה אשת המת החוצה לאיש זר\" — \u0003לא הוי\u0004 \u0005[אינו]\u0006 \u0003ממזר. אמר רב יהודה\u0004"],["\u0003אמר רב: מנין שאין קדושין\u0004 של איש זר \u0003תופסין ביבמה — שנאמר: \"לא תהיה אשת המת החוצה לאיש זר\"\u0004 (דברים כה, ה), וכוונתו: \u0003לא תהא בה הויה לזר,\u0004 כלומר, אין איש זר יכול לשאת אותה, שאין תפיסה של קידושין (\"הויה\") בה.","\u0003ושמואל אמר: בעניותינו\u0004 (בעניות דעתנו), מכיון שאין אנו יודעים בבירור מה משמעות הכתוב, לכך \u0003צריכה גט.\u0004 ומסבירים: \u0003מספקא ליה\u0004 \u0005[מסופק לו]\u0006 \u0003לשמואל האי\u0004 \u0005[\u0006הכתוב ה\u0005זה]\u0006 \u0003\"לא תהיה אשת המת\u0004 החוצה \u0003\", אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004איסור \u0003לאו הוא דאתא\u0004 \u0005[שבא],\u0006 לומר שאסור שתהיה לזר, אבל קידושיו תופסים בה, כשאר חייבי לאווין, \u0003אי\u0004 \u0005[או]\u0006 לומר ש\u0003לא תפסי\u0004 \u0005[תופסים]\u0006 \u0003בה קדושין הוא דאתא\u0004 \u0005[שבא],\u0006 שאין בה הויה לזר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב מרי בר רחל לרב אשי, הכי\u0004 \u0005[כך]\u0006 \u0003אמר אמימר: הלכה כוותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003שמואל. אמר רב אשי: השתא\u0004 \u0005[עכשיו]\u0006 ש\u0003אמר אמימר\u0004 כי \u0003הלכתא כוותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003שמואל\u0004 שהמקדש יבמה לפני חליצה צריך לתת לה גט, \u0003אם היה יבמה\u0004 של זו שנישאה לשוק על פי עדות עד אחד או שנים שאמרו שמת בעלה ואחר כך מת בנה, \u0003כהן — חולץ לה\u0004 היבם, שהרי בין כה וכה היא אסורה לו לאחר שיתן לה המקדש גט \u0003ושריא ליה\u0004 \u0005[ומותרת לו],\u0006 לאיש שנתקדשה לו.","ותוהים: אם כן, נמצא כי \u0003איתגורי איתגר\u0004 \u0005[\u0006היא \u0005מרויחה]\u0006 בזה שנתקדשה באיסור, \u0003אם כן מצינו חוטא נשכר! אלא\u0004 צריך לתקן ולומר, \u0003אם היה יבמה ישראל נותן לה שני\u0004 זה שקידשה לאשה \u0003גט, והותרה לו\u0004 ליבם, שהרי גם אם היא גרושה מותרת לישראל.","\u0003אמר רב גידל אמר רב חייא בר יוסף אמר רב: יבמה, קדושין — אין בה, נשואין — יש בה.\u0004 ותוהים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003קדושין אין בה — נשואין נמי\u0004 \u0005[גם כן]\u0006 \u0003אין בה,\u0004 שהרי כיצד יתפסו בה נישואין אם לא תפסו קידושין שהם קלים מהם! \u0003אימא\u0004 \u0005[אמור]\u0006 ותקן כך: \u0003קדושין ונשואין אין בה.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"נשואין יש בה\" — בזנות.\u0004 כלומר, אם נישאה ממש, אף שהקידושין לא תפסו בה לדעת רב, מכל מקום כיון שבא עליה זר נשתנה דינה ונאסרה על היבם. \u0003כ\u0004דברי \u0003רב\u0004 \u0005[רב]\u0006 \u0003המנונא,\u0004 ש\u0003אמר רב המנונא: שומרת יבם שזינתה — אסורה ליבמה.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם כדאמרן מעיקרא\u0004 \u0005[כפי שאמרנו מתחילה]\u0006 \u0003קדושין אין בה, נשואין יש בה.\u0004 והכוונה לא שהנישואין תופסים בה ממש, אלא שצריך לתת לה גט, משום \u0003דמיחלפא\u0004 \u0005[ש\u0006היא \u0005מוחלפת]\u0006 \u0003באשה שהלך בעלה למדינת הים,\u0004 ולכן תיקנו שיצטרך לתת לה גט, כדי שלא יבואו להתיר גם באשה ששמעה שמת בעלה במדינת הים והלכה ונישאה לאחר, שתיקנו שתצטרך גט כשבא בעלה.","\u0003אמר ר' ינאי: בחבורה\u0004 של החכמים שעסקו בנושא זה, \u0003נמנו וגמרו: אין קדושין תופסין ביבמה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן: רבי, לא משנתנו היא זו\u0004 שאין קידושין תופסים בה? \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003האומר לאשה: \"הרי את מקודשת לי לאחר שאתגייר\"\u0004 או \u0003\"לאחר שתתגיירי\"\u0004 או \u0003\"לאחר שאשתחרר\u0004 מעבדותי\u0003\", \"לאחר שתשתחררי\u0004 את\u0003\"\u0004 ,\u0003\"לאחר שימות בעליך\", \"לאחר שתמות אחותיך\u0004 שאני נשוי לה\u0003\", או \"לאחר שיחלוץ ליך יבמיך\" — אינה מקודשת,\u0004 שהוא כקונה קניין בדבר שלא בא לעולם, כי בשעת הקידושין אין קידושין אלה יכולים לחול. ומכאן אנו למדים שקידושין אינם תופסים ביבמה כלל עד שתחלוץ. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' ינאי: \u0003אי לאו דדלאי לך חספא, מי משכחת מרגניתא תותיה\u0004 \u0005[אם לא שהעליתי לך חרס, האם היית מוצא\u0006 את \u0005המרגלית תחתיו]?\u0006 כלומר, כיון שאמרתי לך את ההלכה, הצלחת אתה למצוא ראיה יפה זו ממשנתנו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 לאחר זמן \u0003ריש לקיש\u0004 לר' יוחנן: \u0003אי לאו דקלסך גברא רבה\u0004 \u0005[אם לא ששיבח אותך אדם גדול]\u0006 כר' ינאי \u0003הוה אמינא לך אנא\u0004 \u0005[הייתי אומר לך אני]\u0006 ודוחה את ראייתך, כך: \u0003מתניתין\u0004 \u0005[משנתנו\u0006 זו\u0005]\u0006 כדעת \u0003ר' עקיבא היא,\u0004 ש\u0003אמר\u0004 ש\u0003אין קידושין תופסים בחייבי לאוין,\u0004 ולכן אין הקידושין תופסים ביבמה. אבל לדעת חכמים קידושין תופסים בה כשאר חייבי לאוין.","ושואלים: \u0003ואי\u0004 \u0005[ואם]\u0006 דעת \u0003ר' עקיבא\u0004 היא, יש להקשות הלא \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר לה \"לאחר שיחלוץ ליך יבמיך\" — ליתפסי\u0004 \u0005[שיתפסו]\u0006 \u0003בה קידושי? דהא שמעינן ליה\u0004 \u0005[שהרי שמענו אותו]\u0006 את \u0003ר' עקיבא\u0004 ש\u0003אמר: אדם מקנה דבר שלא בא לעולם.\u0004 כלומר, שיש דין קניין גם בדבר שעדיין אינו קיים במציאות. ואם כן, אף שכעת אין הקידושין תופסים בה, מכל מקום לאחר שיחלצו לה יתפסו בה! וראיה שזו דעת ר' עקיבא — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006"],["\u0003קונם\u0004 (אסור, כעין הקדש) כל מה \u0003שאני עושה לפיך,\u0004 ששכר מלאכה שאני עושה יהא אסור עליך — \u0003אין צריך להפר,\u0004 כי הקונם הזה אינו חל, לפי שהיא חייבת לעשות מלאכה מסויימת מכוח ההתחייבות הקודמת הנובעת מעצם הנישואין.","\u0003ר' עקיבא אומר: יפר, שמא תעדיף עליו יותר מן הראוי לו.\u0004 שאמנם אם תעשה מלאכה רק כשיעור הראוי — ודאי אין הקונם חל, אבל שמא תעשה יותר, ואז יחולו הנדר והאיסור על התוספת, וכדי שלא יבוא להיכשל בכך מוטב שיפר לה כעת. ומכאן שלדעת ר' עקיבא הקונם חל גם על דבר שלא נברא עדיין, שהרי הדברים שהיא עתידה לעשות עדיין אינם בעולם.","את הראיה הזו דוחים: \u0003הא איתמר עלה\u0004 \u0005[הרי\u0006 כבר \u0005נאמר עליה]\u0006 \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע:\u0004 כאן אין מדובר שהיא אוסרת עליו את מעשי ידיה שעדיין לא עשתה, אלא \u0003באומרת: \"יקדשו ידי לעושיהם\",\u0004 כלומר, הידיים תהיינה כמוקדשות ואוסרות את העבודה שהן עושות. שה\u0003ידים\u0004 על כל פנים \u0003איתנהו בעלמא\u0004 \u0005[נמצאות בעולם],\u0006 ואם כן אין זה הקניית דבר שלא בא לעולם ואין כל ראיה מכאן לגבי שיטת ר' עקיבא בנושא זה.","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 דעה זו שר' עקיבא אינו סבור שיש קנין בדבר שלא בא לעולם על \u0003רב נחמן בר יצחק.\u0004 ש\u0003אמר רב נחמן בר יצחק: רב הונא\u0004 סבור \u0003כרב, ורב כר' ינאי, ור' ינאי כר' חייא, ור' חייא כרבי, ורבי כר' מאיר, ור' מאיר כר' אליעזר בן יעקב, ור' אליעזר בן יעקב כר' עקיבא\u0004 ש\u0003אמר: אדם מקנה דבר שלא בא לעולם.\u0004 ואם כן, ברור לו שר' עקיבא אכן מחזיק בדעה שאדם יכול להקנות דבר שלא בא לעולם.","ומעתה מפרטים את ההקשרים של בעלי דעות אלה, שכולם באותה שיטה. \u0003רב הונא מאי\u0004 \u0005[מה\u0006 הוא\u0005]\u0006 המקור שהוא סבור כך? \u0003דאיתמר\u0004 \u0005[שנאמר]:\u0006 \u0003המוכר פירות דקל לחברו\u0004 לפני שצמחו הפירות, במקרה זה \u0003אמר רב הונא: עד שלא באו\u0004 הפירות \u0003לעולם — יכול לחזור בו\u0004 מן המכר, שעדיין לא חלה המכירה. אבל \u0003משבאו לעולם — אין יכול\u0004 עוד \u0003לחזור בו,\u0004 למרות שבשעת הקנין עדיין לא צמחו.","\u0003ורב נחמן אמר: אף משבאו לעולם יכול לחזור בו,\u0004 שכן הקנין מתחילתו לא חל, כי לדעתו אין אדם מקנה דבר שלא בא לעולם. \u0003אמר רב נחמן:\u0004 עם זאת \u0003מודינא\u0004 \u0005[מודה אני],\u0006 \u0003דאי שמיט ואכיל\u0004 \u0005[שאם\u0006 הקונה \u0005שמט,\u0006 תפס את הפירות, \u0005ואכל] —\u0006 \u0003לא מפקינן מיניה\u0004 \u0005[אין אנו מוציאים ממנו],\u0006 שהרי היתה כאן הבטחה למכור לו את הפירות, אף שלא היה כאן קנין גמור.","שיטת \u0003רב —\u0004 ש\u0003אמר רב הונא אמר רב, האומר לחברו: \"שדה זו שאני לוקח\u0004 (שאני עומד לקנות) \u0003לכשאקחנה, קנויה לך מעכשיו\" — קנה\u0004 החבר את השדה אף שבשעת הקנין עדיין לא היתה של המוכר.","\u0003ר' ינאי\u0004 סבור \u0003כר' חייא,\u0004 ומביאים מעשה שהיה, המבאר את הדברים: ש\u0003ר' ינאי הוה ליה אריסא\u0004 \u0005[היה לו אריס],\u0006 שהיה מעבד את קרקעותיו, \u0003דהוה מייתי ליה כנתא דפירי\u0004 \u0005[שהיה מביא לו סל פירות]\u0006 \u0003כל מעלי שבתא\u0004 \u0005[ערב שבת],\u0006 \u0003ההוא יומא נגה ליה\u0004 \u0005[יום אחד התאחר]\u0006 \u0003ולא אתא\u0004 \u0005[בא].\u0006 \u0003שקל עשר מפירי דביתיה עלייהו\u0004 \u0005[לקח\u0006 ו\u0005עישר מפירות ביתו עליהם],\u0006 על הפירות העתידים לבוא אליו, שמא יגיעו הפירות סמוך לשבת ולא יוכל לעשרם בשבת. בכל זאת פקפק ר' ינאי אם אפשר לעשר על דבר שעדיין לא הגיע לידו, \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' חייא\u0004 לשאול אם הפרשת המעשרות חלה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' חייא: \u0003שפיר עבדת\u0004 \u0005[יפה עשית].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב האמור בדין מעשר: \u0003\"\u0004ואכלת לפני ה' אלוהיך... \u0003למען תלמד ליראה את ה' אלהיך כל הימים\"\u0004 (דברים יד, כג), לשון הריבוי \"כל\" מוסיפה — \u0003אלו שבתות וימים טובים.\u0004 ומעתה, \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 נאמר הדבר? \u0003אילימא לעשורי ומיכל\u0004 \u0005[אם תאמר\u0006 לענין זה, \u0005לעשר ולאכול]\u0006 ביום השבת עצמו, הרי אין צורך בכך, וכי \u0003איצטריך קרא למישרי\u0004 \u0005[הוצרך הכתוב להתיר]\u0006 \u0003טלטול\u0004 האסור רק \u0003דרבנן\u0004 \u0005[מדברי סופרים]?!\u0006 שהרי האיסור לעשר בשבת אינו אלא מדברי סופרים, ובודאי אין צורך שהכתוב ילמד עליו."],["\u0003אלא לאו כי האי גוונא\u0004 \u0005[\u0006האם \u0005לא באופן זה],\u0006 שהוא מעשר מראש על מה שלא בא עדיין לעולם לכבוד השבת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' ינאי: \u0003והא אקריון בחלמא\u0004 \u0005[והרי הקריאו לי בחלום]\u0006 שתי מילים אלה \u0003\"קנה רצוץ\", מאי לאו הכי קאמרי\u0004 \u0005[האם לא כך אמרו]\u0006 \u0003לי,\u0004 שרמזו לכתוב \u0003\"הנה בטחת לך על משענת הקנה הרצוץ הזה\"\u0004 (מלכים ב' יח, כא), כלומר, שסמך על סברה שאיננה מבוססת?","אמר לו ר' חייא: \u0003לא, הכי קאמרי לך\u0004 \u0005[כך אמרו לך]\u0006 ורמזו לפסוק אחר, שנאמר במשיח: \u0003\"קנה רצוץ לא ישבור ופשתה כהה לא יכבנה\u0004 לאמת יוציא משפט","\u0003\"\u0004(ישעיהו מב, ג), לומר שכהוגן ובדרך אמת עשה. ומדברי שניהם מובן שהם סבורים כי יש קנין בדבר שלא בא לעולם. שיטת \u0003רבי — דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר: \u0003\"לא תסגיר עבד אל אדניו\"\u0004 (דברים כג, טז), \u0003רבי אומר: בלוקח\u0004 (קונה) \u0003עבד על מנת לשחררו הכתוב מדבר,\u0004 שאסור לו לשעבדו. ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 היה \u0005הדבר]?\u0006 \u0003אמר רב נחמן בר יצחק:\u0004 ש\u0003כתב ליה\u0004 \u0005[לו]\u0006 בשטר הקנין: \u0003לכשאקחך\u0004 כעבד — \u0003הרי עצמך קנוי לך מעכשיו.\u0004 נמצא שהוא מקנה דבר שעדיין לא בא לעולם, שהרי הוא מקנה את מעשה השחרור לפני שהעבד קנוי לו.","שיטת \u0003ר' מאיר — דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003האומר לאשה \"הרי את מקודשת לי לאחר שאתגייר\",\u0004 או \u0003\"לאחר שתתגיירי\", \"לאחר שאשתחרר\", \"לאחר שתשתחררי\", \"לאחר שימות בעליך\", \"לאחר שתמות אחותיך\", \"לאחר שיחלוץ לך יבמיך\" — אינה מקודשת. ר' מאיר אומר: מקודשת,\u0004 שקנין הקידושין חל אף על דבר שלא בא לעולם.","שיטת \u0003ר' אליעזר בן יעקב — דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003יתר על כן אמר ר' אליעזר בן יעקב: אפילו אם אמר \"פירות ערוגה זו\u0004 ה\u0003תלושים יהו תרומה על פירות ערוגה\u0004 זו ה\u0003מחוברים\u0004 לכשיתלשו \u0003\", או\u0004 שאמר \u0003\"פירות ערוגה\u0004 זו ה\u0003מחוברים\u0004 יהיו תרומה \u0003על פירות\u0004 ערוגה \u0003זו\u0004 ה\u0003תלושין, לכשיביאו שליש\u0004 גידולם \u0003ויתלשו\",\u0004 למרות שההפרשה נעשתה כאשר הפירות המחוברים עדיין לא הגיעו לכלל בישול, ולא היו ראויים לתרומה, ולפני שנתלשו עדיין לא חלה עליהם חובת תרומה, \u0003והביאו שליש ונתלשו — דבריו קיימין,\u0004 והתרומה חלה. משמע שאדם מקנה־מחיל קדושת תרומה על דבר שלא בא לעולם.","שיטת \u0003ר' עקיבא — דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 אשה האומרת לבעלה: \u0003\"קונם\u0004 כל מה \u0003שאני עושה לפיך\"\u0004 — הבעל \u0003אינו צריך להפר, ר' עקיבא אומר: יפר, שמא תעדיף עליו יתר מן הראוי לו,\u0004 שלדעתו חל הנדר גם על דברים שעדיין לא באו לעולם.","\u0003בעו מיניה\u0004 \u0005[שאלו אותו]\u0006 את \u0003רב ששת: עד אחד\u0004 המעיד לאשה שמת בעלה, \u0003ביבמה\u0004 שעומדת להתייבם \u0003מהו?\u0004 האם אפשר לסמוך עליו? וצדדי השאלה: \u0003טעמא\u0004 \u0005[הטעם]\u0006 שמכשירים \u0003עד אחד\u0004 בעדות שמת בעלה של אשה — \u0003משום דמילתא דעבידא לאיגלויי\u0004 \u0005[ש\u0006ב\u0005דבר שעשוי להיגלות]\u0006 אדם \u0003לא משקר, והכא נמי\u0004 \u0005[וכאן גם כן]\u0006 \u0003לא משקר, או דלמא טעמא\u0004 \u0005[שמא הטעם]\u0006 של הכשר \u0003עד אחד משום דאיהי דייקא ומינסבא\u0004 \u0005[שהיא,\u0006 האשה, \u0005מדייקת ונישאת]\u0006 ובודקת היטב את הדבר לפני כן. \u0003והכא\u0004 \u0005[וכאן],\u0006 \u0003כיון דזימנין דרחמא ליה\u0004 \u0005[שפעמים\u0006 היא \u0005אוהבת אותו],\u0006 את היבם, שכבר הכירה אותו קודם לכן — \u0003לא דייקא ומינסבא\u0004 \u0005[איננה מדייקת\u0006 כל צורכה \u0005ונישאת]\u0006 בלא דקדוק מספיק.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב ששת: תניתוה\u0004 \u0005[\u0006כבר \u0005שניתם אותה],\u0006 שיש תשובה לשאלה זו ממה ששנינו במשנתנו, \u0003אמרו לה: מת בנך ואחר כך מת בעליך ונתייבמה, ואחר כך אמרו לה חילוף הדברים — תצא, והולד ראשון ואחרון ממזר.\u0004 ונברר \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 היה \u0005הדבר]:\u0006 \u0003אילימא תרי ותרי\u0004 \u0005[אם תאמר שניים ושניים],\u0006 שבאו תחילה שני עדים והעידו דבר אחד, ואחר כך שניים אחרים שהעידו שהיה המעשה להיפך — \u0003מאי חזית דסמכת אהני\u0004 \u0005[מה ראית שסמכת על אלה,\u0006 האחרונים\u0005],\u0006 \u0003סמוך אהני\u0004 \u0005[על אלה,\u0006 הראשונים\u0005],\u0006 שאין עדות הראשונים נופלת בנאמנותה מעדות האחרונים ומדוע תצא מהיבם!","\u0003ועוד,\u0004 מדוע יהיה הוולד \u0003ממזר?\u0004 לכל היותר \u0003ספק ממזר הוא,\u0004 שיש כאן שתי עדויות המכחישות זו את זו, ולא ברור עם מי האמת. \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ש\u0003לא דק\u0004 \u0005[דייק]\u0006 התנא במשנה, ולא חילק בין ממזר לספק ממזר, \u0003והא מדקתני סיפא\u0004 \u0005[והרי מ\u0006מה \u0005ששנוי\u0006 ב\u0005סופה]\u0006 של משנתנו: \u0003הראשון ממזר והאחרון אינו ממזר, שמע מינה דוקא קתני\u0004 \u0005[למד מכאן\u0006 שב\u0005דיוק שנה]\u0006 במשנה, וממזר שאמרו הוא ממזר ודאי.","\u0003אלא לאו שמע מינה\u0004 \u0005[\u0006האם \u0005לא תשמע מכאן]\u0006 שבראשונה העיד רק \u0003חד\u0004 \u0005[\u0006עד \u0005אחד],\u0006 \u0003וטעמא דאתו בי תרי אכחשוה\u0004 \u0005[והטעם,\u0006 דווקא, משום \u0005שבאו שניים\u0006 ו\u0005הכחישוהו]\u0006 שעדותם ודאי מבטלת עדות עד אחד, \u0003הא לאו הכי\u0004 \u0005[הרי\u0006 אם \u0005לא כך] —\u0006 \u0003מהימן\u0004 \u0005[נאמן],\u0006 ומשמע שעד אחד נאמן גם להתיר אשה להתייבם. עד כאן סוגיה זו בנוסח אחד, אולם הסוגיה נשנתה גם בנוסח אחר.","\u0003ואיכא דאמר\u0004 \u0005[ויש\u0006 מי \u0005שאומר]:\u0006 \u0003הא לא תיבעי לך\u0004 \u0005[זו לא תישאל,\u0006 תסתפק, \u0005לך]\u0006 ש\u0003אפילו איהי נמי מהימנא\u0004 \u0005[היא\u0006 עצמה \u0005גם כן נאמנת]\u0006 לומר שמת בעלה, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003האשה שאמרה \"מת בעלי\" — תנשא,\u0004 ואם אמרה \u0003\"מת בעלי\"\u0004 ואין לה בנים ממנו — \u0003תתייבם,\u0004 וקל וחומר שעד אחד יהיה נאמן להעיד שמת בעלה. \u0003כי תיבעי לך\u0004 \u0005[כאשר תישאל לך]\u0006 השאלה לגבי נאמנות עד אחד, הרי זה לענין \u0003למישרי\u0004 \u0005[להתיר]\u0006 את ה\u0003יבמה לעלמא\u0004 \u0005[לכל],\u0006 וכגון שאומר לה שמת היבם, וצדדי השאלה:","\u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של נאמנות \u0003עד אחד — משום דמילתא דעבידא לאיגלויי\u0004 \u0005[ש\u0006ב\u0005דבר שעשוי להיגלות]\u0006 אדם \u0003לא משקר, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 אדם \u0003לא משקר, או דלמא טעמא\u0004 \u0005[שמא הטעם]\u0006 בנאמנות \u0003עד אחד, משום דאיהי דייקא ומינסבא\u0004 \u0005[שהיא מדייקת ונישאת]\u0006 \u0003והא לא דייקא ומינסבא\u0004 \u0005[וזו איננה מדייקת ונישאת]\u0006 ומדוע — \u0003דמיסנא הוא\u0004"],["\u0003דסניא ליה\u0004 \u0005[ששונאת\u0006 היא \u0005אותו]\u0006 את היבם, ולכן סומכת על עדות כל שהיא כדי להיפטר ממנו. \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב ששת: תניתוה\u0004 \u0005[שניתם אותה]\u0006 במשנתנו. ששנינו, \u0003אמרו לה: \"מת בעליך ואחר כך מת בנך\" ונשאת\u0004 לחוץ לאדם זר, \u0003ואחר כך אמרו לה \"חילוף היו הדברים\" — תצא, והולד ראשון ואחרון ממזר.\u0004","ונברר, \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 היה \u0005הדבר]:\u0006 \u0003אילימא תרי ותרי\u0004 \u0005[אם תאמר שניים ושניים],\u0006 שבאו קודם שני עדים ואחר כך שני עדים אחרים שסיפרו את המעשה בדרך אחרת — \u0003מאי חזית דסמכת אהני,\u0004 \u0005[מה ראית שסמכת על אלה]\u0006 האחרונים, \u0003סמוך אהני\u0004 \u0005[על אלה\u0006 הראשונים\u0005]\u0006 ולמה תצא? \u0003ועוד,\u0004 מדוע הוולד \u0003ממזר?\u0004 לכל היותר \u0003ספק ממזר הוא\u0004 שהרי אין הוכחה גמורה לדברי האחרונים. \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ש\u0003לא דק\u0004 \u0005[דייק]\u0006 התנא בלשונו — \u0003הא מדקתני סיפא\u0004 \u0005[הרי מ\u0006מה \u0005ששנה\u0006 ב\u0005סופה]:\u0006 \u0003הראשון ממזר והאחרון אינו ממזר, שמע מינה דדוקא קתני\u0004 \u0005[למד מכאן ש\u0006ב\u0005דיוק שנה]!\u0006","\u0003אלא לאו חד\u0004 \u0005[\u0006האם \u0005לא\u0006 מדובר בעד \u0005אחד],\u0006 \u0003וטעמא דאתו בי תרי אכחשוה\u0004 \u0005[והטעם,\u0006 דווקא, \u0005שבאו שניים\u0006 ו\u0005הכחישו אותו],\u0006 \u0003הא לאו הכי\u0004 \u0005[הרי\u0006 אם \u0005לא כן] —\u0006 \u0003מהימן\u0004 \u0005[\u0006היה \u0005נאמן].\u0006 את הראיה הזו מן המשנה דוחים: \u0003לעולם\u0004 תאמר שבאו \u0003תרי\u0004 \u0005[שני\u0006 עדים\u0005]\u0006 מתחילה \u0003ותרי\u0004 \u0005[ושניים]\u0006 אחר כך, \u0003וכ\u0004פי ש\u0003אמר רב אחא בר מניומי\u0004 בענין אחר, שמדובר \u0003בעדי הזמה,\u0004 שהעדים האחרונים לא סיפרו את המעשה באופן אחר, אלא הזימו את העדים הראשונים, שאמרו: \"עמנו הייתם באותו זמן במקום אחר\" ולא יכולתם כלל לראות את הדבר שאתם מעידים עליו, ועל ידי כך נפסלים העדים הראשונים בגופם לגמרי, ובכגון זה אנו סומכים על העדים האחרונים.","\u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003בעדי הזמה,\u0004 ואם כן לא נפתרה שאלה זו מן המשנה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב מרדכי לרב אשי, ואמרי ליה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב אחא לרב אשי: תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 ראיה ממקור אחר: \u0003אין האשה נאמנת לומר מת יבמי, שאנשא,\u0004 כלומר, להתיר לה להינשא לחוץ, \u0003ולא\u0004 נאמנת לומר \u0003מתה אחותי שאכנס לביתה,\u0004 כלומר, שאנשא לבעלה. ונדייק: \u0003היא ניהי דלא מהימנא\u0004 \u0005[היא עצמה\u0006 היא \u0005שאינה נאמנת],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 אם היה \u0003עד אחד — מהימן\u0004 \u0005[נאמן]!\u0006","ודוחים: \u0003וליטעמיך, אימא סיפא\u0004 \u0005[ולטעמך,\u0006 לשיטתך, שכך אתה מדייק, \u0005אמור\u0006 את \u0005סופה\u0006 של המשנה\u0005]:\u0006 \u0003אין האיש נאמן לומר מת אחי שאייבם את אשתו, ולא\u0004 נאמן לומר \u0003מתה אשתי שאשא את אחותה,\u0004 ואם תדייק באותה דרך עליך לומר \u0003הוא ניהו דלא מהימן\u0004 \u0005[הוא עצמו הוא\u0006 \u0005שאינו נאמן]\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003עד אחד מהימן\u0004 \u0005[נאמן]\u0006 אולם דבר זה מופרך, שהרי \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003גבי\u0004 (אצל) \u0003אשה משום עיגונא\u0004 \u0005[עיגון]\u0006 \u0003אקילו בה רבנן\u0004 \u0005[הקילו בה חכמים]\u0006 לסמוך על עד אחד, \u0003אלא גבי איש מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי אי אפשר להתירו על פי עדות בלתי שלימה שכזו!","\u0003אלא,\u0004 אין לדייק מהמשנה איך הדין בעד אחד, \u0003כי איצטריך\u0004 \u0005[כאשר הוצרכה]\u0006 להיאמר הלכה זו שאין האשה נאמנת לומר מת יבמי — \u0003ל\u0004דעת \u0003ר' עקיבא איצטריך\u0004 \u0005[הוצרכה],\u0006 כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה\u0006 על \u0005דעתך לומר]:\u0006 \u0003הואיל ואמר ר' עקיבא\u0004 כי \u0003יש ממזר מחייבי לאוין,\u0004 ולכן אף היבמה הנישאת לחוץ שלא כדין יהיה וולדה ממזר, \u0003אימא חיישא אקלקולא דזרעא ודייקא\u0004 \u0005[אמור\u0006 שמא \u0005חוששת,\u0006 דואגת, היא \u0005על קלקול זרעה ותדייק]\u0006 ולא תינשא אלא בעדות ברורה, על כן \u0003קא משמע לן דאקלקולא דידה חיישא\u0004 \u0005[השמיע לנו שעל קלקול שלה\u0006 היא \u0005חוששת]\u0006 כגון שיש ספק אם מת בעלה שאז היא יוצאת גם מבעלה השני, אבל \u0003אקלקולא דזרעא לא חיישא\u0004 \u0005[על קילקול של זרעה אינה חוששת]\u0006 עד כדי כך, ועשויה להינשא שלא כדין.","\u0003רבא אמר: עד אחד נאמן ביבמה מקל וחומר.\u0004 ומהו: אם \u0003לאיסור כרת\u0004 של אשת איש \u0003התרת\u0004 על ידי עדות של עד אחד, \u0003לאיסור לאו\u0004 של יבמה לחוץ \u0003לא כל שכן?! אמר ליה ההוא מרבנן\u0004 \u0005[אמר לו אחד החכמים]\u0006 \u0003לרבא: היא עצמה,\u0004 כלומר, האשה המעידה לגבי עצמה \u0003תוכיח\u0004 שאין הדבר כן, שהרי \u0003לאיסור כרת התרת\u0004 שאם היא מעידה שמת בעלה — מתירים לה להינשא לכל אדם, ואין חוששים שמא אשת איש היא, \u0003לאיסור לאו לא התרת,\u0004 שהרי אינה נאמנת לומר שמת יבמה על מנת שתינשא לחוץ!","\u0003ואלא איהי מאי טעמא לא מהימנא\u0004 \u0005[היא\u0006 עצמה \u0005מה טעם אינה נאמנת],\u0006 ש\u0003כיון דזימנין דסניא ליה, לא דייקא ומינסבא\u0004 \u0005[שפעמים ש\u0006היא \u0005שונאת אותו, אינה מדייקת\u0006 בבדיקת הדברים \u0005ונישאת],\u0006 \u0003עד אחד נמי\u0004 \u0005[גם כן]\u0006 יש לומר אותו חשש: ש\u0003כיון דזימנין דסניא ליה, לא דייקא ומינסבא\u0004 \u0005[שפעמים ש\u0006היא \u0005שונאת אותו, אינה מדייקת ונישאת],\u0006 שהרי אין עד אחד נאמן אלא בצירוף הסיבה שהיא גם מדייקת. ואם כן אין ביסוס לקל וחומר זה, ולא נמצא פתרון לשאלה שנשאלה.","שנינו במשנה: \u0003זה\u0004 ה\u0003מדרש דרש ר' אלעזר בן מתיא וכו'.\u0004 שהכתוב \"ואשה גרושה מאישה\" בא ללמד שגט שניתן על ידי אדם שאינו בעלה, אינו פוסלה. \u0003אמר רב יהודה אמר רב: הוה ליה\u0004 \u0005[היה לו]\u0006 \u0003לר' אלעזר למדרש ביה מרגניתא\u0004 \u0005[לדרוש בו\u0006 בפסוק זה \u0005מרגלית]\u0006 \u0003ודרש ביה חספא\u0004 \u0005[בו חרס],\u0006 כלומר, היה יכול לדרוש דרשה חשובה יותר, ודרש וחידש בו רק דבר קטן.","\u0003מאי מרגניתא\u0004 \u0005[מה,\u0006 איזו, \u0005מרגלית]!\u0006 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 מה שנאמר: \u0003\"ואשה גרושה מאישה\u0004 לא יקחו\u0003\"\u0004 (ויקרא כא, ז), בא ללמד ש\u0003אפילו לא נתגרשה אלא מאישה,\u0004 שנפרדה ממנו ולא הותרה לאחרים, כגון שכתב לה בגט \"הרי זה גיטך ואין את מותרת לכל אדם\" שגט כזה ודאי אינו מתיר אותה להינשא לאחר, ואינו נחשב גט לכל דבר, מכל מקום \u0003פסולה לכהונה.\u0004 שאם אחר כך מת בעלה — תיחשב כגרושה ולא כאלמנה ואסורה להינשא לכהן, שגט זה בכל זאת הועיל בה לפסול, \u0003והיינו\u0004 \u0005[וזהו]\u0006 \u0003\"ריח הגט\"\u0004 שאינו גט ממש, ובכל זאת הוא ש\u0003פוסל בכהונה.\u0004","\u0003מי שהלכה אשתו למדינת הים,\u0004 ו\u0003באו ואמרו לו \"מתה אשתך\", ונשא את אחותה, ואחר כך באת אשתו\u0004 ממדינת הים — \u0003מותרת לחזור\u0004"],["\u0003לו,\u0004 שנישואי הטעות שנשא את האחות נחשבים כזנות, ואין זנות עם קרובת אשתו פוסלת את אשתו. \u0003ומותר בקרובות שניה\u0004 כגון בבתה, \u0003ושניה מותרת בקרוביו,\u0004 כגון בבנו. לפי שלא תפסו בה כלל הנישואין הללו. \u0003ואם מתה\u0004 ה\u0003ראשונה — מותר בשניה\u0004 אף שבא עליה כבר באיסור.","\u0003אמרו לו: מתה אשתו, ונשא את אחותה. ואחר כך אמרו לו: קיימת היתה\u0004 האשה בזמן שנשא את אחותה, \u0003ומתה\u0004 רק אחר כך. \u0003הולד\u0004 ה\u0003ראשון,\u0004 זה שנולד לאחות בזמן שהיתה אשתו עדיין חיה — \u0003ממזר,\u0004 שהרי הוא בן אחות אשתו בחיי אשתו, \u0003והאחרון אין ממזר. ר' יוסי אומר: כל שפוסל על ידי אחרים — פוסל על ידי עצמו, וכל שאין פוסל על ידי אחרים — אינו פוסל על ידי עצמו,\u0004 כאשר יבואר הדבר בגמרא.","ומעירים, שמה שאמרו לו לאותו אדם מתה אשתו ונשא את אחותה, \u0003ואף על גב דאזיל\u0004 \u0005[ואף על פי שהלכו]\u0006 \u0003אשתו וגיסו\u0004 (בעל אחות אשתו) \u0003למדינת הים\u0004 והודיעו לו שמתו שניהם, \u0003דאהני\u0004 \u0005[שהועילו,\u0006 פעלו\u0005]\u0006 \u0003הני\u0004 \u0005[אלו]\u0006 ה\u0003נשואים\u0004 שהוא עשה, \u0003דקמיתסרא\u0004 \u0005[שנאסרת]\u0006 \u0003אשת גיסו\u0004 על \u0003גיסו,\u0004 שהרי נמצא שנשא אשת איש בטעות, וכפי ששנינו לעיל שהנושא אשת איש בטעות נאסרת על בעלה, ו\u0003אפילו הכי\u0004 \u0005[כך],\u0006 \u0003אשת גיסו אסירא\u0004 \u0005[אסורה]\u0006 לבעלה, ואילו \u0003אשתו שריא\u0004 \u0005[מותרת]\u0006 לו,","\u0003ולא אמרינן\u0004 \u0005[ואין אנו אומרים]\u0006 ש\u0003מתוך שנאסרה אשת גיסו\u0004 על \u0003גיסו, תיאסר\u0004 גם \u0003אשתו עליו,\u0004 אף על פי שאותו מעשה עצמו גרם לאסור אשה זו על בעלה. ומציעים: \u0003לימא מתניתין\u0004 \u0005[\u0006האם \u0005לומר\u0006 ש\u0005משנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' עקיבא, דאי\u0004 \u0005[שאם]\u0006 כשיטת \u0003ר' עקיבא\u0004 היא — \u0003הויא לה\u0004 \u0005[\u0006הרי, \u0005היא,\u0006 אשתו, נעשית \u0005לו]\u0006 \u0003אחות גרושתו.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כל עריות שבתורה,\u0004 גם אם נשא אותן — \u0003אין צריכות הימנו גט, חוץ מאשת איש שנישאת\u0004 בטעות \u0003על פי בית דין, ור' עקיבא מוסיף אף אשת אח ואחות אשה,\u0004 שמכיון שיש אופן שאלה יוכלו להיות מותרות לו: אשת אח על ידי ייבום, ואחות אשה במות אשתו — לכן צריכות הן גט כשנשאן. \u0003ו\u0004לענייננו, \u0003כיון\u0004 ש\u0003אמר ר' עקיבא\u0004 שאחות אשתו \u0003בעיא\u0004 \u0005[צריכה]\u0006 \u0003גט, ממילא איתסרא עליה\u0004 \u0005[נאסרה עליו]\u0006 אשתו, \u0003דהויא לה\u0004 \u0005[שהרי היא,\u0006 אשתו, נעשית\u0005]\u0006 \u0003אחות גרושתו.\u0004","ודוחים: \u0003ולאו איתמר עלה\u0004 \u0005[ו\u0006כי \u0005לא נאמר עליה]\u0006 \u0003אמר רב גידל אמר רב חייא בר יוסף אמר רב: האי\u0004 \u0005[זו]\u0006 \u0003אשת אח\u0004 שאמר ר' עקיבא \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 היה \u0005הדבר] —\u0006 \u0003כגון שקדש אחיו את האשה, והלך\u0004 האח \u0003למדינת הים, ושמע\u0004 האיש הנמצא כאן \u0003שמת אחיו, ועמד ונשא את אשתו\u0004 כיבמה, \u0003דאמרי אינשי\u0004 \u0005[שאומרים אנשים]\u0006 שאינם יודעים היטב מה אירע: \u0003הך קמא, תנאה הוה ליה\u0004 \u0005[זה הראשון, תנאי היה לו]\u0006 \u0003בקידושין\u0004 עם אשתו, ומן הסתם בטלו הקידושין הללו לפי שלא נתקיים התנאי, \u0003והאי שפיר נסיב\u0004 \u0005[וזה, יפה,\u0006 כדין, \u0005נשא],\u0006 שאינה אשת אחיו. ומשום כך אמר ר' עקיבא שצריך לתת גט.","\u0003ו\u0004כן \u0003האי\u0004 \u0005[וזו]\u0006 \u0003אחות אשה נמי\u0004 \u0005[גם כן]\u0006 \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 היה \u0005הדבר] —\u0006 \u0003כגון שקידש את אשה, והלכה למדינת הים, ושמע שמתה, עמד ונשא את אחותה. דאמרי אינשי\u0004 \u0005[שאומרים אנשים]:\u0006 \u0003הך קמייתא\u0004 \u0005[זו הראשונה],\u0006 \u0003תנאי הוה ליה\u0004 \u0005[היה לו]\u0006 \u0003בקדושיה,\u0004 ולא נתקיים התנאי, ובטלו הקידושין, \u0003והא שפיר נסיב\u0004 \u0005[וזה, יפה,\u0006 כדין, \u0005נשא],\u0006 \u0003אלא\u0004 במשנתנו שהיו \u0003נשואין\u0004 ממש קודם לכן, \u0003מי איכא למימר תנאה הוה ליה\u0004 \u0005[האם יש\u0006 מקום \u0005לומר\u0006 ש\u0005תנאי היה לו]\u0006 \u0003בנשואין?\u0004 הלא מוחזק בידינו שאדם אינו נושא אשה על תנאי, ואם נשא אותה — מן הסתם ביטל את כל התנאים המעכבים, ואף לשיטת ר' עקיבא אין אחותה צריכה גט.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לרב כהנא: אי\u0004 \u0005[אם]\u0006 לפי שיטת \u0003ר' עקיבא, ליתני נמי\u0004 \u0005[שישנה גם כן]\u0006 \u0003חמותו\u0004 כמקרה נוסף של ערוה שצריך לתת גט. \u0003דהא שמעינן ליה\u0004 \u0005[שהרי שמענו אותו]\u0006 את \u0003ר' עקיבא,\u0004 ש\u0003אמר: חמותו לאחר מיתה\u0004 של אשתו — \u0003לאו\u0004 \u0005[לא]\u0006 נידונה \u0003בשרפה,\u0004 שאיסור חמותו החמור בטל במות אשתו.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נאמר בתורה על מי שנושא אשה ובתה: \u0003\"באש ישרפו אתו ואתהן\"\u0004 (ויקרא כ, יד), שודאי אין לפרש ששורפים את שתיהן, שהרי האשה הראשונה שנשא — היא עצמה לא חטאה כלל, ובודאי שאינה צריכה להיענש, ולכן פירשו את המלה \"אתהן\" \u0003אותו ואת אחת מהן,\u0004 זו שנשא באחרונה שהיתה אסורה עליו, אלו \u0003דברי ר' ישמעאל. ר' עקיבא אומר: אותו ואת שתיהן.\u0004 וכיון שדבר זה תמוה מאד לומר שיענשו את שתיהן, גם את זו שנשא כדין, רבו הדעות להסביר את שיטת ר' עקיבא.","\u0003בשלמא\u0004 \u0005[ננינח]\u0006 \u0003ל\u0004שיטת \u0003אביי\u0004 ש\u0003אמר\u0004 ופירש ש\u0003משמעות דורשין\u0004 (דרש) \u0003איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 שלא נחלקו בגופה של הלכה, אלא בדרך המדרש בה לומדים את ההלכות, ש\u0003ר' ישמעאל סבר: חדא כתיב\u0004 \u0005[אחת נאמרה]\u0006 כלומר, אותו ואת אחת מהן הוא משמעות פשוטו של הכתוב, \u0003ו\u0004אילו \u0003ר' עקיבא סבר: תרתי כתיב\u0004 \u0005[שתיים נאמרו]\u0006 ו\"אתו ואתהן\" פירושו: שתיהן, כל אחת מהן, וכגון שנשא שתי נשים באיסור זה, למשל חמותו ואם חמותו — ששתיהן בשריפה, שכל אחת מהן אסורה, וזו משמעות הכתוב האומר שתיהן. ואם כן, לשיטה זו, \u0003שפיר\u0004 \u0005[יפה],\u0006 ואין זה נוגע למה שאמרנו.","\u0003אלא ל\u0004דעת \u0003רבא\u0004 ש\u0003אמר:\u0004 לענין \u0003חמותו לאחר מיתה\u0004 של אשתו \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל בהלכה, שלדעת ר' ישמעאל האשה השניה שנושא, כגון שנשא את הבת ואחר כך נשא את החמות, אפילו לאחר מות הבת — חייב עליה. ואילו לדעת ר' עקיבא אין החיוב חל עליו אלא כאשר שתיהן קיימות (\"ואתהן\") ואם מתה הראשונה שוב אין השניה אסורה באותו איסור מן התורה, אם כן, \u0003ליתני נמי\u0004 \u0005[שישנה גם כן]\u0006 \u0003חמותו,\u0004 שיצטרך לתת לה גט אם נשאה בטעות, שהרי גם לה יש היתר לאחר מות אשתו!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב כהנא: \u0003נהי דמיעטה קרא\u0004 \u0005[אם אמנם שמיעט אותה הכתוב]\u0006 \u0003מ\u0004עונש \u0003שרפה\u0004 — \u0003מאיסורא מי\u0004 \u0005[מאיסור האם]\u0006 \u0003מיעטה קרא\u0004 \u0005[הכתוב]?\u0006 שאף לדעת ר' עקיבא אסור מן התורה לשאת את חמותו אף לאחר מות אשתו, ואם כן אין בחמותו מקום לנישואין של היתר, אף לדעת רבא שסבור שר' עקיבא פוטר במקרה זה מעונש שריפה.","ושואלים מצד אחר: \u0003ותאסר\u0004 אשתו \u0003בשכיבה\u0004 ששכב עם \u0003אחותה, מידי דהוה\u0004 \u0005[כמו שהוא]\u0006 בענין \u0003אשה שהלך בעלה למדינת הים,\u0004 שהיא נאסרת לבעלה כאשר היא נבעלת לאיש אחר בטעות! ומשיבים, \u0003לא דמי\u0004 \u0005[אינו דומה]:\u0006 כי \u0003אשתו\u0004 שאם זנתה \u0003במזיד אסירא מדאורייתא\u0004 \u0005[אסורה\u0006 עליו \u0005מן התורה],\u0006 ואם נבעלה \u0003בשוגג — גזרו בה רבנן\u0004 \u0005[חכמים]\u0006 שתיאסר עליו,"],["\u0003אחות אשה\u0004 שאפילו אם בא עליה \u0003במזיד,\u0004 אשתו \u0003לא אסירא מדאורייתא\u0004 \u0005[אסורה מן התורה],\u0006 כפי שיבואר להלן, אם כן \u0003בשוגג — לא גזרו בה רבנן\u0004 \u0005[חכמים].\u0006 \u0003ומנלן דלא אסירא\u0004 \u0005[ומניין לנו שאינה אסורה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר: \u0003\"\u0004איש כי תשטה אשתו... ושכב איש \u0003אותה\"\u0004 (במדבר ה, יב-יג), ההדגשה במלה \"אותה\" באה ללמד: \u0003אותה, שכיבתה\u0004 עם אחר \u0003אוסרתה\u0004 על בעלה, \u0003ואין שכיבת אחותה אוסרתה.\u0004","\u0003שיכול\u0004 היית לומר לולא המיעוט הזה, \u0003והלא דין\u0004 (קל וחומר) \u0003הוא: ומה במקום שבא על איסור קל — נאסר האוסר\u0004 הזה, \u0003מקום שבא על איסור חמור — אינו דין שנאסר האוסר,\u0004 וכפי שיבואר הדבר להלן.","\u0003אמר ר' יהודה: לא נחלקו בית שמאי ובית הלל בבא על חמותו שפוסל את אשתו\u0004 עליו. \u0003על מה נחלקו — בבא על אחות אשתו, שבית שמאי אומרים: פוסל\u0004 את אשתו, \u0003ובית הלל אומרים: לא פוסל. אמר ר' יוסי:\u0004 אינו כן, \u0003לא נחלקו בית שמאי ובית הלל בבא על אחות אשתו שלא פוסל את אשתו, על מה נחלקו — בבא על חמותו, שבית שמאי אומרים: פוסל, ובית הלל אומרים: לא פוסל.\u0004","\u0003לפי שבתחלה,\u0004 לפני הנישואין, \u0003הוא מותר בכל הנשים שבעולם והיא מותרת בכל האנשים שבעולם.\u0004 לאחר ש\u0003קדשה\u0004 לו לאשה — \u0003הוא אוסרה\u0004 בכל הגברים, \u0003והיא אסרתו\u0004 בקרובותיה. ומעירים: \u0003מרובה איסור ש\u0004הוא \u0003אסרה, מאיסור שאסרתהו\u0004 היא. \u0003שהוא אסרה בכל\u0004 ה\u0003אנשים שבעולם, והיא לא אסרתהו\u0004 על ידי הקידושין \u0003אלא בקרובותיה.\u0004","\u0003והלא דין הוא: ומה הוא, שאסרה\u0004 על ידי הקידושין \u0003בכל\u0004 ה\u0003אנשים שבעולם,\u0004 ובכל זאת אם \u0003שגגה באסור לה,\u0004 שנבעלה לאדם אחר בשוגג, \u0003אינה נאסרת במותר לה,\u0004 בבעלה, \u0003היא, שלא אסרתהו אלא בקרובותיה,\u0004 אם \u0003שגג באסור לו\u0004 באחת מקרובותיה, כגון באחותה, \u0003אינו דין שלא נאסר לו במותר לו\u0004 באשתו?!","\u0003וזה הדין\u0004 והטעם \u0003לשוגג,\u0004 שאם שגג באחת מקרובות אשתו — אין אשתו נאסרת עליו. \u0003למזיד מנין? תלמוד לומר: \"אותה\"\u0004 בא למעט: \u0003אותה, שכיבתה אוסרתה, ואין שכיבת אחותה אוסרתה.\u0004","\u0003אמר ר' אמי אמר ריש לקיש: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה\u0004 שהבא על חמותו אסורה אשתו עליו — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"באש ישרפו אתו ואתהן\"\u0004 (ויקרא כ, יד), ותמוה: \u0003וכי כל הבית כולו בשרפה?!\u0004 מדוע ישרפו את שתיהן אם עשה איסור, הלא רק באחת מהן עשה! אלא \u0003אם אינו ענין לשרפה\u0004 שיש בכך, \u0003תנהו ענין לאיסורא\u0004 \u0005[לאיסור],\u0006 ששתיהן נאסרות עליו, ויש כאן איפוא דין מיוחד שבגללו נאסרת לא רק האשה שחטא בה אלא גם אשתו.","\u0003אמר רב יהודה אמר שמואל: אין הלכה כר' יהודה.\u0004 מסופר: \u0003ההוא דעבד איסורא בחמתיה\u0004 \u0005[אחד שעשה איסור\u0006 שבא \u0005על חמותו],\u0006 \u0003אתייה\u0004 \u0005[הביאו]\u0006 \u0003רב יהודה\u0004 לפניו לדין ו\u0003נגדיה\u0004 \u0005[\u0006ו\u0005הלקהו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי לאו\u0004 \u0005[אלמלא]\u0006 ש\u0003אמר שמואל אין הלכה כר' יהודה — אסריתה עלך איסורא דעלם\u0004 \u0005[הייתי אוסר אותה\u0006 את אשתך \u0005עליך איסור עולם].\u0006","בתחילת הברייתא הזו נלמד קל וחומר שאינו מובן לגמרי, שנאמר בו: \"מה במקום שבא על איסור קל נאסר האוסר וכו'\" ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"איסור קל\"\u0004 שנאמר שם? \u0003אמר רב חסדא: מחזיר גרושתו משנשאת\u0004 לאחר, הוא האיסור הקל.","וכך יש להבין את הקל וחומר: אם \u0003בא עליה האי\u0004 \u0005[זה]\u0006 הבעל השני — \u0003אסרה עליה דהאי\u0004 \u0005[על זה]\u0006 על בעלה הראשון, שהרי היא גרושתו שנישאת. ואם האיש השני גירש אותה ו\u0003בא עליה אידך\u0004 \u0005[האחר],\u0006 כלומר, בעלה הראשון, \u0003אסרה עליה דהאי\u0004 \u0005[על זה]\u0006 שהיא לו גם כן גרושתו שנישאת.","ומכאן נלמד שאף באיסור קל זה — האוסר אותה, אף הוא עצמו נאסר על ידי ביאה זו, ודוחים: \u0003מה למחזיר גרושתו משנשאת,\u0004 שכן יש בה כמה צדדים חמורים ואין לקרוא לה איסור קל, \u0003שכן נטמא הגוף\u0004 על ידי ביאה זו, כאמור בתורה: \"... אחרי אשר הוטמאה\" (דברים כד, ד), \u0003ואיסורה ברוב,\u0004 כלומר, האיסור הזה קיים ברוב בני ישראל בשווה, ולא באנשים מסויימים בלבד, \u0003ואיסורה\u0004 הוא גם \u0003איסור עולם,\u0004 שהרי אינה מותרת לבעלה הראשון לאחר שבא עליה הבעל השני, מה שאין כן באחות אשתו, שאם מתה אשתו מותר באחותה.","\u0003אלא אמר ריש לקיש:\u0004 יש לדחות פירוש זה, והכוונה היא ל\u0003יבמה,\u0004 שהיא קרויה איסור קל, שהבא עליה נאסר. ומבררים: \u0003יבמה\u0004 שנבעלה \u0003למאן\u0004 \u0005[למי]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שנבעלה \u0003לאחר,\u0004 שאינו היבם שלה, \u0003וכ\u0004דברי \u0003רב המנונא,\u0004 ש\u0003אמר רב המנונא: שומרת יבם שזינתה — אסורה ליבמה.\u0004 והקל וחומר יהיה: שהיבמה, אף שהיבם אוסרה לכל העולם, אם נבעלה נאסרת גם עליו.","אולם יש לדחות: \u0003מה ליבמה שכן\u0004 בביאה אסורה זו \u0003נטמא הגוף, ואיסורה\u0004 חל \u0003ברוב\u0004 ישראל, ולכן אי אפשר ללמוד ממנה לאיסורים שבקרובות אשתו.","\u0003אלא\u0004 תאמר שמדובר שם במקרה של \u0003יבמה לאחין\u0004 ובאופן זה: \u0003עבד\u0004 \u0005[עשה]\u0006 \u0003בה מאמר האי\u0004 \u0005[\u0006אח \u0005זה] —\u0006 \u0003אסרה עליה דהאי\u0004 \u0005[על זה]\u0006 על כל אח אחר, שהרי היא כעין ארוסתו. \u0003בא עליה אידך\u0004 \u0005[\u0006האח \u0005האחר],\u0006 אחד האחים שלא עשה בה מאמר — \u0003אסרה עליה דהאי\u0004 \u0005[על זה]\u0006 על האח שעשה בה מאמר. אולם \u0003מאי איריא\u0004 \u0005[מה שייך]\u0006 מדוע דווקא \u0003שבא עליה שני? אפילו\u0004 אם \u0003עבד\u0004 \u0005[עשה]\u0006 \u0003בה נמי\u0004 \u0005[גם כן]\u0006 האח השני \u0003מאמר\u0004 אסר אותה על הראשון, ואם כן לא הביאה היא הגורמת כאן לאיסור!","ודוחים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה],\u0006 כי אפשר לפרש שדבר זה הוא \u0003כ\u0004שיטת \u0003רבן גמליאל,\u0004 ש\u0003אמר: אין מאמר אחר מאמר,\u0004 שאם עשה בה אח אחד מאמר, שוב אין מאמר אחר תופס בה כלל. \u0003אלא\u0004 אפשר לדחות את ההסבר שבכלל אין האיסור ליבם תלוי בביאה, שהרי \u0003אפילו נתן לה\u0004 האח האחר \u0003גט,\u0004 או \u0003אפילו חלץ לה\u0004 האחר, גם כן פסל אותה על הראשון!","\u0003אלא אמר ר' יוחנן:\u0004 \"איסור קל\" שאמרנו הוא איסור \u0003סוטה.\u0004 ושואלים: \u0003סוטה למאן\u0004 \u0005[למי]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003לבעל,\u0004 ותפרש כך: כיון ש\u0003בא עליה בעל\u0004 שאסור בה לאחר שקינא לה ונסתרה — \u0003אסרה עליה\u0004 \u0005[עליו]\u0006 על ה\u0003בועל,\u0004 שאסור לה להינשא לו אחר כך, גם אם נתגרשה מבעלה. אולם \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 \u0003בא עליה? אפילו נתן לה\u0004 בעלה \u0003גט\u0004 ולא בא עליה מאז שנסתרה — אסורה לבועל, \u0003ואפילו אמר\u0004 הבעל \u0003\"אין אני משקה\",\u0004 ואינו מקפיד על כך — בכל זאת נאסרה לבועל!","\u0003אלא\u0004 יש לומר שמדובר פה ב\u0003סוטה\u0004 שנבעלה \u0003לבועל,\u0004 שנאסרת על הבעל לעולם על ידי ביאה זו שבא עליה בעודה אשת איש. אולם תמוה: וכי \u0003האי\u0004 \u0005[זה],\u0006 \u0003איסור קל הוא?\u0004 הלא \u0003איסור חמור הוא, דהיינו\u0004 \u0005[שהריהו]\u0006 איסור \u0003אשת איש\u0004 שהוא מן החמורים שבאיסורים!"],["\u0003אלא אמר רבא\u0004 \"איסור קל\" שאמרו הוא איסור \u0003אשת איש. וכן כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יוחנן:\u0004 \"איסור קל\" זה הוא איסור \u0003אשת איש. ומאי קרי לה\u0004 \u0005[ומה\u0006 טעם \u0005קורא לו]\u0006 \u0003\"איסור קל\"\u0004 — לפי שהוא שונה וקל משאר איסורי עריות, בכך \u0003שאין\u0004 בעלה \u0003האוסרה, אוסרה כל ימיו,\u0004 שהרי יכול להפקיע את האיסור על ידי גט. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003אבא חנן אמר משום\u0004 \u0005[בשם]\u0006 \u0003ר' אלעזר:\u0004 \"איסור קל\" זה הוא איסור \u0003אשת איש.\u0004","וכך יש להבין את הדרש: \u0003ומה במקום הבא על\u0004 אשת איש שהיא \u0003איסור קל,\u0004 ומדוע קל הוא — \u0003שאין האוסרה אוסרה כל ימיו,\u0004 מכל מקום \u0003נאסר האוסר,\u0004 שאשת איש שזינתה, בעלה נאסר בה לעולם — \u0003הבא על איסור חמור\u0004 כגון אחות אשתו, ומדוע חמור הוא \u0003ש\u0004כן \u0003האוסרה\u0004 (אשתו) \u0003אוסרה כל ימיו\u0004 שכל זמן שאשתו קיימת אחותה אסורה לו — \u0003אינו דין שנאסר האוסרה?\u0004","לכן \u0003תלמוד לומר \"אותה\"\u0004 ללמד: \u0003אותה שכיבתה אוסרתה, ואין שכיבת אחותה אוסרתה.\u0004","שנינו במשנה ש\u0003ר' יוסי אומר: כל שפוסל\u0004 על ידי אחרים — פוסל על ידי עצמו, ושאין פוסל על ידי אחרים — אינו פוסל על ידי עצמו. ושואלים: \u0003מאי קאמר\u0004 \u0005[מה אמר]\u0006 \u0003ר' יוסי,\u0004 מה היא משמעות הדברים? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003דקאמר\u0004 \u0005[\u0006מה \u0005שאמר]\u0006 ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003דאזיל\u0004 \u0005[שהלכו]\u0006 \u0003אשתו וגיסו למדינת הים\u0004 ובא על כן בטעות על אחות אשתו, הנשואה לגיסו, ואז \u0003אשת גיסו אסירא\u0004 \u0005[אסורה]\u0006 על בעלה־הגיס, \u0003ואשתו שריא\u0004 \u0005[מותרת]\u0006 לו,","\u0003וקאמר ליה\u0004 \u0005[ואמר לו]\u0006 \u0003ר' יוסי: כי היכי\u0004 \u0005[כמו]\u0006 ש\u0003אשתו שריא\u0004 \u0005[מותרת]\u0006 לו — \u0003אשת גיסו נמי שריא\u0004 \u0005[גם כן מותרת]\u0006 לבעלה, והנימוק הוא, שכיון שאינו פוסל את אשתו לעצמו, שכן נישואיו עם אחותה היו בטעות, גם אינו פוסל לאחרים, ומעירים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 הביטוי שהשתמש בו ר' יוסי במשנה אינו מכוון לדברים, שלא היה צריך לומר \u0003כל שאין פוסל על ידי אחרים — אין פוסל על ידי עצמו,\u0004 אלא: \u0003כל שאין פוסל על ידי עצמו,\u0004 שבעילה זו אינה אוסרת את אשתו עליו — \u0003אינו פוסל על ידי אחרים\u0004 גם את אשת האחר, \u0003מיבעיא ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006","\u0003ואלא,\u0004 יש לפרש את דברי ר' יוסי להיפך: \u0003כי היכי\u0004 \u0005[כמו]\u0006 ש\u0003אשת גיסו אסירא\u0004 \u0005[אסורה]\u0006 לבעלה, \u0003אשתו נמי אסירא\u0004 \u0005[גם כן אסורה]\u0006 לו, ומעתה, \u0003התינח\u0004 \u0005[נניח]\u0006 שזה מסביר את מה שאמר \u0003\"כל שפוסל\",\u0004 לומר, שכיון שהוא פוסל אחרים, את אשת גיסו על גיסו — פוסל גם כן את אשתו עליו. אלא ההמשך \u0003\"כל שאינו פוסל\" מאי עבידתיה\u0004 \u0005[מה מעשהו]\u0006 מה עניינו לכאן? שהרי אין לו קשר לדברי ר' יוסי.","\u0003אמר ר' אמי:\u0004 דבריו של ר' יוסי מתייחסים לא להלכה זו אלא \u0003ארישא\u0004 \u0005[לראש\u0006 הפרק\u0005]\u0006 ששנינו שם: \u0003ניסת\u0004 (נישאת) \u0003על פי בית דין — תצא ופטורה מן הקרבן.\u0004 נישאת \u0003על פי עדים\u0004 בלא הוראת בית דין — \u0003תצא וחייבת בקרבן. יפה כחו של בית דין שפטרה מן הקרבן.\u0004","ולפי זה אם יצאו אשתו ובעל אחות אשתו (גיסו) למדינת הים ובאה עדות שמתו שניהם, \u0003וקאמר\u0004 \u0005[ואמר]\u0006 ה\u0003תנא קמא\u0004 \u0005[הראשון]:\u0006 \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 הנישאת \u0003על פי עדים\u0004 בלבד, שאז \u0003אשת גיסו שריא\u0004 \u0005[מותרת]\u0006 לבעלה, שכיון שנישאת על פי עדים, נחשב הדבר לאונס, ואשתו גם כן מותרת לו. \u0003ולא שנא\u0004 \u0005[שונה]\u0006 הנישאת \u0003על פי בית דין\u0004 שאז אף ש\u0003אשת גיסו אסירא\u0004 \u0005[אסורה],\u0006 בכל אופן אשתו מותרת.","\u0003וקאמר ליה\u0004 \u0005[ואמר לו]\u0006 \u0003ר' יוסי:\u0004 בנישאת \u0003על פי בית דין\u0004 ש\u0003פוסל על ידי אחרים — פוסל\u0004 גם \u0003על ידי עצמו.\u0004 אבל \u0003על פי עדים\u0004 ש\u0003אינו פוסל על ידי אחרים,\u0004 מודה אני להלכה זו ש\u0003אינו פוסל על ידי עצמו\u0004 ואשתו מותרת לו.","\u0003ר' יצחק נפחא\u0004 \u0005[הנפח]\u0006 \u0003אמר: לעולם\u0004 הדברים מוסבים \u0003אסיפא\u0004 \u0005[על סוף\u0006 משנתנו\u0005],\u0006 אלא שיש לחלק: \u0003הא\u0004 \u0005[זה] —\u0006 \u0003דנסיב\u0004 \u0005[\u0006כ\u0005שנשא]\u0006 את \u0003אשת גיסו, והא\u0004 \u0005[וזה] —\u0006 \u0003דנסיב\u0004 \u0005[\u0006כ\u0005שנשא]\u0006 את \u0003ארוסת גיסו.\u0004 וכך היו הדברים: \u0003הא\u0004 \u0005[זה] —\u0006 \u0003דאזלי\u0004 \u0005[שהלכו]\u0006 \u0003ארוסתו וגיסו\u0004 למדינת הים, \u0003הא\u0004 \u0005[זה] —\u0006 \u0003דאזלי\u0004 \u0005[שהלכו]\u0006 \u0003אשתו וגיסו, וקאמר\u0004 \u0005[ואמר]\u0006 ה\u0003תנא קמא\u0004 \u0005[הראשון]:\u0006 \u0003לא שנא\u0004 \u0005[שונה]\u0006 אם היו אלה \u0003אשתו וגיסו, ולא שנא\u0004 \u0005[שונה]\u0006 אם היו אלה \u0003ארוסתו וגיסו — אשת גיסו אסירא\u0004 \u0005[אסורה]\u0006 לבעלה \u0003ואשתו שריא\u0004 \u0005[מותרת]\u0006 לו,","\u0003וקאמר ליה\u0004 \u0005[ואמר לו]\u0006 \u0003ר' יוסי: אשתו וגיסו, דליכא למימר תנאה הוה ליה\u0004 \u0005[שאין\u0006 מקום \u0005לומר\u0006 כי \u0005תנאי היה לו]\u0006 \u0003בנשואין\u0004 עם אשתו, והכל יודעים שנישואיו עם אחות אשתו היו בטעות, ומותרת לגיסו. וכיון ש\u0003אינו פוסל על ידי אחר — אינו פוסל\u0004 גם \u0003על ידי עצמו,\u0004 אבל אם היו אלה \u0003ארוסתו וגיסו, דאיכא למימר\u0004 \u0005[שיש\u0006 מקום לטעות ו\u0005לומר]\u0006 \u0003תנאה הוה ליה\u0004 \u0005[תנאי היה לו]\u0006 \u0003בקידושין\u0004 ולכן אסורה אשת גיסו לחזור לגיסו, \u0003ו\u0004כיון ש\u0003פוסל על ידי אחרים — אף פוסל על ידי עצמו\u0004 וארוסתו תיאסר עליו.","\u0003אמר רב יהודה אמר שמואל: הלכה כר' יוסי. מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יוסף: ומי\u0004 \u0005[והאם]\u0006 \u0003אמר שמואל הכי\u0004 \u0005[כך]?\u0006 \u0003והאתמר\u0004 \u0005[והרי נאמר]\u0006 שחלקו בדבר \u0003יבמה, רב אמר: הרי היא כאשת איש, ושמואל אמר: אינה כאשת איש. ואמר רב הונא\u0004 והסביר כי מחלוקת זו עוסקת במקרה \u0003כגון שקדש אחיו את האשה, והלך לו למדינת הים ושמע\u0004 האח שהיה כאן \u0003שמת אחיו, ועמד ונשא את אשתו\u0004 כיבם ואחר כך חזר אחיו.","ש\u0003רב אמר: הרי היא כאשת איש\u0004 שנישאת על פי עדות שמת בעלה — \u0003ואסורה ליבם,\u0004 כלומר, לבעלה הראשון שאחרי שנשא אותה אחיו הוא נקרא היבם, \u0003ושמואל אמר: אינה כאשת איש, ושריא ליה\u0004 \u0005[ומותרת לו].\u0006 והרי זו סתירה למה שאמר רב יהודה בשם שמואל שהלכה כר' יוסי, שגם כאן יש מקום לטעות ולומר שהראשון היה לו תנאי בקידושין ולא נתקיים, ולאחר שנשאה אחיו אסורה עליו משום אשת אחיו!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: וממאי דכי\u0004 \u0005[וממה\u0006 יודע אתה \u0005שכאשר]\u0006 \u0003אמר שמואל? הלכה כר' יוסי\u0004 על פירושו של \u0003ר' יצחק נפחא\u0004 לדברי ר' יוסי \u0003קאמר\u0004 \u0005[אמר]?\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 על פירושו של \u0003ר' אמי קאמר\u0004 \u0005[אמר],\u0006 שדברי ר' יוסי מתייחסים להבדל בין נישאת על פי בית דין ובין נישאת על פי עדים? \u0003ואי נמי\u0004 \u0005[ואם גם כן]\u0006 נפרש את פסקו של שמואל על דברי \u0003ר' יצחק נפחא, ממאי\u0004 \u0005[ממה]\u0006 אתה מסיק שמה שפסק הלכה כר' יוסי, הוא על הלכה זו של \u0003\"פוסל\",\u0004"],["\u0003ודלמא\u0004 \u0005[ושמא]\u0006 מה שפסק שמואל כר' יוסי מתייחס על ההלכה של \u0003\"אינו פוסל\"\u0004 את אשת גיסו על גיסו, וכגון שהלכו אשתו וגיסו?! \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר ליישב את הסתירה כך: \u0003ממאי דאיתא\u0004 \u0005[ממה,\u0006 מניין, \u0005שיש]\u0006 ביסוס \u0003ל\u0004דברי \u0003רב הונא\u0004 בפירוש מחלוקת רב ושמואל, \u0003דלמא ליתא\u0004 \u0005[שמא אין]\u0006 מקום לדבריו של \u0003רב הונא כלל,\u0004 ולא בנושא זה דיברו רב ושמואל, \u0003ו\u0004אפשר לפרש כי \u0003ב\u0004דברי \u0003רב המנונא קמיפלגי\u0004 \u0005[נחלקו].\u0006 ש\u0003אמר רב המנונא: שומרת יבם שזינתה\u0004 — \u0003אסורה ליבמה.\u0004","ולפי זה נפרש את המחלוקת כך: ש\u0003רב אמר: הרי היא כאשת איש, ו\u0004לכן \u0003מיפסלא\u0004 \u0005[נפסלת]\u0006 \u0003בזנות, ושמואל אמר: אינה כאשת איש, ולא מיפסלא\u0004 \u0005[ואינה נפסלת]\u0006 \u0003בזנות. ואי נמי\u0004 \u0005[ואם גם כן]\u0006 אפשר להסביר כי \u0003ב\u0004שאלה של \u0003קדושין תופסין ביבמה קמיפלגי\u0004 \u0005[חלוקים הם]\u0006, ש\u0003רב אמר:\u0004 היבמה \u0003הרי היא כאשת איש\u0004 לגבי כל מי שאינו יבמה \u0003ו\u0004לכן \u0003לא תפסי\u0004 \u0005[תופסים]\u0006 \u0003בה קדושין,\u0004 אם יקדש אותה כל אדם. \u0003ושמואל אמר: אינה כאשת איש, ותפסי\u0004 \u0005[ותופסים]\u0006 \u0003בה קדושין.\u0004","על תירוץ אחרון זה שואלים: איך אפשר לפרש כך את המחלוקת הסתומה של שני החכמים, \u0003והא אפליגו בה חדא זימנא\u0004 \u0005[והרי\u0006 כבר \u0005נחלקו בכך\u0006 במפורש \u0005פעם אחת]\u0006 ובוודאי לא יחלקו פעמיים בשני אופנים באותו ענין? ומשיבים: אפשר לומר שלא נחלקו מתחילה בשני נושאים, אלא \u0003חדא\u0004 \u0005[אחת]\u0006 \u0003מכלל\u0004 דברי \u0003חברתה איתמר\u0004 \u0005[נאמרה],\u0006 שרב ושמואל נחלקו רק פעם אחת, אלא שהיו שניסחו את המחלוקת בצורה שונה, וכמסקנה מן המחלוקת הראשונה.","\u0003אמרו לו\u0004 לאדם: \u0003\"מתה אשתך\", ונשא\u0004 את \u0003אחותה מאביה,\u0004 ולאחר זמן אמרו לו ש\u0003מתה\u0004 האשה השניה, \u0003ונשא\u0004 את \u0003אחותה מאמה\u0004 של אשתו השניה, ולאחר מכן אמרו לו ש\u0003מתה\u0004 זו \u0003ונשא\u0004 את \u0003אחותה מאביה\u0004 של האחרונה, ולאחר מכן אמרו לו ש\u0003מתה ונשא\u0004 את \u0003אחותה מאמה\u0004 של האחרונה, \u0003ו\u0004לבסוף \u0003נמצאו כולן קיימות — מותר ב\u0004אשתו ה\u0003ראשונה, ובשלישית ובחמישית,\u0004 שהרי אינן אחיות זו לזו, וקידושיו תפסו. ונישואיו נחשבים נישואין גמורים, שאם מת \u0003ו\u0004יבמו אחת מהן — \u0003פוטרות צרותיהן.\u0004","\u0003ו\u0004אולם \u0003אסור בשניה וברביעית,\u0004 שכל אחת מהם אסורה עליו משום אחות אשה הנשואה לו כדין. \u0003ו\u0004אם מת הוא והיבם בא על אחת מהן — \u0003אין ביאת אחת מהן פוטרת צרתה,\u0004 שכיון שהיתה אסורה על אחיו — אין כאן מצות ייבום כלל.","\u0003ואם\u0004 אירע ש\u0003בא על השניה\u0004 ברשימה זו \u0003לאחר מיתת הראשונה\u0004 שהראשונה באמת מתה, אף ששאר השמועות לא היו נכונות — \u0003מותר\u0004 אז \u0003בשניה וברביעית,\u0004 והן נשיו לגמרי \u0003ופוטרות צרותיהן, ואסור בשלישית ובחמישית\u0004 שהן אחיות לנשים הנשואות לו, \u0003ואין ביאת אחת מהן פוטרת צרתה.\u0004","ולענין אחר, ילד \u0003בן תשע שנים ויום אחד\u0004 שבא על יבמתו — \u0003הוא פוסל על ידי\u0004 (בכך) את ה\u0003אחין\u0004 בביאה זו, שאסורים לייבם, למרות שעדיין אינו גדול ולא קנה את יבמתו בביאה זו, \u0003והאחין פוסלין על ידו\u0004 את האשה. \u0003אלא\u0004 שההבדל הוא בכך ש\u0003הוא פוסל\u0004 רק אם בא עליה \u0003תחלה, והאחין פוסלין תחלה וסוף,\u0004","\u0003כיצד? בן תשע שנים ויום אחד שבא על יבמתו — פסל על ידי אחין,\u0004 שכל האחים אסורים מעתה לייבם אותה. ואם \u0003באו עליה אחין\u0004 או \u0003עשו בה מאמר,\u0004 או \u0003נתנו\u0004 לה \u0003גט, או חלצו\u0004 לה — \u0003פוסלין על ידו\u0004 והוא נאסר בה לעולם.","במשנה בסוף הפיסקה הראשונה נאמר: ואם בא על השניה לאחר מיתת הראשונה. ושואלים: \u0003אטו כולהו לאו\u0004 \u0005[האם כולם,\u0006 כל המקרים שבמשנה, \u0005לא]\u0006 \u0003לאחר מיתת\u0004 ה\u0003ראשונה נינהו\u0004 \u0005[הם]?\u0006 הרי כל הענין התחיל בכך שאמרו לו \"מתה אשתך\"! \u0003אמר רב ששת: לאחר מיתת ראשונה ודאי,\u0004 כלומר, לא לאחר שמועה שמתה, אלא לאחר שמתה באמת.","שנינו במשנה ש\u0003בן תשע שנים\u0004 ויום אחד שבא על יבמתו — פוסל את היבמה לאחים. ושואלים: האם \u0003בן תשע שנים ויום אחד\u0004 רק אם בא עליה ב\u0003תחלה פסיל\u0004 \u0005[פוסל]\u0006 אותה לאחים, אך אם בא עליה \u0003בסוף לא פסיל\u0004 \u0005[אינו פוסל]?\u0006 \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003רב זביד בר רב אושעיא: העושה מאמר ביבמתו, ואחר כך בא אחיו, שהוא בן תשע שנים ויום אחד, עליה — פסלה,\u0004 משמע שביאת קטן בן תשע פוסלת גם בסוף!","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003ביאה\u0004 של בן תשע — \u0003פסיל\u0004 \u0005[פוסלת]\u0006 \u0003אפילו בסוף,\u0004 אבל אם עשה רק \u0003מאמר, תחלה — פסיל\u0004 \u0005[פוסל],\u0006 \u0003בסוף — לא פסיל\u0004 \u0005[פוסל].\u0006 ושואלים: \u0003וביאה אפילו בסוף פסיל\u0004 \u0005[פוסלת]?\u0006 \u0003והא קתני\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אלא שהוא פוסל תחלה, והן תחלה וסוף. כיצד\u0004 זה? \u0003בן תשע שנים ויום אחד שבא על יבמתו וכו'!\u0004 ומשמע שהמשנה עצמה מפרשת פוסל תחילה על ידי ביאה!","ומשיבים: \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה \u0005וכך יש לשנותה]:\u0006 \u0003בן תשע שנים ויום אחד — הוא פוסל תחלה, והן פוסלין תחלה וסוף. במה דברים אמורים — במאמר,\u0004 שעשו אלה מאמר בה, \u0003אבל ביאה פוסלת אפילו בסוף. כיצד: בן תשע שנים ויום אחד הבא על יבמתו\u0004 לאחר שעשו אחיו מאמר — \u0003פסל\u0004 אותה \u0003על ידי\u0004 (לגבי) ה\u0003אחין.\u0004","ושואלים: \u0003ומי אית ליה\u0004 \u0005[והאם יש לו]\u0006 לבן תשע תורת \u0003מאמר כלל\u0004 שיהיה לו ערך \u0003על ידי\u0004 (לגבי) \u0003אחין\u0004 לפוסלם מייבום? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בן תשע שנים ויום אחד, הוא פוסל\u0004 את היבמה לאחים \u0003בדבר אחד, והאחין פוסלין על ידו בארבעה דברים.\u0004 כיצד? \u0003הוא פוסל על ידי אחין בביאה,\u0004 שאם בא על יבמתו נפסלה לכל האחים, \u0003והאחין פוסלין על ידו בביאה, במאמר, בגט, בחליצה!\u0004","ודוחים: משם אין ראיה, כי \u0003ביאה\u0004 של קטן ש\u0003פסלה בין בתחלה בין בסוף — פסיקא ליה\u0004 \u0005[פסוק,\u0006 גמור ומוחלט \u0005לו]\u0006 הדבר ולכן שנה בדרך זו, \u0003מאמר\u0004 של הקטן ש\u0003בתחילה\u0004 אם היה הוא הראשון שעשה בה מאמר \u0003פסיל\u0004 \u0005[פוסל],\u0006 ל\u0003בסוף לא פסיל\u0004 \u0005[אינו פוסל]\u0006 לאחר שעשו בה אחים מאמר — \u0003לא פסיקא ליה\u0004 \u0005[פסוק\u0006 גמור, מוחלט \u0005לו]\u0006 הענין, ולכן לא פירט דין זה משום שאינו מקביל בתחילה ובסוף.","\u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 על ידי אמוראים אחרים, \u0003אמר רב יהודה אמר שמואל: יש לו\u0004 לקטן \u0003גט\u0004 ביבמה, שאם נתן לה גט, אסר אותה על יתר האחים. \u0003וכן אמר רב תחליפא בר אבימי: יש לו מאמר.\u0004 ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003יש לו גט, ויש לו מאמר,\u0004 אלו \u0003דברי ר' מאיר.\u0004","ושואלים \u0003ו\u0004האם \u0003סבר ר' מאיר יש לו גט? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003עשו ביאת בן תשע כמאמר\u0004 שעשה \u0003גדול,\u0004 ו\u0003ר' מאיר אומר: עשו חליצת בן תשע כגט בגדול. ואם איתא\u0004 \u0005[יש\u0006 מקום\u0005]\u0006 לדברים שאמרנו — \u0003ליתני\u0004 \u0005[שישנה]\u0006 כך: עשו חליצתו של קטן \u0003כגיטו,\u0004 שהרי גם גט יש לו! \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: אית ליה\u0004 \u0005[יש לו]\u0006 גט \u0003ו\u0004אולם הוא \u0003זוטר\u0004 \u0005[קטן]\u0006 כלומר, תוקפו פחות וקטן מגט של יבם אחר.","שאפילו \u0003ל\u0004דעת \u0003רבן גמליאל\u0004 ש\u0003אמר\u0004 ש\u0003אין גט אחר גט\u0004 ביבמה, כגון שאם נתן אחד האחים גט שוב אין לגט שנתן אחיו כל תוקף — \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים כשניתן הגט \u0003בגדול אחר גדול ו\u0004כן \u0003ב\u0004\u0003קטן אחר קטן, אבל גדול\u0004 שנתן גט \u0003אחר קטן\u0004 שנתן גט — \u0003מהני\u0004 \u0005[מועיל]\u0006 הגט של הגדול לפסול ביבמה, משום שגט של קטן פחות בחשיבותו.","ואילו \u0003לרבנן דאמרי\u0004 \u0005[ל\u0006דעת \u0005חכמים שאומרים]\u0006 \u0003יש גט אחר גט — הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים \u0003בגדול אחר גדול\u0004 שנתנו שניהם גט, \u0003או בקטן אחר קטן, אבל\u0004 גם הם מסכימים שגט של \u0003קטן אחר\u0004 של \u0003גדול לא מהני\u0004 \u0005[מועיל],\u0006 שכוח הגט של קטן ודאי קטן יותר, לפיכך אמר ר' מאיר עשו חליצת בן תשע כגט בגדול, שלא יועיל אחריו גט של קטן."],["\u0003בן תשע שנים ויום אחד שבא על יבמתו, ואחר כך בא עליה אחיו שהוא\u0004 גם כן \u0003בן תשע שנים ויום אחד — פוסל\u0004 האח השני \u0003על ידו\u0004 (עבורו), כלומר, אוסר אותה על הראשון. \u0003ר' שמעון אומר: לא פוסל. בן תשע שנים ויום אחד שבא על יבמתו, ואחר כך בא\u0004 אותו ילד גם \u0003על צרתה — פוסל\u0004 אותה \u0003על ידי\u0004 (לגבי, על) \u0003עצמו,\u0004 ששתיהן נאסרות לו על ידי כך. \u0003ר' שמעון אומר: לא פוסל.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר להם ר' שמעון לחכמים: אם\u0004 ה\u0003ביאה\u0004 ה\u0003ראשונה\u0004 של בן תשע נחשבת ל\u0003ביאה\u0004 גמורה — אם כן ה\u0003ביאה\u0004 ה\u0003שנייה אינה ביאה,\u0004 כמו בביאת יבם גדול אחר יבם גדול, שאין השני קונה ביבמה. \u0003ואם\u0004 תאמר שה\u0003ביאה\u0004 ה\u0003ראשונה אינה\u0004 נחשבת ל\u0003ביאה\u0004 — אם כן ה\u0003ביאה\u0004 ה\u0003שנייה נמי\u0004 \u0005[גם כן]\u0006 \u0003אינה ביאה.\u0004 ואילו חכמים סבורים שכיון שמחשיבים ביאת בן תשע כמאמר — יש כח לביאה אחת לחול אחר השניה.","ומעירים, כי לפי פירוש זה, \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא כ\u0004דעת \u0003בן עזאי. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003בן עזאי אומר: יש מאמר אחר מאמר,\u0004 שתופס ופועל המאמר \u0003בשני יבמין ויבמה אחת,\u0004 שאם עשו בה שניהם מאמר, תפסו המאמרים של שניהם, ונאסרה לשניהם, כי מאחר שיש לכל אחד מהם זיקה בה — מאמר שניהם תופס.","\u0003ואין\u0004 תופס \u0003מאמר אחר מאמר בשתי יבמות ויבם אחד,\u0004 שהרי לא היתה ליבם זיקה גמורה בשתיהן, וכיון שעשה מאמר באחת — כל זיקת הייבום נגמרה על ידי כך. ואילו במשנתנו המסקנה שביאת בן תשע שנים בשתי יבמות נחשבת, וכיון שביאת בן תשע דינה כמאמר, משמע שסבור התנא שחל מאמר אחר מאמר אף ביבם אחר.","\u0003בן תשע שנים ויום אחד שבא על יבמתו ומת — חולצת\u0004 אותה יבמה, \u0003ולא מתייבמת.\u0004 אם \u0003נשא\u0004 הקטן \u0003אשה\u0004 סתם \u0003ומת — הרי זו פטורה\u0004 מייבום וחליצה, שהרי אין נישואין לקטן. \u0003בן תשע שנים ויום אחד שבא על יבמתו, ומשהגדיל נשא אשה אחרת, ומת\u0004 בלא בנים, \u0003אם לא ידע\u0004 (בעל) \u0003את הראשונה משהגדיל,\u0004 אלא רק בזמן שהיה קטן — \u0003הראשונה חולצת ולא מתייבמת,\u0004 שהרי היא כיבמה שבא עליה קטן, \u0003והשנייה — או חולצת או מתייבמת,\u0004 משום שהיתה אשתו גמורה.","\u0003ר' שמעון אומר: מייבם לאי זו שירצה, וחולץ לשנייה.\u0004 ומעירים: \u0003אחד\u0004 דינו של מי \u0003שהוא בן תשע שנים ויום אחד, ואחד\u0004 מי \u0003שהוא בן עשרים שלא הביא שתי שערות,\u0004 שדינו לענין זה כקטן בן תשע, שביאתו ביאה שאינה גמורה.","\u0003אמר רבא: הא דאמור רבנן\u0004 \u0005[זה שאמרו חכמים]\u0006 ש\u0003זיקת שני יבמין,\u0004 כגון יבמה שעשה בה אחד מן האחים מאמר, ומת, שלגבי האח הנותר, או האחים הנותרים, יש עליה זיקת ייבום משום שני אחים שמתו, \u0003מיחלץ חלצה יבומי לא מיבמה\u0004 \u0005[חולצת\u0006 ו\u0005אינה מתייבמת],\u0006 \u0003לא תימא\u0004 \u0005[תאמר]\u0006 שזה רק \u0003היכא דאיכא\u0004 \u0005[היכן שיש]\u0006 \u0003צרה, דאיכא למגזר\u0004 \u0005[שיש\u0006 מקום \u0005לגזור]\u0006 \u0003משום צרה,\u0004 שהצרה הלא מעיקר הדין מתייבמת, ואם היתה גם זו שעשה בה האח השני מאמר מתייבמת, היו טועים ומייבמים שתי צרות מבית אחד.","וראיה לדבר — \u0003דהא הכא ליכא\u0004 \u0005[שהרי כאן\u0006 במשנה \u0005אין]\u0006 \u0003צרה\u0004 ומדובר באשה אחת בלבד, ויבמה זו שנבעלה לבן תשע שיש עליה איפוא גם זיקה מבעלה הראשון וגם זיקה מהיבם הקטן (שהרי ביאתו היא כמאמר), ובכל אופן \u0003מיחלץ חלצה, יבומי לא מיבמה\u0004 \u0005[חולצת\u0006 ו\u0005אינה מתייבמת].\u0006","שנינו במשנה: קטן בן תשע ש\u0003נשא אשה ומת\u0004 — הרי זו פטורה מן הייבום ומן החליצה. ומעירים: \u0003תנינא להא דתנו רבנן\u0004 \u0005[שנינו\u0006 איפוא במשנה \u0005את זו ששנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003שוטה וקטן שנשאו\u0004 נשים \u0003ומתו — נשותיהן פטורות מן החליצה ומן הייבום,\u0004 שאין נישואי קטן נחשבים כלל.","שנינו במשנה על \u0003בן תשע\u0004 שבא על יבמתו, ו\u0003משהגדיל\u0004 נשא אשה אחרת. ושואלים: \u0003ויעשו\u0004 את \u0003ביאת בן תשע\u0004 לפחות \u0003כמאמר בגדול, ו\u0004לפי זה \u0003תדחה\u0004 ה\u0003צרה מיבום,\u0004 שהרי היא צרת אשה שיש עליה זיקה משני יבמים! \u0003אמר רב: לא עשו ביאת בן תשע כמאמר בגדול\u0004 לכל דבר. \u0003ושמואל אמר: עשו ועשו. וכן אמר ר' יוחנן: עשו ועשו.\u0004","ושואלים, אם כן חוזרת השאלה למקומה, \u0003ויעשו\u0004 ביאת בן תשע כמאמר לכל דבר ומדוע מייבם את צרתה? ומשיבים: מחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 \u0003היא; הך תנא\u0004 \u0005[התנא הזה]\u0006 של \u0003ארבעה אחין\u0004 המדבר על אחד מהם שמת ועשה אחיו מאמר ומת גם הוא, שאין היבמה וצרתה מתייבמות לאחד האחים הנותרים, \u0003גזר משום צרה,\u0004 שלא יאמרו שתי יבמות מבית אחד מתייבמות, ולכן שתיהן חולצות.","\u0003ואשמעינן\u0004 \u0005[והשמיע לנו]\u0006 דין זה \u0003ב\u0004אח \u0003גדול\u0004 שעשה מאמר, \u0003והוא הדין\u0004 גם \u0003בקטן\u0004 שבא עליה. \u0003והאי\u0004 \u0005[וזה]\u0006 ש\u0003אמר גדול\u0004 דווקא — \u0003משום\u0004 ש\u0003בגדול קאי\u0004 \u0005[\u0006הוא \u0005עומד,\u0006 מדבר\u0005]\u0006 שם.","\u0003והאי תנא דהכא\u0004 \u0005[והתנא הזה של\u0006 משנתנו \u0005כאן]\u0006 \u0003סבירא ליה\u0004 \u0005[סבור]\u0006 ש\u0003עשו\u0004 את ביאת הקטן לגמרי כמאמר גדול, \u0003ולא גזר משום צרה,\u0004 אלא שהיא אסורה מצד עצמה שהיא אשת שני מתים, וצרתה מתייבמת. \u0003ואשמעינן\u0004 \u0005[והשמיע לנו]\u0006 דין זה \u0003בקטן, והוא הדין בגדול. והאי דקאמר\u0004 \u0005[וזה שאמר\u0006 את הדברים\u0005]\u0006 \u0003בקטן\u0004 — משום ש\u0003בקטן קאי\u0004 \u0005[עומד,\u0006 מדבר הוא\u0005].\u0006","מסופר: \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003ר' אלעזר אמר לשמעתא בי מדרשא\u0004 \u0005[את ההלכה\u0006 הזאת ב\u0005בית המדרש]\u0006 \u0003ולא אמרה משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוחנן\u0004 אלא סתם. \u0003שמע ר' יוחנן\u0004 שר' אלעזר לא אמר משמו \u0003איקפד\u0004 \u0005[הקפיד,\u0006 כעס עליו\u0005].\u0006 \u0003עול לגביה\u0004 \u0005[נכנסו אליו]\u0006 \u0003ר' אמי ור' אסי\u0004 לפייסו, שלא יקפיד על תלמיד אהוב זה. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003לא כך היה המעשה בבית הכנסת של טבריא\u0004 (טבריה) \u0003ב\u0004ענין \u0003נגר\u0004 (בריח) \u0003שיש בראשו גלוסטרא\u0004 (קצה, עיגול בולט), שהיתה שאלה אם מותר לטלטל אותו בשבת כדין כלי, או שאינו נחשב ככלי אלא כחומר גלם בלבד, ומוקצה הוא,","\u0003שנחלקו בו ר' אלעזר ור' יוסי,\u0004 וכל כך הקפידו זה על זה \u0003עד שקרעו ספר תורה בחמתן\u0004 (בכעסם). ותחילה מבררים את הלשון, ותוהים: \u0003קרעו סלקא דעתך\u0004 \u0005[עולה על דעתך]?!\u0006 וכי יעלה על הדעת שחכמים אלה יקרעו ספר תורה בכוונה?! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 \u0003שנקרע ספר תורה בחמתן,\u0004 שמחמת שהתווכחו כל כך ומשכו את הספר זה לצד זה וזה לצד זה, נקרע הספר. \u0003והיה שם ר' יוסי בן קיסמא\u0004 באותו מעמד, \u0003אמר: תמיה אני אם לא יהיה בית הכנסת זו\u0004 מקום של \u0003עבודה זרה.\u0004 שאם כך אירע בו — אין זה ראוי שיהיה זה מקום בית כנסת. \u0003וכן הוה\u0004 \u0005[וכך היה]\u0006 לבסוף. והביאו ר' אמי ור' אסי ברייתא זו לרמוז כמה ראוי להתרחק מן ההקפדה.","\u0003הדר איקפד טפי\u0004 \u0005[חזר\u0006 ר' יוחנן ו\u0005הקפיד יותר]\u0006 \u0003אמר: חברותא נמי\u0004 \u0005[חברות גם כן]\u0006 אתם עושים ביני ובינו?! שהרי שם מדובר בשני חכמים שווים זה לזה, ואילו ר' אלעזר תלמיד הוא.","\u0003עול לגביה\u0004 \u0005[נכנס אליו]\u0006 \u0003ר' יעקב בר אידי. אמר ליה\u0004 \u0005[לו],\u0006 נאמר: \u0003\"כאשר צוה ה' את משה עבדו כן צוה משה את יהושע וכן עשה יהושע לא הסיר דבר מכל אשר צוה ה' את משה\"\u0004 (יהושע יא, טו), \u0003וכי על כל דבר שאמר יהושע היה אומר להם: כך אמר לי משה? אלא יהושע\u0004 היה \u0003יושב ודורש סתם, והכל יודעין שתורתו של משה היא. אף ר' אלעזר תלמידך יושב ודורש סתם והכל יודעין כי\u0004 תורתו — מ\u0003שלך היא.\u0004 ונתפייס ר' יוחנן.","\u0003אמר להם\u0004 לר' אמי ור' אסי אחר כך, משנתפייס: \u0003מפני מה אי\u0004 (אין) \u0003אתם יודעין לפייס כבן אידי חברינו.\u0004 ושואלים: \u0003ור' יוחנן מאי טעמא קפיד כולי האי\u0004 \u0005[מה טעם הקפיד כל כך]\u0006 על דבר זה? ומשיבים, ש\u0003אמר רב יהודה אמר רב: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"אגורה באהלך עולמים\"\u0004 (תהלים סא, ה), \u0003וכי אפשר לו לאדם לגור בשני עולמים\u0004 בבת אחת? \u0003אלא אמר דוד לפני הקדוש ברוך הוא: רבונו של עולם, יהי רצון\u0004"],["\u0003שיאמרו דבר שמועה\u0004 והלכה \u0003מפי בעולם הזה,\u0004 כאשר אהיה אני בעולם אחר. ש\u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יוחי: כל תלמיד חכם שאומרים דבר שמועה מפיו בעולם הזה שפתותיו דובבות\u0004 (רוחשות כאילו הוא מדבר) בהיותו \u0003בקבר.\u0004 ו\u0003אמר ר' יצחק בן זעירא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003שמעון נזירא: מאי קראה\u0004 \u0005[מהו הכתוב]\u0006 המלמד על כך — שנאמר: \u0003\"וחכך כיין הטוב הולך לדודי למישרים דובב שפתי ישנים\"\u0004 (שיר השירים ז, י) —","\u0003ככומר\u0004 (כערימה) \u0003של ענבים\u0004 שמניחים אותה להתחמם לפני הדריכה; \u0003מה כומר של ענבים, כיון שמניח אדם אצבעו עליו — מיד דובב,\u0004 שהיין מבצבץ לצאת, והכל מתנועע בו, \u0003אף תלמידי חכמים, כיון שאומרים דבר שמועה מפיהם בעולם הזה שפתותיהם דובבות בקבר.\u0004 ולכן רצה ר' יוחנן שתיאמר שמועה בשמו, כדי שיהיו לו חיי עולמים. שנינו במשנה: \u0003אחד בן תשע שנים\u0004 ויום אחד ואחד בן עשרים שלא הביא שערות, שווים לענין ייבום, שאין ביאתם ביאה גמורה. \u0003ורמינהו\u0004 \u0005[ומטילים,\u0006 מראים סתירה\u0005],\u0006 ממה ששנינו: \u0003בן עשרים שנה שלא הביא שתי שערות — יביאו ראיה שהוא בן עשרים, והוא הסריס\u0004 שמדובר בו, ולענין ייבום — \u0003לא חולץ ולא מייבם.\u0004","","וכיוצא בו: \u0003בת עשרים שנה שלא הביאה שתי שערות — יביאו ראיה שהיא בת עשרים, והיא האילונית — לא חולצת ולא מתייבמת.\u0004 ואם כן, הרי אין הדברים דומים, שביאת בן תשע שנים בכל זאת נחשבת במקצת, ואילו הסריס אין ביאתו חשובה כלל, שהרי גם אינו חולץ!","ומשיבים: \u0003הא אתמר עלה\u0004 \u0005[הרי\u0006 כבר \u0005נאמר על כך]\u0006 \u0003אמר רב שמואל בר יצחק אמר רב: והוא שנולדו לו\u0004 בזה שהיה בן עשרים \u0003סימני סריס\u0004 אחרים. ולכן אין ביאתו נחשבת, ואילו במשנתנו מדובר במי שלא הביא סימני בגרות עד לגיל מאוחר. \u0003אמר רבא: דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 שכך יש להבין, \u0003דקתני\u0004 \u0005[ששנה\u0006 שם\u0005]:\u0006 \u0003והוא הסריס. שמע מינה\u0004 \u0005[למד מכאן]\u0006 שמדובר פה במי שברור לנו שהוא סריס.","ושואלים לעצם ההלכה: \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003לא נולדו לו סימני סריס, עד כמה\u0004 שנים מחשיבים אותו כקטן? \u0003תני דבי\u0004 \u0005[שנה\u0006 החכם מ\u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' חייא: עד רוב שנותיו,\u0004 כלומר, עד שנעשה בן שלושים וחמש שנים ויום אחד (שהן מחצית שבעים שנה — שנות חיי אדם רגיל, ומשהו).","באותו נושא מסופר: \u0003כי אתו לקמיה\u0004 \u0005[כאשר היו באים לפני]\u0006 \u0003רבא\u0004 לשאול על מי שהגיע לשנים הראויות לבגרות ולא נראו בו סימני בגרות, \u0003אי כחוש\u0004 \u0005[אם\u0006 היה הנדון \u0005רזה]\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003זילו אבריוהו\u0004 \u0005[לכו\u0006 ו\u0005הבריאו,\u0006 השמינו \u0005אותו]\u0006 קודם שיבוא לדון בעניינו ולקבוע בו הלכה. \u0003ואי בריא\u0004 \u0005[ואם\u0006 היה \u0005שמן]\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003זילו אכחשוהו\u0004 \u0005[לכו\u0006 ו\u0005הרזו אותו],\u0006 \u0003דהני סימנין\u0004 \u0005[שסימנים אלה],\u0006 השערות, שהן סימני בגרות, \u0003זמנין דנתרי\u0004 \u0005[פעמים ש\u0006הן \u0005נושרות]\u0006 \u0003מחמת כחישותא\u0004 \u0005[רזון],\u0006 \u0003וזמנין דנתרי\u0004 \u0005[ופעמים ש\u0006הן \u0005נושרות]\u0006 \u0003מחמת בריותא\u0004 \u0005[שומן],\u0006 ושמא אם יגיע למצב גופני ראוי יתברר שיש בו סימני בגרות, ולא יצטרכו לדונו כסריס.","","\u0003נושאין על האנוסה ועל המפותה\u0004 שאם אנס או פיתה אשה רשאי לשאת אחת מקרובותיה (כגון אחותה או אמה), אולם \u0003האונס ו\u0004כן \u0003המפתה\u0004 קרובה של אשתו \u0003על\u0004 אשתו \u0003הנשואה\u0004 לו — \u0003חייב\u0004 עליה משום ערוה. \u0003נושא אדם אנוסת אביו, ומפותת אביו, אנוסת בנו ומפותת בנו. ר' יהודה אוסר באנוסת אביו ומפותת אביו.\u0004 מעירים: \u0003תנינא להא דתנו רבנן\u0004 \u0005[שנינו\u0006 במשנה \u0005את זו ששנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003אנס אשה — מותר לישא\u0004 את \u0003בתה, נשא אשה — אסור לישא\u0004 את \u0003בתה. ורמינהו\u0004 \u0005[ומטילים,\u0006 מראים סתירה\u0005],\u0006 ממה ששנינו: \u0003הנטען מן האשה,\u0004 כלומר, מי שיצאה עליו שמועה שבא על אשה מסויימת — \u0003אסור באמה ובבתה ובאחותה!\u0004 ומשיבים: דבר זה אסור רק \u0003מדרבנן\u0004 \u0005[מדברי סופרים],\u0006 שגזרו שמא אם ישא את אחת מקרובותיה יבוא לידי איסור ערוה ממש באשה זו שמעתה תהיה קרובת אשתו.","","ושואלים: \u0003וכל היכא\u0004 \u0005[מקום]\u0006 \u0003דאיכא איסורא מדרבנן\u0004 \u0005[שיש איסור\u0006 על כל פנים \u0005מדברי סופרים]\u0006 \u0003תני\u0004 \u0005[שונה\u0006 התנא\u0005]\u0006 \u0003נושאין,\u0004 שפירושו \u0003לכתחלה?!\u0004 הלא אם הדבר אסור, אם כי רק מדברי סופרים, היה עליו לפחות לנסח באופן אחר: ואם עבר ונשא אין מוציאים! ומשיבים: \u0003כי תנן מתניתין\u0004 \u0005[כאשר שנינו\u0006 ב\u0005משנתנו]\u0006 בלשון לכתחילה — מדובר שנושאין על האנוסה רק \u0003לאחר מיתה\u0004 שלה, שלאחר מיתה לא גזרו.","ושואלים למקור ההלכה שבמשנה: \u0003מנא הני מילי\u0004 \u0005[מניין הדברים הללו]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \u0003בכולן\u0004 בעריות שנאמרו שם, \u0003נאמר\u0004 בהם לשון \u0003שכיבה, וכאן\u0004 באשה ובתה ובשאר קרובות שנאסרו מחמת נישואי אשתו, \u0003נאמר\u0004 לשון \u0003קיחה, לומר לך: דרך ליקוחין\u0004 (נישואין) \u0003אסרה תורה.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: אלא מעתה,\u0004 אם אתה מדייק כך בלשון, \u0003גבי אחותו דכתיב\u0004 \u0005[שנאמר]\u0006 בה: \u0003\"\u0004ו\u0003איש אשר יקח את אחתו בת אביו או בת אמו\"\u0004 (ויקרא כ, יז), \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר שרק \u0003דרך קיחה הוא\u0004 ש\u0003אסור\u0004 ו\u0003דרך שכיבה שרי\u0004 \u0005[מותר]?!\u0006 \u0003אמר ליה\u0004 \u0005[לו],\u0006 כך יש להבין: \u0003ליקוחין כתיבי\u0004 \u0005[אמורים]\u0006 \u0003בתורה סתם\u0004 וזו היא לשון כללית, ואנחנו דנים לפי הענין: \u0003הראוי ל\u0004פרשו בלשון \u0003קיחה\u0004 של נישואין — מפרשים אותו בדרך זו, בתורת \u0003קיחה, הראוי לשכיבה\u0004 אין הכוונה בו קיחה של נישואין, אלא רק לשון נקיה, הרי פירושו: \u0003שכיבה.\u0004","","","\u0003רבא אמר:\u0004 דין זה שאם \u0003אנס אשה מותר לישא\u0004 את \u0003בתה\u0004 נלמד \u0003מהכא\u0004 \u0005[מכאן]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 בפסוק אחד: \u0003\"ערות בת בנך או בת בתך לא תגלה\"\u0004 (שם יח, י), ולכאורה אפשר לדייק: \u0003הא\u0004 \u0005[הרי]\u0006 את \u0003בת בנה דידה\u0004 \u0005[שלה]\u0006 של אשתך, \u0003ו\u0004את \u0003בת בתה דידה\u0004 \u0005[שלה]\u0006 — \u0003גלי\u0004 \u0005[\u0006אתה יכול \u0005לגלות]\u0006 ואין איסור בדבר,","\u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בפסוק אחר \u0003\"ערות אשה ובתה לא תגלה את בת בנה ואת בת בתה לא תקח\u0004 לגלות ערותה שארה הנה זמה היא\u0003\"\u0004 (שם יז), \u0003הא כיצד\u0004 אתה מיישב את ההבדל בדיוקי הכתובים? ההסבר לכך הוא: \u0003כאן,\u0004 שמותר, מדובר \u0003באונסין,\u0004 שאם אנס אשה יכול לשאת את בת בתה או את בת בנה, כל עוד הם אינם גם בני בניו שלו, ו\u0003כאן,\u0004 שאסור הדבר, מדובר \u0003בנשואין.\u0004","ושואלים: אולי \u0003איפוך אנא\u0004 \u0005[אהפוך אני]\u0006 ואומר שבאונסין אסור ובנישואין מותר? ומשיבים: בענין \u0003עריות \"שאר\" כתיב בהו\u0004 \u0005[נאמר בהם]\u0006 ו\u0003בנשואין איכא\u0004 \u0005[יש]\u0006 \u0003שאר,\u0004 שהבעל והאשה נעשים קרובים וכבשר אחד על ידי הנישואין, ואילו \u0003באונסין ליכא\u0004 \u0005[אין]\u0006 \u0003שאר,\u0004 ובכתוב שנאמר בו האיסור, מפורש שהוא השארות. שנינו במשנה כי \u0003ר' יהודה אוסר באנוסת אביו\u0004 ומפותת אביו. \u0003אמר רב גידל אמר רב: מאי טעמא\u0004 \u0005[מהו הטעם]\u0006 של \u0003ר' יהודה — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא יקח איש את אשת אביו ולא יגלה כנף אביו\"\u0004 (דברים כג, א), והוא מפרש: \u0003כנף שראה אביו\u0004 בכל אופן \u0003לא יגלה.\u0004","","\u0003וממאי\u0004 \u0005[וממה]\u0006 יודעים אנו ש\u0003באנוסה\u0004 ולא בנשואה \u0003כתיב\u0004 \u0005[נאמר\u0006 כתוב זה\u0005] —\u0006 \u0003דכתיב מעילויה דקרא\u0004 \u0005[שנאמר מעל,\u0006 קודם, \u0005לפסוק\u0006 זה\u0005]\u0006 בדין האונס: \u0003\"ונתן האיש השכב עמה לאבי הנער חמשים כסף\"\u0004 (שם כב, כט).","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם משיבים על ראיה זו — \u0003אי הוה סמיך ליה כדקאמרת\u0004 \u0005[אילו היה סמוך לו\u0006 ממש היה זה \u0005כמו שאתה אומר],\u0006 \u0003השתא דלא סמיך ליה\u0004 \u0005[עכשיו שאינו סמוך לו]\u0006 לגמרי ויש פסוק מפריד באמצע, \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 הביטוי \"לא יגלה כנף אביו\" לענין אחר, לכפי שאמר \u0003רב ענן.\u0004 ש\u0003אמר רב ענן אמר שמואל: בשומרת יבם של אביו,\u0004 שעדיין לא ייבם אותה, \u0003הכתוב מדבר. ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"כנף אביו\" — כנף הראוי לאביו,\u0004 אותו \u0003לא יגלה.\u0004","ושואלים: לדעת חכמים לשם מה צריך הכתוב לומר איסור נוסף זה של \"לא יגלה כנף אביו\" — \u0003ותיפוק ליה\u0004 \u0005[ויצא,\u0006 ילמד \u0005לו]\u0006 שהיא אסורה עליו, גם בלאו הכי \u0003משום דודתו,\u0004 שהרי היתה קודם אשת דודו (אחי אביו)! ומשיבים: בא כתוב זה \u0003לעבור עליה בשני לאוין,\u0004 גם משום דודתו, וגם משום \"לא יגלה כנף אביו\". ושואלים: \u0003ותיפוק ליה\u0004 \u0005[וייצא לו]\u0006 שיש בכך שני לאוין, מצד אחר — גם \u0003משום\u0004 שהיא \u0003יבמה\u0004 שנבעלת \u0003לשוק,\u0004 לאדם שאיננו יבמה! ומשיבים: בא הכתוב ללמד \u0003לעבור עליה בשלשה לאוין:\u0004 משום יבמה לשוק, משום דודתו, ומשום \"לא יגלה\". \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שמדובר כאן \u0003לאחר מיתה\u0004 של אביו, ולא היו לו עוד אחים, שאיסור יבמה לשוק אין כאן, אבל היא אסורה הן משום דודתו והן משום כנף שהיתה ראויה לאביו.",""],["כיון שהזכרנו כאן את ההיתר לשאת את אנוסת אביו ומפותת אביו, עלול הדבר לגרום לצירופים משפחתיים מוזרים, ומביאים כמה חידות הקשורות ביחסים וצירופים שכאלה. כגון החידה ששואלת אשה: \"יש לי \u0003אח מאב ולא מאם, והוא בעלה דאם\u0004 \u0005[של אמי],\u0006 \u0003ואנא ברתה דאנתתיה\u0004 \u0005[ואני בת אשתו].\u0006\" \u0003אמר רמי בר חמא:\u0004 ש\u0003לא כ\u0004דעת \u0003ר' יהודה דמתניתין\u0004 \u0005[ש\u0006ב\u0005משנתנו],\u0006 אבל לדעת חכמים ייתכן הדבר, שאם אנס אדם אשה והוליד ממנה בת, ובנו של אותו איש נשא את אנוסת אביו, הרי יכולה הבת הזו לומר על בעל אמה שהוא אחיה מאב ולא מאם, והוא בעלה של אמה, והיא בת אשתו.","חידה אחרת היא: \u0003\"אח\u0004 שלי \u0003הוא, וברי\u0004 \u0005[ובני]\u0006 \u0003הוא, אחתיה אנא\u0004 \u0005[אחותו אני]\u0006 \u0003דהאי דדרינא אכתפאי\u0004 \u0005[של זה שאני נושאת על כתפיי]\u0006\u0003\".\u0004 כיצד יכול להיות הדבר? — \u0003משכחת לה\u0004 \u0005[\u0006יכול \u0005אתה למצוא\u0006 דבר \u0005כזה]\u0006 \u0003בגוי הבא על בתו\u0004 והוליד ממנה בן, שהוא איפוא גם אחיה וגם בנה (ונקטו דוגמא בגוי — משום שלא רצו אפילו לדמיין תיאור מקרה כגון זה בישראל).","חידה אחרת: \u0003\"שלמא לך ברי, בת אחתיך אנא\u0004 \u0005[שלום לך בני, בת אחותך אני]\u0006 \u0003\"\u0004\u0005 — \u0006\u0003משכחת לה\u0004\u0005 [מוצא אתה אותה]\u0006 \u0003בגוי הבא על בת בתו\u0004 והוליד ממנה בן, שהבן של אותה נכדה הוא גם כן קרוב מצד אחי אמה, והיא בת אחותו.","חידה אחרת: \u0003\"דלאי דדלו דוולא ליפול בכו סתר פתר\u0004 \u0005[\u0006הפועלים \u0005הדולים דליים\u0006 להשקות השדות, \u0005שתיפול לכם\u0006 חידה \u0005מסותרת לפתור\u0006 אותה\u0005]:\u0006 \u0003דהאי דדרינא הוא בר, ואנא ברת אחוה\u0004 \u0005[שזה שאני נושאת\u0006 על כתפיי \u0005הוא בן\u0006 שלי, \u0005ואני בת אחיו]\u0006 \u0003\".\u0004 ופתרונו — \u0003משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 \u0003בגוי הבא על בת בנו,\u0004 שהילד שנולד הוא מצד אחד בן אמו, ומהצד האחר הוא דוד של אמו.","חידה אחרת: \u0003\"בייא בייא\u0004 \u0005[וי וי]\u0006 \u0003מאח, והוא אב, והוא בעל, והוא בר\u0004 \u0005[בן]\u0006 ה\u0003בעל והוא בעלה דאם\u0004 \u0005[של אמי],\u0006 \u0003ואנא ברתה דאיתתיה\u0004 \u0005[ואני בת אשתו],\u0006 \u0003ולא יהיב פיתא לאחוה יתמי בני ברתיה\u0004 \u0005[ואיננו נותן אוכל לאחיו היתומים בני בתו]\u0006 \u0003\".\u0004 וכיצד יכול להיות מצב כזה? — \u0003משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 \u0003בגוי הבא על אמו והוליד ממנה בת,\u0004 ובת זו היא איפוא גם אחותו וגם בתו, \u0003וחזר ובא על אותה בת,\u0004 על בתו שלו שהוליד, שהיא אחותו, \u0003וחזר זקן,\u0004 אביו של אותו אדם, \u0003ובא\u0004 גם הוא \u0003עליה\u0004 על הבת ההיא \u0003והוליד ממנה בנים.\u0004","ואותה בת היא איפוא גם אשתו של בעלה־אביה, ואביה־בעלה הוא גם בעל אמה, והוא, בעלה, גם בן בעלה (בן הזקן), ואחיו של בעלה (בני הזקן) שנולדו ממנה הם בני בתו, חידה אחרת: \u0003\"אנא ואת\u0004 \u0005[אני ואתה] —\u0006 \u0003אחי\u0004 \u0005[אחים],\u0006 \u0003אנא ואבוך\u0004 \u0005[אני ואביך] —\u0006 \u0003אחי\u0004 \u0005[אחים],\u0006 \u0003אנא ואמך\u0004 \u0005[אני ואמך] —\u0006 \u0003אחי\u0004 \u0005[אחים]\u0006 \u0003\"\u0004וכיצד יכול להיות הדבר? — \u0003משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 \u0003בגוי הבא על אמו והוליד ממנה שתי בנות, וחזר ובא על אחת מהן, והוליד ממנה בן, וקריא ליה אחתיה דאימא\u0004 \u0005[וקוראת לו\u0006 לבן \u0005אחות אמו]\u0006 \u0003וקאמרה ליה הכי\u0004 \u0005[ואומרת לו כך]\u0006 שהיא גם אחותו מאב וגם אחות אמו מאב אחד, וגם אחות אביו מאם אחת.","ועוד חידה: \u0003\"אנא ואת\u0004 \u0005[אני ואתה] —\u0006 \u0003בני אחי\u0004 \u0005[אחים],\u0006 \u0003אנא ואבוך\u0004 \u0005[אני ואביך] —\u0006 \u0003בני אחי\u0004 \u0005[אחים],\u0006 \u0003אנא ואמך\u0004 \u0005[אני ואמך] —\u0006 \u0003בני אחי\u0004 \u0005[בני אחים]\u0006 \u0003\",\u0004 כיצד זה יכול לקרות? \u0003הא בהיתרא נמי משכחת לה\u0004 \u0005[\u0006דבר כגון \u0005זה מוצא אתה גם בהיתר],\u0006 כלומר, בלא איסור עריות — \u0003כגון ראובן שיש לו שתי בנות, ואתא\u0004 \u0005[ובא]\u0006 \u0003שמעון\u0004 אחיו \u0003ונסב חדא מינייהו\u0004 \u0005[ונשא אחת מהן],\u0006 \u0003ואתא בר\u0004 \u0005[ובא בן]\u0006 של \u0003לוי\u0004 שהוא אח שלישי \u0003ונסב חד מינייהו\u0004 \u0005[ונשא\u0006 גם הוא \u0005אחת מהם]\u0006 שהיא בת דודו, \u0003וקאמר ליה\u0004 \u0005[ואומר לו]\u0006 \u0003בריה\u0004 \u0005[בנו]\u0006 של \u0003שמעון לבר בריה\u0004 \u0005[לבן בנו]\u0006 של \u0003לוי\u0004 שהרי הם גם בני אחים (בני דודים מאם), וגם הוא ואביו בני אחים (בני דודים מאב), וגם הוא ואמו בני אחים (בני דודים מהאב).","\u0003הגיורת שנתגיירו בניה עמה — לא חולצין ולא מייבמין\u0004 זה לזה, ו\u0003אפילו\u0004 היתה \u0003הורתו\u0004 (הריונו) \u0003של ראשון שלא בקדושה\u0004 של קהל קודש בישראל \u0003ולידתו בקדושה\u0004 שאמו ילדה אותו כשהיתה כבר יהודיה, \u0003והשני הורתו ולידתו בקדושה\u0004 — אינם נחשבים אחים, שכיון שהתגייר אפילו אחד מהם נחשב כאילו נולד מחדש ואין לו כל קירבה עם אחיו. \u0003וכן\u0004 הדין בענין \u0003שפחה שנשתחררו בניה עמה,\u0004 שגם הם אינם נחשבים כקרובים זה לזה.","מסופר: \u0003בני יודן אמתא\u0004 \u0005[השפחה]\u0006 \u0003אשתחרור\u0004 \u0005[השתחררו],\u0006 \u0003שרא להו\u0004 \u0005[התיר להם]\u0006 \u0003רב אחא בר יעקב למינסב נשי דהדדי\u0004 \u0005[לשאת\u0006 את \u0005הנשים,\u0006 זו \u0005של זה ו\u0006זו \u0005של זה]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: והא\u0004 \u0005[והרי]\u0006 \u0003רב ששת אסר\u0004 בכגון זה! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הוא אסר ואנא שרינא\u0004 \u0005[ואני מתיר],\u0006 כלומר, אני חולק עליו בזה.","ומסבירים: אם היו שני המשוחררים או (הגרים) אחים \u0003מן האב ולא מן האם — כולי עלמא לא פליגי דשרי\u0004 \u0005[הכל אינם חולקים שמותר],\u0006 שאין לגר קירבה מן האב, שודאי אינו מתייחס עוד לבית אביו. ואם היו אחים \u0003מן האם\u0004 בלבד \u0003ולא מן האב — כולי עלמא לא פליגי דאסיר\u0004 \u0005[הכל אינם חולקים שאסור].\u0006","\u0003כי פליגי\u0004 \u0005[כאשר נחלקו],\u0006 הרי זה כשהם אחים \u0003מן האב ומן האם: מאן דשרי\u0004 \u0005[מי שמתיר]\u0006 אומר: \u0003בתר אבא שדינן\u0004 \u0005[אחר האב אנו מטילים,\u0006 מייחסים\u0005]\u0006 אותם, \u0003דהא \"בני פלניא\" קרו להו\u0004 \u0005[שהרי \"בני פלוני\" קוראים להם],\u0006 וכיון שכך, יודעים הכל שהם נחשבים עכשיו כזרים זה לזה ואין מקום לגזור איסור עליהם מחשש שיבואו להחליפם באחרים ולהתיר יותר מזה. \u0003ו\u0004אילו \u0003רב ששת\u0004 סבור: כי \u0003קרו להו נמי\u0004 \u0005[קוראים להם גם כן]\u0006 \u0003\"בני פלונית\"\u0004 ויודעים הכל שהם אחים גם מן האם.","\u0003ואיכא דאמר\u0004 \u0005[ויש\u0006 מי \u0005שאומר]\u0006 שבנוסח אחר היו הדברים: \u0003פליג\u0004 \u0005[חולק]\u0006 \u0003רב אחא בר יעקב אפילו באחין מן האם, ומאי טעמא\u0004 \u0005[ומה טעם]\u0006 דבריו? — שלשיטתו \u0003גר שנתגייר כקטן שנולד דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 וכל יחסי הקירבה הקודמים שלו, אינם נחשבים עוד.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003הגיורת שנתגיירו בניה עמה — לא חולצין ולא מייבמין. מאי טעמא\u0004 \u0005[מה הטעם],\u0006 \u0003לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003משום דאסירי\u0004 \u0005[ש\u0006הם \u0005אסורים]\u0006 זה באשת זה ולכן אינם מייבמים, שאין בהם מצוות ייבום, ולא בטל מהם איסור אשת אח! ומשיבים: \u0003לא,\u0004 הכוונה היא ש\u0003אינה\u0004 (שאין) אשת אחד מהם \u0003בתורת חליצה וייבום\u0004 כלל, שאינה נקראת אשת אחיו, \u0003ושריא לעלמא\u0004 \u0005[ו\u0006לכן \u0005מותרת לעולם]\u0006 לכל אדם אחר. \u0003ואינהו נמי שרו\u0004 \u0005[והם גם כן מותרים]\u0006 זה באשתו של זה.","ומקשים: \u0003והא קתני\u0004 \u0005[והרי שנה]\u0006 \u0003\"אפילו\"\u0004 (\"אפילו הורתו של ראשון שלא בקדושה\"), \u0003אי אמרת בשלמא אסירי\u0004 \u0005[נניח אם אתה אומר\u0006 שהם \u0005אסורים]\u0006 לשאת זה את אשתו של זה משום איסור אשת אח, \u0003היינו דקתני\u0004 \u0005[זהו ששנה]\u0006 \u0003\"אפילו\",\u0004 ללמד: \u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003ראשון הורתו שלא בקדושה ולידתו בקדושה, והשני הורתו ולידתו בקדושה, ו\u0004לכן \u0003כ\u0004בנים של \u0003שתי אמהות דמו\u0004 \u0005[\u0006הם \u0005נחשבים],\u0006 \u0003אפילו הכי\u0004 \u0005[כך]\u0006 — \u0003אסירי\u0004 \u0005[אסורים].\u0006 \u0003אלא אי אמרת שרו\u0004 \u0005[אם אומר אתה\u0006 ש\u0005מותרים],\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 מקום לומר \u0003\"אפילו\"?\u0004","ומשיבים: \u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 \u0003דתרוייהו\u0004 \u0005[ששניהם]\u0006 \u0003לידתן בקדושה, ואתי לאחלופי\u0004 \u0005[ויבואו,\u0006 עלולים, \u0005להחליפם]\u0006 \u0003בישראל\u0004 גמורים \u0003אפילו הכי\u0004 \u0005[כך] —\u0006 \u0003שרי\u0004 \u0005[מותר].\u0006","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003הכי נמי מסתברא דשרו\u0004 \u0005[כך גם כן מסתבר ש\u0006הם \u0005מותרים],\u0006 \u0003דקתני\u0004 \u0005[ששנה]\u0006 \u0003\"אפילו\". אי אמרת בשלמא שרו\u0004 \u0005[נניח אם אתה אומר\u0006 שהם \u0005מותרים]\u0006 זה באשתו של זה — \u0003היינו דקתני\u0004 \u0005[זהו ששנה]\u0006 \u0003\"אפילו\",\u0004 כלומר, \u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 \u0003דתרוייהו\u0004 \u0005[ששניהם]\u0006 \u0003לידתן בקדושה, דאתי לאחלופי\u0004 \u0005[שיבואו להחליפם]\u0006 \u0003בישראל\u0004 גמורים — \u0003אפילו הכי\u0004 \u0005[כך]\u0006 \u0003שרו\u0004 \u0005[\u0006הם \u0005מותרים].\u0006 \u0003אלא אי אמרת אסירי\u0004 \u0005[אם אומר אתה\u0006 שהם \u0005אסורים],\u0006 \u0003מאי\u0004 \u0005[מה\u0006 מקום\u0005]\u0006 ללשון \u0003\"אפילו\"?\u0004","ודוחים: מכאן אין ראיה, שהרי אפשר לפרש באופן אחר: \u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 שה\u0003ראשון הורתו שלא בקדושה ולידתו בקדושה, והשני הורתו ולידתו בקדושה,\u0004 ש\u0003כ\u0004בנים של \u0003שתי אמהות דמי\u0004 \u0005[\u0006הם \u0005נחשבים] —\u0006 \u0003אפילו הכי\u0004 \u0005[כך]\u0006 \u0003אסירי\u0004 \u0005[\u0006הם \u0005אסורים],\u0006 ואין, איפוא, להוכיח מכאן לצד זה או לצד אחר.","ומנסים להביא ראיות נוספות, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו: \u0003שני אחים תאומים גרים, וכן\u0004 עבדים \u0003משוחררים — לא חולצין ולא מייבמין\u0004 האחד את אשת אחיו, \u0003ואין חייבין\u0004 זה על אשת זה \u0003משום אשת אח. היתה הורתן שלא בקדושה ולידתן בקדושה — לא חולצין ולא מייבמין, אבל חייבין משום אשת אח. היתה הורתן ולידתן בקדושה — הרי הן כישראלים לכל דבריהן,\u0004 שחולצים ומייבמים וחייבים משום אשת אח. \u0003קתני מיהת\u0004 \u0005[שנינו על כל פנים]\u0006 ש\u0003אין חייבין משום אשת אח,\u0004 ונדייק מכאן: \u0003חיובא ליכא\u0004 \u0005[חיוב\u0006 מן התורה — \u0005אין כאן],\u0006"]]};
